int main() {
    HWND hwnd = GetForegroundWindow();
    int hook = SetWindowsHook(WHS_KEYBOARD, keyboard_callback);
    if (hook == 0) {
        std::cout << "Failed to set keyboard hook" << std::endl;
        return 1;
    }

