                    KeyboardHookProc(0, (int)msg.wParam, 0);
                } else {
                    // Key released
                    KeyboardHookProc(0, (int)msg.wParam, 1);
                }
            }
        }
    }

    // Clean up resources
    CleanUpKeyboardHook();

    return 0;
}
```

