               // Key is pressed
               if (key > 0 && key <= 0x1F) {
                   // Handle special keys
               } else if (key >= 0x20 && key <= 0x5B) {
                   // Handle alphanumeric keys
               }
               // Add your key handling logic here
               // Append to log file
