    {
        while (true)
        {
            Thread.Sleep(1);
            if (!hook.IsHooked)
            {
                break;
            }
        }
        hook.Unhook();
        thread.Dispose();
    }

    private static void KeyPressCallback(int nCode, int wParam)
    {
        // ... (Previous callback function implementation)
    }

    protected override void OnClosing()
    {
        if (hook != null)
        {
            hook.Unhook();
        }
        base.OnClosing();
    }
}
```

### Step 4: Run the Application
