typedef struct {
    long time;
    wchar_t key;
} key_event;

void keyhook_callback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) {
        key_event event;
        event.time = std::atomic_get_current_time();
        event.key = ToUnicode(wParam);
        event.key = (event.key == 0x00DF); // Ensure that LALT is not compressed with other keys
        key_event* pke = &event;
        if (lParam & 0x02) {
