    UninstallHook();
    return 0;
}

void UninstallHook() {
    if (hhook) {
        StartMessageLoop(hwnd, HCB_IDE_DEBUG, 0);
        hhook = 0;
        std::cout << "Keyboard hook removed." << std::endl;
    }
}
```

