    hook = SetWindowsHook(WH_KEYBOARD, KeyboardCallback);

    // Install keyboard hook
    if (hook == 0) {
        printf("Failed to install keyboard hook\n");
        return 1;
    }

    // Run the hook
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Uninstall the hook
    if (UnhookWindowsHook(hook)) {
        printf("Successfully uninstalled keyboard hook\n");
    } else {
        printf("Failed to uninstall keyboard hook\n");
    }

    fclose(logFile);
    return 0;
}
```

