    }

    // Set up the timer
    timerHandle = CreateTimer(nil, TimerCallback, NULL, 100, 0, 0);

    // Start the timer
    ResumeTimer(timerHandle);

    // Keep the main thread responsive
    while (true) {
        Sleep(100);
    }

    // Cleanup
    UninstallKeyboardHook();
    DeleteTimer(timerHandle);
    return 0;
}
