inline char KeyToChar(int key) {
    return (char)ToUnicode(key);
}

// Callback function
void KeyStrokeCallback(int nCode, int wParam, int lParam) {
    if (wParam == 0x0001) { // Key down
        KeyState key = {0, 0};
        // Get the key state
        key.key = GetKeyState(0x0000); // Check for all keys
        // Get the key code
        int keyID = GetKeyID(nCode);
        // Get the character
        char c = KeyToChar(key.key);
        // Print the key press
        cout << "Key pressed: " << c << endl;
        lastKey.key = keyID;
        lastKey.state = key.state;
    }
    return 0;
}

// Install the keyboard hook
int main() {
    // Check if the application has admin rights
    if (!IsUserAnAdmin()) {
        cout << "Error: Admin rights are required to hook the keyboard." << endl;
        return -1;
    }

    // Install the hook
    int hHook = SetWindowsHook(WH_KEYBOARD, KeyStrokeCallback);

    // Wait for key presses
    cout << "Press any key to continue..." << endl;
    while (true) {
        Sleep(100); // Prevent high CPU usage
    }

    // Remove the hook
    if (UnhookWindowsHook(hHook)) {
        cout << "Keyboard hook removed." << endl;
    } else {
        cout << "Failed to remove hook." << endl;
    }

    return 0;
}
```

