   void hookKeyboard() {
       // Handle to store the hook
       HHOOK hKeyboardHook = 0;

       // Callback function prototype
       DWORD WINAPI keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
           // Handle key events
           // Return 0 if the hook is not handled
           return 0;
       }

       // Set up the hook
       hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);

       // If hook installation fails, exit
       if (hKeyboardHook == 0) {
           printf("Failed to install keyboard hook\n");
           return;
       }

       // Start the hook
       printf("Keyboard hook installed. Press Q to quit.\n");

       // Wait for key events
       while (true) {
