               // Process key up event
               // Optionally log key release
           }
           TranslateMessage(&msg);
           DispatchMessage(&msg);
       }

       // Uninstall the hook
       UnhookKeyboard(hKeyboardHook);
       printf("Keyboard hook removed.\n");
   }
