    KBDKEYSSTATE *keyState = (KBDKEYSSTATE*)lParam;
    bool isKeyDown = (wParam == KM_KEYDOWN);

    // Check if it's a keyboard event
    if (nCode == HCK_KEYDOWN || nCode == HCK_KEYUP)
    {
        // Determine if the key is pressed (down) or released (up)
