        printf("Logged: %s\n", logLine.c_str());
    } else {
        printf("Failed to write to file!\n");
    }
}

int main() {
    // Check if running in the main thread
    if (!IsThisThread()) {
        printf("This code must run in the main thread\n");
        return 1;
