    int currentHook = GetWindowHook(WH_KEYBOARD);
    if (currentHook != 0) {
        printf("Keyboard hook already active\n");
        return 1;
    }

    // Initialize the hook
    InitializeKeyboardHook();

    // Main loop to keep the application active
    while (true) {
        Sleep(500); // Prevent high CPU usage
    }

    return 0;
}
