        cout << "Error: Cannot create log file." << endl;
    }
}

void UninstallHook() {
    if (hKeyboardHook) {
        UnhookKeyboard(hwnd, hKeyboardHook);
        hKeyboardHook = NULL;
        isHooked = false;
    }
}

