        // Handle key release
        // Maybe just log the release
    }

    return 0;
}

// Install the hook
void InstallKeyboardHook() {
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);
    if (hKeyboardHook == 0) {
        printf("Keyboard hook installed successfully\n");
    } else {
        printf("Failed to install keyboard hook\n");
    }
}

// Remove the hook
