    {
        std::string input;
        std::getline(std::cin, input);
        if (input == "ESC")
        {
            break;
        }
    }

    UninstallKeyboardHook();
    std::cout << "Keyboard hook logging has been disabled." << std::endl;
    return 0;
}
```

