        buffer[6] = (state & 1) ? ',' : '.';
        buffer[7] = (state & 2) ? '<' : '-';
        buffer[8] = (state & 4) ? '=' : '+';
        buffer[9] = (state & 8) ? '(' : '-';
        buffer[10] = (state & 16) ? ')' : '/';
        buffer[11] = (state & 32) ? '\\' : '\\';
