    }

    cout << "Keyboard hook installed." << endl;
}

void cleanUp() {
    UnhookKeyboard();
    DestroyWindow(hwnd);
    cout << "Keyboard hook removed." << endl;
}

int main() {
    setupKeyboardHook();
    while (recording) {
        // Keep the application alive
        Sleep(1);
    }
    return 0;
}
