        buffer[15] = (state & 512) ? ' ' : '\t';
        buffer[16] = (state & 1024) ? '\n' : '\r';
        buffer[17] = (state & 2048) ? '\v' : '\f';
        buffer[18] = (state & 4096) ? '\b' : 0;
        buffer[19] = (state & 8192) ? 0 : 0;
        buffer[20] = (state & 16384) ? 0 : 0;
        buffer[21] = (state & 32768) ? 0 : 0;
        buffer[22] : 0;

        // Flush the buffer to file
