}

void setupKeyboardHook() {
    HWND hwnd = CreateWindow("MyApp", "Keyboard Hook", WS_VISIBLE | CS_OWNED, 0, 0, 0, 0, HWND_DESKTOP, WS_OVERLapped | WS_Hidden);
