                    }
                    // Other modifiers like Ctrl, Alt, etc.
                }
            }
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Unhook and clean up
    UnhookKeyboard(hhook);
    return 0;
}
```

**Step 5: Compile and Run**

Compile the code into an executable and run it. This program will log every key press to the console. Note that this should be used ethically and only for legitimate purposes, as keyboard hooking can be considered intrusive.

