    data->nTickCount = GetTickCount();
}

// Callback function for keyboard events
void KeyboardCallback(int nCode, int nVirtualKey, DWORD nState, KEYBOARD_EVENT_DATA *data)
{
    static bool isShiftDown = false;
    static bool isCtrlDown = false;

    // Check if this is a key press event
