        bool keyIsDown = (currentState & 0x1) != 0;

        // Determine if modifiers are pressed
        if (currentState & (1 << 0)) // Check if left shift is pressed
            isShiftDown = true;
        if (currentState & (1 << 2)) // Check if right shift is pressed
            isShiftDown = true;
        if (currentState & (1 << 16)) // Check if left control is pressed
            isCtrlDown = true;
        if (currentState & (1 << 17)) // Check if right control is pressed
            isCtrlDown = true;

        // Record the key and its state
        if (keyIsDown && !lastKey.nVirtualKey)
        {
            lastKey.nVirtualKey = nVirtualKey;
            lastKey.nState = nState;
            lastKey.nShift = isShiftDown;
            lastKey.nVirtualModifier = nVirtualModifier;
            lastKey.nTickCount = GetTickCount();
            cout << "Key pressed: " << char(nVirtualKey) << " (";
            if (isShiftDown) cout << "Shift ";
            if (isCtrlDown) cout << "Ctrl ";
            cout << "at time: " << lastKey.nTickCount << endl;
        }
    }
    else if (nCode == 1)
    {
        // Handle key release events if needed
        // This part can be omitted if you only need to log key presses
    }
}

// Release the hook and clean up
void ReleaseKeyboardHook()
{
    HWND hwnd = GetDesktopWindow();
    if (hwnd)
    {
        int hHook = GetWindowLong(hwnd, GW_HHOOK);
        if (hHook)
        {
            RemoveWindowHook(hwnd, WH_JOURNAL_KEY, hHook);
        }
    }
}

int main()
{
    // Initialize the hook
    InitializeKeyboardHook();

    // Keep the program running to capture keystrokes
    while (true)
    {
        // Sleep to save resources
        Sleep(500);
    }

    // Release the hook before exit
    ReleaseKeyboardHook();
    return 0;
}
```

