    // Check if the event is a keyboard event
    if (nCode != HCARDATA) {
        return CallNextHook(nCode, wParam, lParam);
    }

    // Check if it's a key press or release
    if (wParam == 0) {
        // Key down event
        // Check modifiers
        bool shift = (lParam & 0x20) ? true : false;
        bool ctrl = (lParam & 0x10) ? true : false;
        bool alt = (lParam & 0x08) ? true : false;

        // Record the key
        char key = static_cast<char>(wParam);
        cout << "Key down: " << key << " (Shift: " << shift << ", Ctrl: " << ctrl << ", Alt: " << alt << ")" << endl;
    } else {
        // Key up event
        char key = static_cast<char>(wParam);
        cout << "Key up: " << key << endl;
    }

    // Continue with the next hook
    return CallNextHook(nCode, wParam, lParam);
}
```

