            } else if (key >= 0x60 && key <= 0x7E) {
                ch = key - 0x60 + 0x20;
            }
            fprintf(logFile, "[%s %s]\n", "KeyDown", (isKeyDown ? static_cast<char>(ch) : ' '));
        }
    } else {
        // Handle key release
        // ...
    }
}

int main() {
