        // Key is released
        if (state == 0) {
            // Reset the key and modifiers
            lastKey = 0;
            isShift = false;
            isCtrl = false;
            isAlt = false;

            std::unique_lock lock(keyLoggerMutex);
            std::cout << "Key released: " << static_cast<int>(key) << std::endl;
        }
    }
}
