int main() {
    HWND hwnd = GetDesktopWindow();
    int (HWND) hHook = SetWindowsHook(hwnd, WH_KEYBOARD_LL);

    // Initialize an array to store the previous key state
    int (unsigned char) *prevKey = NULL;

    // Define the callback function
    auto callback = [](int code, int wParam, int lParam) -> int {
        if (code == HC_KEY) {
            // Check if it's a key down or up event
            bool isKeyDown = (lParam & 0x01) != 0;

            // Check if it's a keyboard event
            if (wParam == VK_KEY) {
                // Get the key number
