                // Check if it's a special key (like Shift, Ctrl, etc.)
                // by checking the top bits
                bool isAlt = (lParam & 0x100) != 0;
                bool isCtrl = (lParam & 0x200) != 0;
                bool isShift = (lParam & 0x400) != 0;

                // Get the previous key state
                if (prevKey) {
                    if (prevKey == key) {
                        // Key is being held down
                        isKeyDown = true;
                    } else {
                        // Key is being released
                        isKeyDown = false;
                    }
