                if (isKeyDown) {
                    std::cout << "Down" << std::endl;
                } else {
                    std::cout << "Up" << std::endl;
                }
            }
        }
        return CallNextHook(code, wParam, lParam);
    };

    // Start the hook
    hHook = SetWindowsHook(hwnd, callback);

    // Keep the console window open
    std::ofstream file("keylog.txt");
    std::cout << "Keyboard hook started. Press Ctrl+Alt+D to exit." << std::endl;

    while (true) {
        // Sleep to prevent high CPU usage
        Sleep(100);
    }

    // Release the hook and clean up
    UnhookKeyboard(hHook);
    std::cout << "Keyboard hook stopped." << std::endl;
    return 0;
}
```

