                else if (key->dwKey == VK_KEY_A) keyChar = 'A';
                // Add other shifted keys as needed
            } else {
                // Handle lowercase and other keys
                // For example, 'a' when not shifted
                if (key->dwKey == VK_KEY_A) keyChar = 'a';
            }
        }

        // Append to buffer or send to another application
        // For this example, just print to the console
