             return 2;
         }

         // Start the hook
         cout << "Keyboard hook installed." << endl;

         // Keep the console active
         while (true) {
             Sleep(500); // Sleep to prevent high CPU usage
         }

         // Release the hook
         UnhookWindowsHook(g_hHook);
         FreeLibrary(g_hInstance);
         cout << "Keyboard hook removed." << endl;

         return 0;
     }
     ```

4. **Running the Application**:
   - Compile the code into an executable and run it. It will log all keyboard events to the console.

5. **Testing the Application**:
