            if ((keyState >> 4) & 1) modifiers |= 0x0010; // Alt
        } else {
            modifiers = 0;
        }

        if (key != 0) {
            KeyEvent event;
            event.key = key;
            event.modifiers = modifiers;
            event.timestamp = time(nullptr);
