#include <windows.h>
#include <string>
#include <iostream>
```

### Step 2: Define the Callback Function
Define a function to handle keyboard events. This function will be called for each key press and release.
```cpp
int KeyProc(int hInstance, int thread, int msg, int key, int wparam, int lparam) {
    if (msg != WM_KEYDOWN && msg != WM_KEYUP) {
        return 0;
    }

    bool isKeyDown = (msg == WM_KEYDOWN);
    bool shiftDown = GetAsyncKeyState(VK_SHIFT);
    bool ctrlDown = GetAsyncKeyState(VK_CONTROL);
    bool altDown = GetAsyncKeyState(VK_MENU);

    if (isKeyDown) {
        // Record the key press
        char keyChar = GetKeyName(key);
        std::cout << "Key pressed: " << keyChar << " (";
        if (shiftDown) std::cout << "Shift";
        if (ctrlDown) std::cout << " Ctrl";
        if (altDown) std::cout << " Alt)";
        std::cout << std::endl;
    } else {
        // Record the key release
        std::cout << "Key released: " << keyChar << std::endl;
    }

    return 0;
}
```

### Step 3: Set Up the Keyboard Hook
In the main function, set up the keyboard hook and start the event loop.
```cpp
int main() {
    HHOOK hhook = 0;
    hhook = SetWindowsHook(WH_KEYBOARD_LL, KeyProc);

    // Keep the application running
    while (true) {
        Sleep(1);
    }

    // Uninstall the hook
    UnhookWindowsHook(hhook);
    return 0;
}
```

### Step 4: Compile and Run
Compile the code using a compiler (e.g., Visual C++ or Cygwin) and run it. This will log each key press to the console, including any modifiers like Shift, Ctrl, or Alt.

