        return;
    }

    // Check if the key was just pressed
    keyStates[key] = true;
    cout << "Key pressed: ";

    // Determine the character for output
    if (key >= 'A' && key <= 'Z') {
        cout << (char)key;
    } else if (key >= 'a' && key <= 'z') {
        cout << (char)(key + 32);
    } else if (key == 8) { // Backspace
        cout << "Backspace";
    } else if (key == 5) { // Space
        cout << " ";
    } else if (key == 0) { // Escape
        cout << "Escape";
    } else {
        cout << "Unknown key: " << key;
    }

    // Print modifiers
    cout << " (";
    if (modifiers) {
        if (modifiers & KM_KEYSHIFT) cout << "Shift";
        if (modifiers & KM_CTRL) cout << "Ctrl";
        if (modifiers & KM_ALTSYSS) cout << "Alt";
    }
    cout << ")" << endl;
}
```

### Step 3: Set Up the Keyboard Hook

In the main function, set up the keyboard hook using `SetWindowsHook` and start a loop to process events.

```cpp
int main() {
