#include <iostream>
#include <thread>
#include <queue>
#include <string>

using namespace std;

void KeyPressCallback(int nCode, int wParam, int lParam) {
    static int lastKey = 0;
    static int lastState = 0;
    static bool isRecording = false;

    if (wParam != WM_KEYDOWN) {
        if (isRecording) {
            if (wParam == WM_KEYUP) {
                isRecording = false;
            }
        }
        return;
    }

    if (!isRecording) {
        isRecording = true;
        cout << "Starting keyboard recording." << endl;
    }

    BYTE state = (BYTE)((lParam & 0x01) != 0 ? 1 : 0);
    BYTE previousState = lastState;
    lastState = state;

    if (state != previousState) {
        if (state) {
            cout << "Key: " << (char)wParam << " is PRESSED" << endl;
        } else {
            cout << "Key: " << (char)wParam << " is RELEASED" << endl;
        }
    }
}

