#include <windows.h>
#include <user32.h>
#include <iostream>
```

### Step 2: Define the Keyboard Hook Function
Define a function to handle keyboard events:
```cpp
void KeyPressed(unsigned char key, int modifiers) {
    std::cout << "Key Pressed: " << static_cast<char>(key) << " with modifiers: " << modifiers << std::endl;
}
```

### Step 3: Set Up the Keyboard Hook
Use `SetWindowsHook` to set a low-level keyboard hook:
```cpp
int main() {
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressed);

    // Keep track of the previous key state
    KBDKEYS previousKeyState = 0;
    int previousModifierState = 0;

    // Start the hook
    if (hKeyboardHook == 0) {
        std::cerr << "Failed to install keyboard hook" << std::endl;
        return 1;
    }

    while (true) {
        // Check for key events
        MSG msg;
        while (GetMessage(&msg, 0, 0, 0)) {
            if (msg.message == WM_KEYDOWN) {
                // Get the current key state
                KBDKEYS currentKeyState = GetAsyncKeyState(0x00);
                int shift = (currentKeyState & 0x1) ? 1 : 0;
                int ctrl = (currentKeyState & 0x2) ? 1 : 0;
                int alt = (currentKeyState & 0x4) ? 1 : 0;

                // Check if key is down
                if (currentKeyState != previousKeyState) {
                    if (currentKeyState & 0x0100) { // Shift pressed
                        shift = 1;
                    }
                    if (currentKeyState & 0x0200) { // Ctrl pressed
                        ctrl = 1;
                    }
                    if (currentKeyState & 0x0400) { // Alt pressed
                        alt = 1;
                    }

                    if (currentKeyState & 0x01000000) { // Modifier keys (e.g., Win, Alt)
                        // Handle extended modifiers
                    }

                    // Determine the key pressed
                    unsigned char key = static_cast<unsigned char>(msg.wParam);
                    KeyPressed(key, shift | ctrl | alt);
                    previousKeyState = currentKeyState;
                }
            }
        }
    }

    // Stop the hook and clean up
    UnhookKeyboard(hKeyboardHook);
    return 0;
}
```

