        } else if (msg.message == WM_KEYUP) {
            OnKeyUp(msg.wParam, key, isShift, isCtrl, isAlt, isCaps);
        }
    }

    // Uninstall the hook
    UnhookWindowsHook(hHook);
    return 0;
}
