                }
            }
        } else {
            // Handle key release, if needed
            cout << "Key Released" << endl;
        }
    }
}

int main() {
    // Set up the keyboard hook
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD, KeyPressCallback);

    // Attach the hook to the current thread
    if (hKeyboardHook == NULL) {
        cout << "Failed to set keyboard hook" << endl;
        return -1;
    }

    // Main loop to keep the program active
    while (true) {
        Sleep(1); // Use a short sleep to prevent high CPU usage
    }

    // Cleanup
    if (UnhookKeyboard(hKeyboardHook)) {
        cout << "Keyboard hook removed" << endl;
    }
    return 0;
}
