                if (wParam >= 0x30 && wParam <= 0x5A) {
                    key += 0x20;
                } else if (wParam >= 0x60 && wParam <= 0x69) {
                    key = static_cast<char>(wParam - 0x60 - 0x40);
                    if (shift) {
                        key += 0x30;
                    }
                }
            }
        }

        cout << "Key down: " << key << endl;
    } else if (nCode == HCN_KEYUP) {
        // Key released
        cout << "Key up: " << static_cast<char>(wParam) << endl;
    }
}

int main() {
    HHOOK hKeyboardHook = 0;
    HINSTANCE hInstance = GetWindowModuleHandle(nullptr);

    KeyHookProc *pfnHook = nullptr;

    hKeyboardHook = SetWindowsHook(hInstance, WH_KEYBOARD, pfnHook);

    if (hKeyboardHook == 0) {
        cout << "Failed to install keyboard hook" << endl;
        return 1;
    }

    // Wait for messages
    MSG msg;
    while (GetMessage(&msg, hInstance, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Uninstall the hook
    if (hKeyboardHook) {
        UnhookWindowsHook(hInstance, hKeyboardHook);
        hKeyboardHook = 0;
    }

    return 0;
}
```

