using namespace std;

static int WINAPI KeyPress(int nCode, int wParam, int lParam) {
    // Check if the event is a keyboard event
    if (wParam != WM_KEYDOWN && wParam != WM_KEYUP) return 0;

    // Get the keyboard state
    byte keyboardState = GetAsyncKeyState(0x01); // 0x01 for the keyboard
    bool isKeyDown = (keyboardState & 0x80000001) != 0;

    // Extract the key code
