        if (shift) cout << "Shift ";
        if (ctrl) cout << "Ctrl ";
        if (alt) cout << "Alt ";
        cout << static_cast<char>(key) << endl;
    } else {
        // Record the key release
        cout << "Key Release: ";
        if (shift) cout << "Shift ";
        if (ctrl) cout << "Ctrl ";
        if (alt) cout << "Alt ";
        cout << static_cast<char>(key) << endl;
    }

    return 0;
}
```

### Step 3: Set Up the Keyboard Hook

In the main function, set up the hook:

```c++
int main() {
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPress);

