HINSTANCE hInstance = NULL;
HHOOK hKeyboardHook = NULL;
```

### Step 3: Set Up the Keyboard Hook

In the main function, set up the keyboard hook.

```cpp
int main(int argc, char **argv) {
    // Initialize the hook
    hInstance = GetModuleHandle(nullptr);
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressed);

    // Attach the hook to all processes
    if (!SetKeyboardHook(hKeyboardHook)) {
        std::cout << "Failed to set keyboard hook." << std::endl;
        return 1;
    }

    // Start the hook
    if (!SetKeyboardHook(hKeyboardHook)) {
        std::cout << "Failed to set keyboard hook." << std::endl;
        return 1;
    }

    // Wait for events
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0) > 0) {
        if (msg.hwnd != NULL) {
            if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                // Process keyboard events
                if (msg.wParam == 0) {
                    std::cout << "Key pressed: ";
                } else {
                    std::cout << "Key released: ";
                }
                // Get the key and modifiers
                int key = msg.wParam;
                int shift = (msg.message == WM_KEYDOWN) ? 0 : GetKeyState(WM_KEYSHIFT);
                int ctrl = (msg.message == WM_KEYDOWN) ? 0 : GetKeyState(WM_CTRL);
                int alt = (msg.message == WM_KEYDOWN) ? 0 : GetKeyState(WM_ALT);

                char keyChar = 0;
                if (key < 0x20 || (key > 0x5A && key < 0x200)) {
                    keyChar = (key >> 8) | 0x00;
                } else if (key >= 0x20 && key < 0x5B) {
                    keyChar = key;
                } else if (key >= 0x5B && key < 0x60) {
                    keyChar = key - 0x20;
                } else if (key >= 0x60 && key < 0x7E) {
                    keyChar = key - 0x60 + 0x20;
                } else {
                    keyChar = 0;
                }

                std::cout << (char)keyChar << " (";
                std::cout << "Shift: " << (shift ? "Down" : "Up") << " | ";
                std::cout << "Ctrl: " << (ctrl ? "Down" : "Up") << " | ";
                std::cout << "Alt: " << (alt ? "Down" : "Up") << ")" << std::endl;
            }
        }
    }

    // Uninstall the keyboard hook
    if (UnhookKeyboard(hKeyboardHook)) {
        std::cout << "Uninstalled keyboard hook." << std::endl;
    } else {
        std::cout << "Failed to uninstall keyboard hook." << std::endl;
    }

    return 0;
}
```

### Step 4: Define the Callback Function

Here's the function to handle key events.

```cpp
void KeyPressed(int nCode, int state, int shift, int ctrl, int alt) {
    // This function is called for each key press
    // nCode is the key code
    // state is 0 for key down, 1 for key up
    // shift, ctrl, alt are whether the keys are pressed
}
```

