bool g_hookRunning = false;
std::thread g_thread;
std::mutex g_mutex;
```

### Step 3: Define the Keyboard Hook Function

Define a function `KeyboardHookProc` that handles key events.

```c++
void CALLBACK KeyboardHookProc(int h, int nCode, void* data) {
    if (!g_hookRunning) return;

    KBDLLHOOK hKeyboardHook = (KBDLLHOOK)data;

    long result = 0;
    char key = 0;

    if (nCode == HKEYDOWN || nCode == HKEYUP) {
        // Get the current key state
        bool isKeyDown = (nCode == HKEYDOWN);

        // Check if the key is a printable character
        char key = 0;
        if (isKeyDown) {
            key = ReadKey(nCode);
        }

        // Record the key press with modifiers
        if (isKeyDown) {
            // Check for modifiers
            bool shift = (GetKeyState(WORKING_DIRSHIFT) != 0);
            bool ctrl = (GetKeyState(VK_CONTROL) != 0);
            bool alt = (GetKeyState(VK_MENU) != 0);

            std::string modifiers = "";
            if (shift) modifiers += "Shift";
            if (ctrl) modifiers += "Ctrl";
            if (alt) modifiers += "Alt";

            std::string event = isKeyDown ? "pressed" : "released";
            std::string fullKey = key + modifiers + " - " + event;
            g_keyQueue.push(fullKey);
        }
    }

    return result;
}
```

### Step 4: Install the Keyboard Hook

Use `SetWindowsHook` to install the hook and specify the callback function.

```c++
int main() {
    // Initialize the hook
    g_hookRunning = true;

    // Use a dummy window to set the hook globally
    HWND hwnd = CreateWindow("DUMMY", "Keyboard Hook", WS_OVERLapped, 0, 0, 0, 0, HWND_DESKTOP, 0, WS_HIGHLIGHT, SW_SHOWNAW;
    HMODULE hMod = GetModuleHandle("kernel32.dll");
    hHook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyboardHookProc, reinterpret_cast<void*>(&hKeyboardHook));
    if (!hHook) {
        std::cerr << "Failed to set keyboard hook" << std::endl;
        return 1;
    }

    // Keep the hook running in a separate thread
    g_thread = new std::thread([this]() {
        while (g_hookRunning) {
            std::this_thread::yield();
        }
    });

    // Keep the window alive
    while (g_hookRunning) {
        Sleep(1);
    }

    // Cleanup
    UnhookWindowsHook(hHook);
    DeleteWindow(hwnd);
    g_hookRunning = false;
    g_thread.join();
    return 0;
}
```

### Step 5: Run the Program

Compile the code and run it. It will log all keyboard events to `g_keyQueue`, which you can access later.

### Step 6: Access the Keystroke Log

You can access the logged keystrokes by reading from `g_keyQueue`. Each entry includes the key and modifiers, e.g., "Shift pressed - 'A'".

### Notes:
- **Permissions**: Ensure the program runs with sufficient privileges.
- **Uninstall**: Always clean up the hook using `UnhookWindowsHook` and `DeleteWindow` to prevent memory leaks.
- **Testing**: Test different scenarios, including special keys and modifiers, to ensure all are captured.

