    } else if (code == WM_KEYUP) {
        keyboardInfo.uState = isKeyDown ? 0 : 1;
        PostMessage(hMenu, WM_KEYUP, code, 0);
        cout << "KeyUp: " << static_cast<char>(code) << endl;
        // Reset modifiers
        shift = false;
        ctrl = false;
        alt = false;
    }
}

int main() {
    // Initialize variables
    HWND hwnd = GetMainWnd();
    HHOOK hook = SetWindowsHook(WH_KEYBOARD, key_press);

    // Start the hook
    cout << "Keyboard hook installed." << endl;

    // Keep the program alive
    while (true) {
        Sleep(1);
    }

    // Uninstall the hook
    UnhookKeyboard(hook);
    cout << "Keyboard hook uninstalled." << endl;

    return 0;
}
