```cpp
#include <windows.h>
#include <user32.lib>
#include <iostream>
#include <vector>
#include <string>

using namespace std;

struct KEY_STROKE {
    uint32_t key;
    uint32_t modifiers;
    bool isPressed;
    KEY_STROKE() : key(0), modifiers(0), isPressed(false) {}
};

void keyboardCallback(int hwnd, int nCode, uint32_t key, uint32_t modifiers) {
    if (nCode != 0) return;

    uint32_t currentKey = key;
    bool isKeyDown = (modifiers & 0x20) != 0;
    bool isShift = (modifiers & 0x100) != 0;
