    cout << "Keyboard hook installed. Press any key to stop." << endl;
    while (true) {
        getchar(); // Wait for user input to stop the hook
        UninstallKeyboardHook();
        cout << "Keyboard hook removed." << endl;
        return;
    }
}

// Install the keyboard hook
void InstallKeyboardHook() {
    HHOOK hKeyHook = SetWindowsHook(WH_KEYBOARD_LL, KeyStroke);
    if (hKeyHook == NULL) {
        cout << "Failed to install keyboard hook." << endl;
    }
}

// Uninstall the keyboard hook
void UninstallKeyboardHook() {
    HHOOK hKeyHook = GetWindowHook(WH_KEYBOARD_LL, HOOK_ID);
    if (hKeyHook != NULL) {
