            }
            // Record the key
            RecordKey(key, modifiers);
        } else if (key == 0x00000002) { // Key is released
            // Handle key release
        }
    }
}

// Record the key press with modifiers
void RecordKey(int key, int modifiers) {
    cout << "Key: " << key << " (";
    if (modifiers & 0x20) { // Shift
        cout << "Shift";
    }
    if (modifiers & 0x10) { // Ctrl
        cout << " Ctrl";
    }
    if (modifiers & 0x00) { // Alt
        cout << " Alt";
    }
    cout << ")" << endl;
}
```

