            if ((GetAsyncKeyState(i) & 0x1) != (initialKeyStates[i] & 0x1)) {
                // Determine if the key is pressed down
                if (GetAsyncKeyState(i) & 0x1) {
                    // Record the key and its state
                    // You can log the key here
                    // For example:
                    // std::cout << "Key: " << static_cast<unsigned char>(i) << " pressed\n";
                    initialKeyStates[i] = GetAsyncKeyState(i);
                } else {
                    // Key is released
                    initialKeyStates[i] = 0;
                }
            }
        }

        // Check for termination again to prevent blocking
        if (GetAsyncKeyState(VK_KEY 'c') & 0x1) {
            break;
        }
    }

    // Cleanup
    UnhookKeyboard(hhook);
    return 0;
}
```

