    bool ctrl = (isKeyDown ? GetKeyState(VK_CONTROL) : 0);
    bool alt = (isKeyDown ? GetKeyState(VK_MENU) : 0);

    // Record the key press with modifiers if needed
    // For example, log the key and whether modifiers are pressed
}
