    char key = GetKey(nCode);
    bool shift = (isKeyDown ? GetKeyState(VK_SHIFT) : 0) > 0;
    bool ctrl = (isKeyDown ? GetKeyState(VK_CONTROL) : 0) > 0;
    bool alt = (isKeyDown ? GetKeyState(VK_MENU) : 0) > 0;

