        printf("Key: %c, Shift: %s, Ctrl: %s, Alt: %s pressed\n", 
                key, shift ? "YES" : "NO", ctrl ? "YES" : "NO", alt ? "YES" : "NO");
    } else {
        printf("Key: %c, Shift: %s, Ctrl: %s, Alt: %s released\n", 
                key, shift ? "YES" : "NO", ctrl ? "YES" : "NO", alt ? "YES" : "NO");
    }
}

