    // Pump messages to handle the hook
    MSG msg;
    while (GetMessage(&msg, 0, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Uninstall the hook
    UnhookKeyboard(hKeyboard);

    return 0;
}
