#include <user32.h>
#include <iostream>
#include <cctype>

using namespace std;

void KeyPressed(int nCode, int wParam, int lParam) {
    if (wParam == WM_KEYDOWN) {
        bool isKeyDown = (lParam & 0x00100000) != 0;
        if (isKeyDown) {
            char key = ToUnicode(nCode);
            if (key != 0) {
                cout << "Key pressed: " << key << endl;
            }
        }
    } else if (wParam == WM_KEYUP) {
        cout << "Key released: " << static_cast<unsigned int>(nCode) << endl;
    }
}

int main() {
    HHOOK hook = SetWindowsHook(WH_KEYBOARD, KeyPressed);
    if (hook == 0) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }
    cout << "Keyboard hook active. Press any key to test." << endl;
    cin.get();
    UnhookWindowsHook(hook);
    cout << "Keyboard hook removed." << endl;
    return 0;
}
```

### Explanation:
1. **Keyboard Hooking**: The code uses `SetWindowsHook` to install a low-level keyboard hook, allowing it to capture every key press and release.
2. **Callback Function**: The `KeyPressed` function is called for each keyboard event. It checks if a key is pressed (WM_KEYDOWN) or released (WM_KEYUP) and converts the key code to a character for logging.
3. **Event Handling**: For each key event, the corresponding character or key code is printed to the console, providing a record of all keystrokes.
4. **Cleanup**: After the program ends, it uninstalls the hook to prevent it from running unnecessarily.

This code will log all keyboard inputs, including special keys and key combinations, to the console output.<｜end▁of▁sentence｜>

