    if (!event) { // Only handle key presses
        // Get the current key state
        BYTE modifiers = GetAsyncKeyState(VkKeyScanLeft);
        BYTE modifiersPrev = GetAsyncKeyState(VkKeyScanLeft);
        // Check each modifier key
