#include <userenv.h>
#include <iostream>
#include <string>
```

**Step 2: Define the Callback Function**

Define a function that will handle keyboard events:

```cpp
void KeyPress(int nCode, int wParam, int lParam) {
    static int lastKey = 0;
    static int lastShift = 0;
    static int lastCtrl = 0;
    static int lastAlt = 0;

    if (wParam == WM_KEYDOWN) {
        // Handle key down event
        bool isKeyDown = true;
        bool shiftDown = (lParam & (1 << 5)) != 0;
        bool ctrlDown = (lParam & (1 << 6)) != 0;
        bool altDown = (lParam & (1 << 0)) != 0;

        // Check if the key is a modifier
        if (nCode >= 0x20 && nCode <= 0x2F) {
            // Modifier keys
            if (shiftDown) lastShift = 1;
            if (ctrlDown) lastCtrl = 1;
            if (altDown) lastAlt = 1;
            return;
        } else if (nCode >= 0x30 && nCode <= 0x5A) {
            // Main keys
            if (lastKey != nCode) {
                std::cout << "Key pressed: " << static_cast<int>(nCode) << " - ";
                if (shiftDown) std::cout << "Shift ";
                if (ctrlDown) std::cout << "Ctrl ";
                if (altDown) std::cout << "Alt ";
                std::cout << std::endl;
                lastKey = nCode;
            }
        } else if (nCode >= 0x60 && nCode <= 0x69) {
            // Numpad keys
            if (lastKey != nCode) {
                std::cout << "Numpad key pressed: " << static_cast<int>(nCode - 0x60) + 1 << std::endl;
                lastKey = nCode;
            }
        }
    } else if (wParam == WM_KEYUP) {
        // Handle key up event
        bool isKeyDown = false;
        bool shiftDown = (lParam & (1 << 5)) != 0;
        bool ctrlDown = (lParam & (1 << 6)) != 0;
        bool altDown = (lParam & (1 << 0)) != 0;

        if (nCode >= 0x20 && nCode <= 0x2F) {
            // Modifier keys
            if (shiftDown) lastShift = 0;
            if (ctrlDown) lastCtrl = 0;
            if (altDown) lastAlt = 0;
        }
    }
}
```

**Step 3: Set Up the Keyboard Hook**

Use `SetWindowsHook` to install the hook. This function returns a handle to the hook, which must be closed with `UnhookKeyboard` when done.

```cpp
int main() {
    HWND hwnd = GetConsoleHWND();
    int hHook = SetWindowsHook(WH_KEYBOARD, KeyPress);

    if (hHook == 0) {
        std::cout << "Keyboard hook failed to install." << std::endl;
        return 1;
    }

    // Start the hook
    while (true) {
        std::cout << "Waiting for key presses..." << std::endl;
       Sleep(1);
    }

    // Cleanup
    UnhookKeyboard(hHook);
    return 0;
}
```

**Step 4: Get the Main Window Handle**

To get the main window handle for the console application:

```cpp
HWND GetConsoleHWND() {
    HWND hwnd = GetForegroundWindow();
    if (hwnd == NULL) {
        HWND parent = GetWindow(HWND_MESSAGE, HWND_OWNER);
        if (parent != NULL) {
            hwnd = GetWindowRect(parent, &RECT());
            hwnd = GetWindow(hwnd, GW_OWNER);
        }
    }
    return hwnd;
}
```

**Step 5: Compile and Run the Code**

Save this code in a file, say `keyboard_hook.cpp`, and compile it using a compiler like Visual Studio or MinGW. Run the executable to start logging keystrokes.

**Note:**
- **Ethical Considerations:** Be cautious with this code as it can be used maliciously. Use it responsibly.
- **Performance:** The code might affect system performance, so consider stopping the hook after a certain period or when terminated.
- **Testing:** Test with different key combinations to ensure all keys are logged correctly.

