    int (*pfnKeyboardCallback) = KeyPressed;
    uint32_t thread = 0;
    uint32_t hHook = SetWindowsHook(hwnd, pfnKeyboardCallback, &thread);

    if (hHook == 0) {
        std::cout << "Failed to install keyboard hook." << std::endl;
        return 1;
