    if (keyPress == 0) {
        // No key pressed
        return;
    }

    // Convert to ASCII character
    char charKey = (char)ToUnicode(keyPress);

    // Log the keystroke
    std::cout << "Key: " << charKey << " | Shift: " << shift << " | Ctrl: " << ctrl << " | Alt: " << alt << std::endl;
}
```

