### Step-by-Step Explanation:

1. **Include Necessary Headers and Libraries:**
   - Include `windows.h` for Windows API functions.
   - Include `user32.h` for keyboard hook functions.

2. **Define the Callback Function:**
   - Create a function `OnKeyboardEvent` that takes two parameters: the event type and the key state.
   - The callback will handle both key down and up events.

3. **Initialize the Keyboard Hook:**
   - Use `SetWindowsHook` with `WH_KEYBOARD` to set up the hook.
   - Specify `HWND hwnd` as `0` to affect all windows.

4. **Log Key Presses:**
   - In the callback, check if the event is a key down event.
   - Use `GetAsyncKeyState` to get the current state of the keyboard.
   - Track the previous key state to avoid duplicate logs for sustained key holds.
   - Use `ToUnicode` to convert virtual keys to their corresponding characters.
   - Record the key and any active modifiers (Ctrl, Alt, Shift).

5. **Uninstall the Keyboard Hook:**
   - Call `UnhookKeyboard` to stop the hook after you're done logging.

6. **Handle the Hook in a Separate Thread:**
   - To prevent the UI from freezing, run the hook in a separate thread using `CreateThread`.

7. **Implement the Main Function:**
   - Initialize the hook and start the thread.
   - Wait for input using `WaitForInput` to keep the thread active.

8. **Terminate the Hook:**
   - Stop the thread and uninstall the hook to clean up resources.

Here's the complete code:

```cpp
#include <windows.h>
#include <user32.h>
#include <iostream>
#include <thread>

using namespace std;

void OnKeyboardEvent(UINT nCode, UINT wParam, DWORD *lParam);
void StartKeyboardHook();
void StopKeyboardHook();
void HandleKeyPress(int thread);

HINSTANCE hInst = NULL;

// Global variable to store the hook handle and thread
DWORD g_hook = 0;
HANDLE g_thread = NULL;

// Function prototypes
void OnKeyboardEvent(UINT nCode, UINT wParam, DWORD *lParam);
void StartKeyboardHook();
void StopKeyboardHook();
void HandleKeyPress(int thread);

// Initialize global variables
int g_key_last = 0;
int g_shift = 0;
int g_ctrl = 0;
int g_alt = 0;

// Mutex to prevent concurrent access to shared data
HANDLE g_mutex = NULL;

// Convert virtual key to char
char ToUnicode(DWORD key) {
    char buf[2] = {0};
    if (ToUnicodeEx(key, 0, buf, 2, LOCALE_USER_DEFAULT) != 1) {
        return '\0';
    }
    return buf[0];
}

void OnKeyboardEvent(UINT nCode, UINT wParam, DWORD *lParam) {
    if (wParam == KM_KEYDOWN) {
        // Key pressed
        DWORD key = *((DWORD*)lParam);
        // Check modifiers
        bool shift = (g_shift == 1);
        bool ctrl = (g_ctrl == 1);
        bool alt = (g_alt == 1);
        // Capture the key
        char key_char = ToUnicode(key);
        // Store the key and modifiers
        g_key_last = key_char;
        g_shift = shift;
        g_ctrl = ctrl;
        g_alt = alt;
        // Lock the mutex to protect against concurrent access
        HANDLE hMutex = g_mutex;
        if (hMutex != NULL) {
            WaitForSingleObject(hMutex, INFINITE);
        }
        cout << "Key Press: " << key_char;
        if (shift || ctrl || alt) {
            cout << " (Shift, Ctrl, or Alt is pressed)";
        }
        cout << endl;
    } else if (wParam == KM_KEYUP) {
        // Key released
        // Reset the modifiers
        g_shift = 0;
        g_ctrl = 0;
        g_alt = 0;
        // Unlock the mutex
        if (hMutex != NULL) {
            ReleaseMutex(hMutex);
        }
    }
}

void StartKeyboardHook() {
    g_hook = SetWindowsHook(WH_KEYBOARD, OnKeyboardEvent);
    if (g_hook == 0) {
        cout << "Failed to install keyboard hook." << endl;
    } else {
        // Start a separate thread to handle the hook
        if (g_thread) {
            TerminateThread(g_thread);
        }
        g_thread = CreateThread(0, 0, HandleKeyPress, 0);
    }
}

void StopKeyboardHook() {
    if (g_hook != 0) {
        UnhookKeyboard(g_hook);
        g_hook = 0;
    }
    if (g_thread) {
        TerminateThread(g_thread);
        g_thread = NULL;
    }
    if (g_mutex != NULL) {
        DestroyHandle(g_mutex);
        g_mutex = NULL;
    }
}

void HandleKeyPress(int thread) {
    while (true) {
        Sleep(1); // Sleep to prevent high CPU usage
        StartKeyboardHook();
        WaitForInput();
    }
}

int main() {
    // Initialize the mutex
    g_mutex = CreateMutex(NULL, 0, "KeyboardHook");
    // Start the hook
    StartKeyboardHook();
    while (true) {
        Sleep(1);
    }
    return 0;
}
