#include <user32.h>
#include <iostream>

using namespace std;

HHOOK hKeyboardHook = NULL;

static DWORD lastKeyState = 0;
static HINSTANCE hInstance = NULL;

bool CALLBACK KeyDownCallback(int nCode, WPARAM wParam, LPARAM lParam) {
