            bool ctrl = GetAsyncKeyState(0x10);
            bool alt = GetAsyncKeyState(0xA0);

            // Log the key and modifiers
            std::cout << "Key: " << key << " | Shift: " << shift << " | Ctrl: " << ctrl << " | Alt: " << alt << std::endl;
        }
    }
}
```

### Step 4: Set Up the Keyboard Hook
Install the keyboard hook using `SetWindowsHook`:
```c
int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hHook = SetWindowsHook(hwnd, WH_KEYBOARD, KeyHookProc);

    // Start the hook
    while (true) {
        Sleep(1);
    }

    // Uninstall the hook
    UnhookWindowsHook(hwnd, hHook);
    return 0;
}
```

