#include <windows.h>
#include <User32.h>
#include <iostream>
#include <ctime>
#include <fstream>

using namespace std;

struct KeyEvent {
    char key;
    bool ctrl;
    bool shift;
    bool alt;
    DWORD time;
};

void KeyPressCallback(int h, int nCode, DWORD dwState, DWORD dwExtraInfo, void* userData) {
    KeyEvent ke;
    bool isKeyDown = (dwState & 0x1) != 0;
    bool isRepeated = (dwState & 0x2) != 0;

