       std::cerr << "Failed to install keyboard hook" << std::endl;
       return 1;
   }
   ```

5. **Run the Hook**: Start the hook and wait for events.
   ```cpp
   MSG msg;
   while (GetMessage(&msg, hwnd, 0, 0)) {
       TranslateMessage(&msg);
       DispatchMessage(&msg);
   }
   ```

6. **Uninstall the Hook**: Properly release the hook to clean up resources.
   ```cpp
   if (UnhookWindowsHook(dw)) {
       std::cout << "Uninstalled keyboard hook" << std::endl;
   } else {
       std::cerr << "Failed to uninstall keyboard hook" << std::endl;
   }
   ```

7. **Compile and Execute**: Compile the code into an executable and run it.

### Full Code

```cpp
#include <windows.h>
#include <user32.h>
#include <iostream>
#include <cstdlib>
#include <ctime>

using namespace std;

static LRESULT CALLBACK KeyPressCallback(int nCode, UINT wEvent, DWORD dwParameters, HANDLE hwnd) {
    static int lastKey = 0;
    KBDLLHOOK lastEvent = 0;

    if (wEvent == WM_KEYDOWN) {
        char key = GetAsyncKeyState(0x1);
        if (key != lastKey) {
            cout << "Key pressed: " << (char)key << endl;
            lastKey = key;
        }
    } else if (wEvent == WM_KEYUP) {
        char key = GetAsyncKeyState(0x1);
        if (key == lastKey) {
            cout << "Key released: " << (char)key << endl;
            lastKey = 0;
        }
    }
    return 0;
}

int main() {
    DWORD dw;
    dw = SetWindowsHook(WH_KEYBOARD, KeyPressCallback);
    if (dw == 0) {
        cerr << "Failed to install keyboard hook" << endl;
        return 1;
    }

    HWND hwnd = GetMainWnd();
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    if (UnhookWindowsHook(dw)) {
        cout << "Uninstalled keyboard hook" << endl;
    } else {
        cerr << "Failed to uninstall keyboard hook" << endl;
    }

    return 0;
}
```

### Explanation

This code installs a keyboard hook using the `SetWindowsHook` function, which allows your application to receive notifications about keyboard events. The `KeyPressCallback` function is invoked for each key press and release, logging the keys to the console. The hook is then properly uninstalled to free up resources. This approach ensures that all keyboard inputs are captured, including special keys and modifier states, providing a comprehensive logging system.<｜end▁of▁sentence｜>

