    // Build the key string
    string key_str = "(" + key_char + ")";
    if (!shift.empty()) {
        key_str += " + " + shift;
    }
    if (!ctrl_state && !alt_state) {
        if (!shift.empty()) {
            key_str += " + ";
        }
        if (!ctrl_state.empty()) {
            key_str += "Ctrl";
        }
        if (!alt_state.empty()) {
            key_str += "Alt";
        }
    } else if (ctrl_state && alt_state) {
        key_str += " + Ctrl + Alt";
    } else if (ctrl_state) {
        key_str += " + Ctrl";
    } else if (alt_state) {
        key_str += " + Alt";
    }

    // Output the key stroke
    cout << "Key stroke: " << key_str << endl;
}

void Unhook() {
    HHOOK hKeyboard = GetWindowHook(hwnd);
    if (hKeyboard) {
        UnhookWindowsHook(hKeyboard);
    }
}

// Function to get the key name from its virtual key code
char GetKey(int key) {
    char key_char;
    GetUnicodeChar(key, &key_char);
    return key_char;
}
