   - Create a function `KeyboardCallback` that receives keyboard events. It will check if the event is a key press and record the key and modifiers.

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to install a keyboard hook. This will call `KeyboardCallback` on each key event.

4. **Handle Key Press Events:**
   - In `KeyboardCallback`, check if the event is a key press (`dwParam == WM_KEYDOWN`). Use `GetAsyncKeyState` to get the state of modifier keys (Shift, Ctrl, Alt) and the pressed key.

5. **Log the Keystroke:**
   - Convert the key to a character using `ToUnicode` and log it, along with the modifiers if applicable.

6. **Uninstall the Hook:**
   - Use `UnhookKeyboard` to remove the hook after the program ends to release system resources.

### Sample Code:

```c++
#include <Windows.h>
#include <User32.h>
#include <iostream>
using namespace std;

void KeyboardCallback(int hImgmer, int nCode, DWORD dwState, DWORD dwExtraInfo, DWORD dwUser, DWORD *lpUserData, int ihook);
void StartKeyboardHook();
void StopKeyboardHook();

void KeyboardCallback(int hImgmer, int nCode, DWORD dwState, DWORD dwExtraInfo, DWORD dwUser, DWORD *lpUserData, int ihook) {
    if (nCode == HC_KEYDOWN) {
        // Check if key is pressed
        bool isKeyDown = (dwState & 0x1) != 0;
        // Use GetAsyncKeyState to check modifiers
        int modifiers = GetAsyncKeyState(0x20); // Check Shift, Ctrl, etc.
        if (isKeyDown) {
            // Get the key pressed
            int key = GetKey(nCode);
            // Convert to char
            char ch = ToUnicode(key);
            // Log the keystroke
            cout << "Key pressed: " << ch << endl;
            if (modifiers) {
                cout << "Modifiers: " << modifiers << endl;
            }
        }
    }
    return 0;
}

void StartKeyboardHook() {
    HHOOK hhook = SetWindowsHook(WH_KEYBOARD, KeyboardCallback);
    if (hhook == NULL) {
        cout << "Failed to install keyboard hook" << endl;
    }
}

void StopKeyboardHook() {
    HHOOK hhook = GetWindowsHook(WH_KEYBOARD);
    if (hhook) {
        Unhook(hhook);
        cout << "Keyboard hook removed" << endl;
    }
}

int main() {
    StartKeyboardHook();
    // Keep the program running to capture keystrokes
    cin.get();
    StopKeyboardHook();
    return 0;
}
```

