#include <windows.h>
#include <user32.lib>
#include <stdio.h>

void KeyPressCallback(int hInserting, int nKeysDown) {
    if (nKeysDown != 0) {
        // Key is pressed
        char key = GetAsyncKeyState(0x7F); // Check for each key
        // Convert key to character
        char c = ToUnicode(key);
        // Write to file or display
        printf("Key pressed: %c\n", c);
    }
}

